INSERT INTO legal_documents (id,title,original_title,document_type,year_bs,year_ad,total_pages,nodes,source_filename) VALUES ($CODEx2d17f975f0$doc_0_it7vg66_pdf$CODEx2d17f975f0$,$CODExd9230536c3$मलु कु ी अपराध संहिता, २०७४$CODExd9230536c3$,NULL,$CODEx76f3b5a717$act$CODEx76f3b5a717$,0,0,122,$CODExd7ea9e8908$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "www.lawcommission.gov.np\nमलु कु ी अपराध संहिता, २०७४\nप्रमाणीकरण र प्रकाशन मममत\n२०७४।0६।३०\nसंशोधन गने ऐन", "children": []}, {"tier": 1, "nodeType": "section_group", "identifier": "Sections", "title": "Sections", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "१", "title": "मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई", "content": "संशोधन गने ऐन, २०७५ २०७६।०१।०२", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२", "title": "फौजदारी कसूर तथा फौजदारी कार्हयिमध सम्बन्धी", "content": "के िी ऐन संशोधन गने ऐन, २०७९ २०७9।03।31", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३", "title": "र्ौन हिंसा हिरुद्धका के िी ऐनलाई संशोधन गने ऐन, २०७९ २०७९।0३।३१", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४", "title": "मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई", "content": "संशोधन गने ऐन, २०८० २०८०।०४।१२", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५", "title": "सम्पत्ति शद्धु ीकरण (मनी लाउण्डररङ्ग) मनिारण तथा", "content": "व्र्ािसाहर्क िातािरण प्रिद्धयन सम्बन्धी के िी ऐनलाई\nसंशोधन गने ऐन, २०८० २०८०।१२।३०\nसम्ित ् २०७४ सालको ऐन नं. ३६\nप्रस्तािनााः मलु कु मा कानून तथा व्र्िस्था कार्म गरी सिसय ाधारणको नैमतकता, त्तशष्टाचार, सदाचार,\nसहुिधा, आमथकय हित कार्म राख् न, हिमिन् न धाममकय तथा सााँस्कृ मतक समदु ार् बीचको ससु म्बन्ध\nतथा शात्तन्त कार्म गन,य फौजदारी कसूर मनिारण र मनर्न्रण गन य र तत्सम्बन्धी प्रचमलत\nकानूनलाई संशोधन र एकीकरण गरी समर्ानकु ू ल फौजदारी कसूर सम्बन्धी संहिताको व्र्िस्था\nगन य िाञ्छनीर् िएकोले,\nनेपालको संहिधानको धारा २९६ को उपधारा (१) बमोत्तजमको व्र्िस्थाहपका–संसदले\nर्ो ऐन बनाएको छ।\n1\nwww.lawcommission.gov.np\nिाग-1\nसामान्र् प्रािधानिरु\nपररच्छेद-१\nप्रारत्तम्िक\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१", "title": "संत्तिप्त नाम र प्रारम्िाः (१) र्स ऐनको नाम “मलु कु ी अपराध संहिता, २०७४”", "content": "रिेकोछ।\n(२) र्ो संहिता संित ् २०७५ साल िदौ १ गतेदेत्ति प्रारम्ि िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२", "title": "संहिताको बहििरे ीर् प्रर्ोगाः (१) कसैले नेपाल बाहिर देिार्को कुनै कसूर गरेमा", "content": "मनजलाई नेपालमिर नै त्र्स्तो कसूर गरे सरि र्स संहिता बमोत्तजम सजार् िनु ेछाः–\n(क) दफा ५४ बािेक िाग २ को पररच्छेद १ अन्तगतय को कसूर,\n(ि) नेपालबाट कुनै व्र्त्तिलाई अपिरण गरी िाग २ पररच्छेद १७\nअन्तगतय गरेको कसूर,\n(ग)  दफा १४६क. र १६७, २७६ र २७९ अन्तगतय को कसूर,\n(घ) नेपालमिर चलनचल्तीमा ल्र्ाउने िा पैठारी गने उद्देश्र्ले गरेको\nिाग २ पररच्छेद २२ र २३ अन्तगतय का कसूर,\n(ङ) नेपाल सरकार, प्रदेश सरकार िा स्थानीर् ति िा नेपाल सरकार,\nप्रदेश सरकार िा स्थानीर् तिको पूण य िा अमधकांश स्िाममत्ि िा\nमनर्न्रणमा रिेको कुनै सङ्गठठत संस्थाको कुनै पदीर् िैमसर्तमा\nकार् य सम्पादन गदाय गरेको र्स ऐन अन्तगतय को कसूर।\n(२) कसैले नेपालमा दताय िएको िार्र्ु ान िा जलर्ानमिर र्स ऐन अन्तगतय को\nकुनै कसूर नेपाल बाहिर रिाँदाका बित गरेमा मनजलाई नेपालमिर नै त्र्स्तो कसूर गरे\nसरि र्स ऐन बमोत्तजम सजार् िनु ेछ।\n(३) कुनै नेपाली नागररक िा अन्र् कसैले नेपाल बाहिर कुनै नेपाली नागररक\nहिरुद्ध देिार्को कुनै कसूर गरेमा मनजलाई नेपालमिर नै त्र्स्तो कसूर गरे सरि र्स ऐन\nबमोत्तजम सजार् िनु ेछाः–\n(क) ज्र्ान मलएको िा ज्र्ान मलने उद्योग, दरुु त्सािन िा षड् र्न्र गरेको\nकसूर,\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n सम्पत्ति शद्धु ीकरण (मनी लाउण्डररङ्ग) मनिारण तथा व्र्ािसाहर्क िातािरण प्रिद्धयन सम्बन्धी के िी ऐनलाई\nसंशोधन गने ऐन, २०८० द्वारा संशोमधत।\n2\nwww.lawcommission.gov.np\n(ि) असिार् व्र्त्तिलाई पररत्र्ाग गरेको कसूर,\n(ग) अङ्गिङ्ग गरेको कसूर,\n\n(ग१) दफा १९२क. बमोत्तजमको कसूर,\n(घ) अपिरण, शरीर बन्धक िा गैरकानूनी थनु ामा रािेको कसूर,\n(ङ) जिजस्य ती करणी िा िाडनाता करणी गरेको कसूर,\n(च) नेपाल सरकार, प्रदेश सरकार िा स्थानीर् तिको िा नेपाल\nसरकार, प्रदेश सरकार िा स्थानीर् तिको पूण य िा अमधकांश\nस्िाममत्ि िा मनर्न्रण िएको सङ्गठठत संस्था हिरुद्ध आपरामधक\nउपद्रि, आपरामधक लाि, आपरामधक हिश्ि ासघात, कीते, चोरी, ठगी,\nडााँका िा सम्पत्तिको आपरामधक उपर्ोग गरेको कसूर,\n(छ) दफा १५८ अन्तगतय को कसूर,\n(ज) िाग २ पररच्छेद ११ अन्तगतय का हििाि सम्बन्धी कसूर,\n(झ) नेपालमिर पैठारी गने उद्देश्र्ले िाद्य पदाथ य िा औषमधमा ममसािट\nगरेको कसूर,\n(ञ) दफा २३१, २३२ र २३३ अन्तगतय का इलाज सम्बन्धी कसूर,\n(ट) िाग ३ को पररच्छेद २ अन्तगतय को कसूर।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३", "title": "पररिाषााः हिषर् िा प्रसङ्गले अको अथ य नलागेमा र्स ऐनमा,–", "content": "(क) “अदालत” िन् नाले सिोच्च अदालत, उच्च अदालत िा त्तजल्ला अदालत\nसम्झन ु पछ य र सो शब्दले कुनै िास हकमसमका फौजदारी मद्दु ाको\nकारबािी र हकनारा गन य कानून बमोत्तजम अमधकारप्राप्त अदालत, अन्र्\nन्र्ाहर्क मनकार् िा अमधकारी समेतलाई जनाउाँछ।\n(ि) “आश्रर् ठदने” िन् नाले कुनै व्र्त्तिलाई िान, हपउन, बस्न, नगदी, त्तजन्सी,\nलिा कपडा, िातिमतर्ार िा सिारीको साधन ठदने िा पक्राउबाट िच्न िा\nअन्र् सिार्ता ठदने काम सम्झन ु पछ।य\n(ग) “कसूर” िन् नाले र्स संहिता िा कानून बमोत्तजम सजार् िनु े काम सम्झन ु\nपछ।य\n(घ) “कानून” िन् नाले तत्काल प्रचमलत कानून सम्झन ु पछ।य\n फौजदारी कसूर तथा फौजदारी कार्हयिमध सम्बन्धी के िी ऐन संशोधन गने ऐन, २०७९ द्वारा थहपएको।\n3\nwww.lawcommission.gov.np\n(ङ) “काम” िन् नाले कामिरुको समूि सम्झन ु पछ य र सो शब्दले कानून\nबमोत्तजम गन यु पनेमा नगरेको िा गन य निनु ेमा गरेको काम समेतलाई\nजनाउाँछ।\n(च) “गम्िीर कसूर” िन् नाले तीन िषिय न्दा बढी दश िषसय म्म कै द सजार् िनु े\nकसूर सम्झन ु पछ।य\n(छ) “जघन्र् कसूर” िन् नाले जन्मकै द िा दश िषिय न्दा बढी कै द सजार् िनु े\nकसूर सम्झन ु पछ।य\n(ज) “ज्र्ान” िन् नाले मामनसको ज्र्ान सम्झन ु पछय।\n(झ) “न्र्ार्ाधीश” िन् नाले मद्दु ाको कारबािी, सनु िु ाई र हकनारा गने अदालतको\nअमधकारी सम्झन ु पछ य र सो शब्दले कुनै िास हकमसमका फौजदारी\nमद्दु ाको कारबािी, सनु िु ाई र हकनारा गने अमधकारप्राप्त अमधकारी समेतलाई\nजनाउाँछ।\n(ञ) “राष्‍ट रसेिक” िन् नाले देिार्को कुनै व्र्त्ति सम्झन ु पछयाः–\n(१) संहिधान िा अन्र् कानून बमोत्तजम सािजय मनक जिाफदेिीको पदमा\nमनिायत्तचत, मनोमनत िा मनर्िु िएको व्र्त्ति,\n(२) कानून िा करार बमोत्तजम नेपाल सरकार िा प्रदेश सरकारको\nसेिामा िा अन्र् कुनै सरकारी सेिामा मनर्िु िएको व्र्त्ति,\n\n(३) स्थानीर् ति िा त्तजल्ला समन्िर् समममतको कुनै पद िा सेिामा\nमनिायत्तचत, मनोनीत िा मनर्िु िएको व्र्त्ति,\n(४) नेपाल सरकार, प्रदेश सरकार िा स्थानीर् तिको पूण य िा अमधकांश\nस्िाममत्ि िा मनर्न्रण िएको सङ्गठठत संस्थाका पदामधकारी िा\nत्र्स्तो संस्थाको सेिामा मनर्िु िएको व्र्त्ति, िा\n(५) सािजय मनक जिाफदेिी िएको पदमा अन्र् कुनै हकमसमले मनर्िु\nिएको िा ििाल रिेको व्र्त्ति।\n(ट) “स्थानीर् ति” िन् नाले गाउाँपामलका िा नगरपामलका सम्झन ु पछ।य\n(ठ) “सङ्गठठत संस्था” िन् नाले कुनै कानून बमोत्तजम स्थाहपत िा कानून\nबमोत्तजम दताय िएको संस्था सम्झन ु पछ।य\n(ड) “संहिधान” िन् नाले नेपालको संहिधान सम्झन ु पछ।य\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n4\nwww.lawcommission.gov.np\n(ढ) “सािजय मनक मलित” िन् नाले देिार्को कुनै मलित सम्झन ु पछयाः–\n(१) हिधाहर्काबाट पाररत िएको मलित,\n(२) संहिधान बमोत्तजम राष्‍ट रपमतबाट िएको औपचाररक कार्कय ो\nअमिलेिको रुपमा रिेको मलित,\n\n(२क) संहिधान बमोत्तजम प्रदेश प्रमिु बाट िएको औपचाररक कार्कय ो\nअमिलेिको रुपमा रिेको मलित,\n(३) नेपाल सरकार, प्रदेश सरकार िा स्थानीर् ति िा नेपाल सरकार,\nप्रदेश सरकार िा स्थानीर् ति अन्तगतय का कार्ायलर् िा\nसंिैधामनक मनकार् िा पदामधकारी, अदालत िा ऐन िा आदेशद्वारा\nस्थाहपत संस्था, नेपाल सरकारको पूण य िा अमधकांश स्िाममत्ि िा\nमनर्न्रणमा रिेको सङ्गठठत संस्थाको कार्ायलर्ले जारी गरेको िा\nत्र्स्ता कार्ायलर्मा अमिलेिको रुपमा रिने हकताब, श्रेस्ता िा\nअन्र् कुनै मलित,\n\n(३क) संघीर्, प्रदेश िा स्थानीर् कानून बमोत्तजम जारी िएको कुनै\nमलित,\n(४) अदालतबाट िएको फै सला, मनणर्य िा आदेश।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४", "title": "सामान्र् रुपमा लागू िनु े मसद्धान्त र व्र्िस्थािरुाः र्स संहिताको िाग १ को पररच्छेद–", "content": "\n२, ३, ४ र ५ बमोत्तजमका मसद्धान्त र व्र्िस्थािरु र्स संहिता र अन्र् ऐन अन्तगतय का\nकसूरका सम्बन्धमा सामान्र्ताः लागू िनु े छन।्", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५", "title": "हिशेष ऐनको व्र्िस्था लागू िनु ेाः कुनै िास कामलाई कुनै हिशेष ऐनद्वारा छुट्टै कसूर", "content": "मानी सजार् गने व्र्िस्था िएको रिेछ िने त्र्स्तो कसूरका सम्बन्धमा सोिी ऐन लागू\nिनु ेछ।\nपररच्छेद-२\nफौजदारी न्र्ार्का सामान्र् मसद्धान्तिरु", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६", "title": "कानून बमोत्तजमको काम कसूर निनु ेाः कानून बमोत्तजम गन यु पने िा कानूनले िम्र् मानेको", "content": "कामलाई कसूर मामनने छैन।\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा थप।\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n5\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७", "title": "कानून बमोत्तजम बािेक सजार् निनु ेाः कानूनले सजार् निनु े कुनै काम गरे बापत कुनै", "content": "व्र्त्ति सजार्को िागी िनु े छैन र कुनै पमन व्र्त्तिलाई कसूर गदायको अिस्थामा\nकानूनमा तोहकएिन्दा बढी सजार् िनु े छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८", "title": "तथ्र्को भ्रममा परी गरेको काम कसूर निनु ेाः तथ्र्को भ्रममा परी कानून बमोत्तजम गन यु", "content": "पने िा िम्र् मामनएको हिश्ि ास गरी असल मनर्तले गरेको कुनै काम कसूर मामनने\nछैन।\nतर कानूनको अनमिज्ञतामा गरेको काम िम्र् िनु े छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९", "title": "एउटै कसूरमा दोिोरो सजार् निनु ेाः कुनै व्र्त्ति हिरुद्ध अदालतमा एकै कसूरमा एक", "content": "पटकिन्दा बढी मद्दु ा चलाइने र सजार् गररने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१०", "title": "स्िच्छ सनु िु ाईबाट ित्तित निनु ेाः कुनै व्र्त्ति सिम अदालत िा न्र्ाहर्क मनकार्बाट िनु े", "content": "कारबािीमा स्िच्छ सनु िु ाईबाट ित्तित िनु े छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "११", "title": "आफ्नो हिरुद्ध सािी िनु कर नलागनेाः कुनै कसूरको अमिर्ोग लागेको व्र्त्तिलाई आफ्नो", "content": "हिरुद्ध सािी िनु कर लागने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२", "title": "कसूर प्रमात्तणत निएसम्म कसूरदार नमामननेाः कुनै कसूरको अमिर्ोग लागेको व्र्त्तिलाई", "content": "त्र्स्तो कसूर गरेको प्रमात्तणत निएसम्म कसूरदार मामनने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३", "title": "बालबामलकाले गरेको काम कसूर निनु ेाः दश िष य उमेर नपगु ेको बालबामलकाले गरेको", "content": "कुनै काम कसूर मामनने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४", "title": "िोस ठेगानमा नरिेको व्र्त्तिले गरेको काम कसूर नमामननेाः कुनै काम गदायका बित", "content": "मानमसक अस्िस्थताको कारणले त्र्स्तो कामको प्रकृ मत, गणु , दोष िा पररणाम बझ्ु न\nनसक्ने गरी िोस ठेगानमा नरिेको व्र्त्तिले गरेको काम कसूर मामनने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५", "title": "मञ्ज रु ी मलई गरेको काम कसूर निनु ेाः ज्र्ान मलने िा अङ्गिङ्ग गने मनर्तले िा ज्र्ान", "content": "जान िा अङ्गिङ्ग िनु सक्छ िन् ने थािा िई गरेकोमा बािेक कसैले अठार िष य मामथको\nकुनै व्र्त्तिको मञ् जरु ी मलई गरेको कुनै कामबाट त्र्स्तो मञ् जरु ी ठदने व्र्त्तिलाई कुनै\nिमत पगु न गएमा सो काम कसूर मामनने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६", "title": "िलाईका लामग मञ्ज रु ी मलई गरेको काम कसूर निनु ेाः कसैले कुनै व्र्त्तिको िलाईका", "content": "लामग मनजको मञ् जरु ी मलई असल मनर्तले िोमसर्ारी साथ गरेको कुनै कामबाट त्र्स्तो\nमञ् जरु ी ठदने व्र्त्तिलाई िमत पगु न गएमा त्र्स्तो काम कसूर मामनने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७", "title": "िलाईका लामग संरिकको मञ्ज रु ी मलई गरेको काम कसूर निनु ेाः अठार िष य ननाघेको िा", "content": "मानमसक अस्िस्थताको कारणले िोस ठेगानमा नरिेको व्र्त्तिको िलाईका लामग मनजको\nसंरिकले िा त्र्स्तो संरिकको मञ् जरु ी मलएर अरु कसैले असल मनर्तले िोमसर्ारी साथ\n6\nwww.lawcommission.gov.np\nगरेको कुनै कामबाट त्र्स्तो व्र्त्तिलाई कुनै िमत पगु न गएमा त्र्स्तोेे काम कसूर\nमामनने छैन।\nतर ज्र्ान जान िा अङ्गिङ्ग िनु बाट रोक्ने उद्देश्र्ले गरेकोमा बािेक ज्र्ान जान\nसक्छ िा अङ्गिङ्ग िनु सक्छ िन् ने जानीजानी त्र्स्तो कुनै काम गने व्र्त्तिले आपरामधक\nदाहर्त्िबाट छुट पाउने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८", "title": "िलाईका लामग मञ्ज रु ी नमलई गरेको काम कसूर निनु ेाः कुनै व्र्त्तिको िलाईका लामग", "content": "तत्काल कुनै काम नगरी निनु े िएको, त्र्स्तो व्र्त्ति कुनै कारणले त्र्स्तो काम गन य\nठदनको लामग तत्काल आफै मञ् जरु ी ठदन नसक्ने अिस्थामा रिेको र मनजको तफय बाट\nमञ् जरु ी ठदन सक्ने संरिक पमन तत्काल उपलब्ध निएको अिस्थामा मनजको िलाईका\nलामग मञ्ज रु ी नमलएर पमन असल मनर्तले िोमसर्ारी साथ त्र्स्तो काम गदाय मनजलाई कुनै\nिमत िा िामन, नोक्सानी पगु न गएमा त्र्स्तो काम कसूर मामनने छैन।\nस्पष्‍ट टीकरणाः दफा १६, १७ र र्स दफाको प्रर्ोजनका लामग “िलाई” िन्नालेाः\n(क) आमथकय रुपमा प्राप्त लािलाई जनाउने छैन,\n(ि) ज्र्ान मलने िा मनामसब कारण हिना अङ्गिङ्ग गने मनर्तले गरेको कामलाई\nजनाउने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९", "title": "मञ्ज रु ी मलएर गरेको िए पमन कसूर मामननेाः दफा १५, १६ िा १७ मा जनु सकु ै कुरा", "content": "लेत्तिएको िए तापमन ती दफािरुमा लेत्तिएको काम कानून बमोत्तजम अन्र् कसूर मामनने\nिएमा त्र्स्तो काम मञ् जरु ी मलएर गरेको िए पमन कसूर मामननेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२०", "title": "मञ्ज रु ीाः मञ्ज रु ी मौत्तिक िा मलत्तित रुपमा िा इशारा िा आचरणद्वारा व्र्ि गन य", "content": "सहकनेछ।\nतर देिार्का अिस्थामा ठदइएको मञ् जरु ीलाई मञ् जरु ी मामनने छैनाः–\n(क) तथ्र्को भ्रममा परी िा कुनै हकमसमको िामन, नोक्सानी िनु सक्ने\nडर, रासमा परी कुनै व्र्त्तिले मञ् जरु ी ठदएको र त्र्स्तो मञ् जरु ी\nअनसु ार काम गने व्र्त्तिलाई त्र्स्तो मञ् जरु ी त्र्सरी ठदइएको िो\nिन् ने कुरा थािा िएमा िा मनजले हिश्ि ास गन यु पने कुनै मनामसब\nकारण िएमा,\n(ि) मानमसक अस्िस्थताको कारणले आफू ले ठदएको मञ् जरु ीको गणु ,\nदोष र पररणाम बझ्ु न नसक्ने गरी िोस ठेगानमा नरिेका बित\nकुनै व्र्त्तिले मञ् जरु ी ठदएकोमा,\n(ग) अठार िष य ननाघेको बालबामलकाले मञ् जरु ी ठदएकोमा,\n7\nwww.lawcommission.gov.np\n(घ) अनत्तुचत प्रिािमा परी मञ् जरु ी ठदएकोमा।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२१", "title": "असल मनर्तले ठदएको जानकारीबाट िमत पगु मे ा कसूर निनु ेाः कसैले कुनै व्र्त्तिलाई", "content": "मनजको िलाईको लामग असल मनर्तले ठदएको कुनै कुराको सूचना िा जानकारीबाट\nत्र्स्तो व्र्त्तिलाई कुनै िमत पगु न गएमा त्र्स्तो काम कसूर मामनने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२२", "title": "डर रासमा परी गरेको काम कसूर निनु ेाः (१) कसैले जोत्तिमी िातिमतर्ार िा हिषाल ु िा", "content": "हिष्‍टफोटक पदाथ य मलई कुनै व्र्त्तिलाई मनजले तत्काल कुनै काम नगरे मनज िा मनजको\nनत्तजकको नातेदारको ज्र्ान मलने िा शारीररक अङ्गिङ्ग गराउने डर रास देिाएको र\nतत्काल त्र्स्तो काम नगरे आफ्नो िा आफ्नो नत्तजकको नातेदारको ज्र्ान जान िा\nशारीररक अङ्गिङ्ग िनु सक्ने ितरा छ िनी हिश्ि ास गन यु पने मनामसब कारण िई त्र्स्तो\nव्र्त्तिले गरेको त्र्स्तो काम कसूर मामनने छैन।\nतर देिार्को अिस्थामा त्र्स्तो काम कसूर मामनने छाः-\n(क) ज्र्ान मलएको िा शारीररक अङ्गिङ्ग गरेकोमा,\n(ि) जिजस्य ती करणी गरेकोमा,\n(ग) राज्र् हिरुद्धको कसूर गरेकोमा, िा\n(घ) त्र्स्तो काम गने व्र्त्ति आफैँ ले गदाय िा आफू ले कुनै काम\nगरेको कारणबाट मनज त्र्स्तो डर रासको अिस्थामा पगु ेकोमा।\n(२) उपदफा (१) बमोत्तजम डर, रासमा पारी कसूर गराउने व्र्त्तिलाई मनज\nआफैँ ले त्र्स्तो कसूर गरे सरि कानून बमोत्तजम सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२३", "title": "अन्र् िामन, नोक्सानीबाट बचाउन असल मनर्तले गरेको काम कसूर निनु ेाः कसैलाई कुनै", "content": "िामन, नोक्सानी िनु े कुनै काम तत्काल नगरे आफ्नो िा अरु कसैको जीउ, ज्र्ान िा\nसम्पत्तिमा त्र्सिन्दा ठूलो िामन, नोक्सानी िनु े मनत्तित िई आपरामधक मनर्त हिना र\nसंिाहित ठूलो िामन, नोक्सानी रोक्ने िा टाने उद्देश्र्ले असल मनर्तले त्र्स्तो िामन,\nनोक्सानी िनु े काम गरेमा िामन पगु न सक्छ िन् ने जानीजानी गरेको कारणले मार त्र्स्तो\nकाम कसूर मामनने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२४", "title": "मनजी रिाको लामग गरेको काम कसूर नमामननेाः (१) र्स पररच्छेदको अधीनमा रिी मनजी", "content": "रिाको अमधकार प्रर्ोग गदाय िए गरेको कुनै काम कसूर मामनने छैन।\n(२) प्रत्र्ेक व्र्त्तिलाई आफ्नो िा अरु कसैको त्तजउ, ज्र्ान िा सम्पत्तिलाई कुनै\nगैर कानूनी िमतबाट बचाउने अमधकार िनु ेछ।\n(३) र्स दफा बमोत्तजम मनजी रिाको अमधकार प्रर्ोग गदाय तत्काल कुनै काम\nनगरेमा आफ्नो िा अरु कसैको जीउ, ज्र्ान िा सम्पत्तिलाई कुनै गैर कानूनी िमतबाट\n8\nwww.lawcommission.gov.np\n\nबचाउन सहकदैन िन् ने मनामसब हिश्ि ास िएमा िा हिश्ि ास गन यु पने मनामसब कारण\nिएमा मार प्रर्ोग गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२५", "title": "मनजी रिाको अमधकारमा बन्देजाः (१) दफा २४ मा जनु सकु ै कुरा लेत्तिएको िए तापमन", "content": "देिार्को अिस्थामा िा कामका हिरुद्ध मनजी रिाको अमधकार प्राप्त िनु सक्ने छैनाः-\n(क) कसैको त्तजउ िा सम्पत्तिमा गैर कानूनी िमत पर्ु ाउय ने काम िाँदु ाका\nबित त्र्स्तो िमतबाट बचाउन तत्काल सािजय मनक अमधकारीको\nसंरिण िा मद्दत उपलब्ध िनु े िा िनु सक्ने अिस्था िएकोमा,\n(ि) जसको त्तजउ िा सम्पत्तिमा िमत पगु ेको िो त्र्स्तो व्र्त्तिले नै\nिमत पर्ु ायउने व्र्त्तिलाई उिेत्तजत गरेको कारणबाट त्र्सरी िमत\nपगु ेकोमा,\n(ग) अदालतको फै सला िा आदेश अनसु ार कुनै राष्‍ट रसेिकले असल\nमनर्तले कुनै काम गरेकोमा,\n(घ) कुनै राष्‍ट रसेिकले आफ्नो पदीर् अमधकारको प्रर्ोगमा असल\nमनर्तले कुनै काम गरेकोमा,\n(ङ) कुनै राष्‍ट रसेिकले आफ्नो पदीर् अमधकारको प्रर्ोगमा असल\nमनर्तले ठदएको मनदेशन अनसु ार कसैले कुनै काम गरेकोमा।\n(२) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापमन देिार्को अिस्थामा\nकुनै व्र्त्ति मनजी रिाको अमधकारबाट बत्तित िनु े छैनाः-\n(क) उपदफा (१) को िण्ड (ग) मा उत्तल्लत्तित काम गने व्र्त्ति\nराष्‍ट रसेिक िो र मनज अदालतको फै सला िा आदेशानसु ार काम\nगदैछ िन् ने कुरा जानकारी िनु े िा हिश्ि ास गने मनामसब कारण\nनिएमा िा मनजको पररचर् िा सो काम गन य पाएको अमधकारपर\nमाग गदाय पमन मनजले आफ्नो पररचर् नठदएमा िा त्र्स्तो काम\nगन य पाएको अमधकारपर नदेिाएमा,\n(ि) उपदफा (१) को िण्ड (घ) मा उत्तल्लत्तित काम गने व्र्त्ति\nराष्‍ट रसेिक िो िन् ने कुरा जानकारी िनु े िा हिश्ि ास गन यु पने\nमनामसब कारण निएमा,\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n9\nwww.lawcommission.gov.np\n(ग) उपदफा (१) को िण्ड (ङ) मा उत्तल्लत्तित काम गने व्र्त्तिले\nत्र्स्तो काम कुनै राष्‍ट रसेिकको मनदेशनमा गरररिेको िो िन् ने\nकुरा जानकारी िनु े िा हिश्ि ास गन यु पने मनामसब कारण निएमा\nिा त्र्स्तो मनदेशन अनसु ार त्र्स्तो काम गन य लागेको िो िन् ने\nकुरा मनजले जानकारी नठदएमा िा त्र्स्तो काम गन य अमधकारपर\nिएकोमा माग गदाय पमन त्र्स्तो अमधकार पर नदेिाएमा।\n(३) दफा २४ िा र्स दफा अन्तगतय मनजी रिाको अमधकार प्रर्ोग गदाय त्र्स्तो\nरिा गनकय ो लामग आिश्र्क पने मनामसब बलिन्दा बढी बल प्रर्ोग गन य सहकने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२६", "title": "ज्र्ान मलने अमधकार निनु ेाः (१) र्स पररच्छेद बमोत्तजम मनजी रिाको अमधकार प्रर्ोग", "content": "गदाय कसैलाई कसैको ज्र्ान मलने अमधकार िनु ेछैन।\n(२) उपदफा (१) मा जनु सकै कुरा लेत्तिएको िए तापमन दफा २५ को उपदफा\n(३) को अधीनमा रिी देिार्को अिस्थामा मनजी रिाको अमधकार प्रर्ोग गदाय कसैको\nज्र्ान गएकोमा त्र्स्तो काम कसूर मामनने छैनाः-\n(क) आफू िा अरु कसैमामथ िएको आक्रमण हिरुद्ध तत्काल रिा\nनगदाय आफ्नो िा अरु कसैको ज्र्ान जान िा आफू िा अरु\nकसैलाई गम्िीर चोट लागन िा अङ्गिङ्ग िनु सक्छ िन् ने मनामसब\nहिश्ि ास िएमा,\n(ि) जिजस्य ती करणी गने मनर्तले आक्रमण गरेको िो िन् ने मनामसब\nहिश्ि ास िई िा जिजस्य ती करणी गदायका बित िा गररसके पमछ\nपीमडतबाट तत्काल कुनै काम िएकोमा,\n(ग) ज्र्ान माने, बन्धक िा अपिरण गराउन मत्तुि रकम मलने,\nजिजस्य ती करणी गने, अङ्गिङ्ग गने मनर्तले शरीर बन्धक मलएकोमा\nिा अपिरण गरेकोमा,\n(घ) मामनस बस्ने, पूजा िा प्राथनय ा गने, सम्पत्ति राख् ने कुनै घर, पाल िा\nसिारी साधनलाई घेराबन्दी गरी, जोत्तिमपूण य िातिमतर्ार प्रर्ोग\nगरी, आगो लगाई िा हिष्‍टफोटक पदाथ य प्रर्ोग गरी िमत पर्ु ायउन\nिोजेकोमा,\n(ङ) डााँकाको कसूर हिरुद्ध रिा गन यु परेमा,\n(च) कुनै व्र्त्तिको िैर्त्तिक सरु िा िा नेपाल सरकार, प्रदेश सरकार\nिा स्थानीर् ति िा नेपाल सरकार, प्रदेश सरकार िा स्थानीर्\n10\nwww.lawcommission.gov.np\nतिको पूण य िा अमधकांश स्िाममत्ि िा मनर्न्रण िएको सङ्गठठत\nसंस्थाको सम्पत्ति िा सािजय मनक सम्पत्तिको सरु िाका लामग\nअमधकार प्राप्त अमधकारीको आदेशबाट िहटएको सरु िाकमीले\nत्र्स्तो व्र्त्ति िा सम्पत्ति हिरुद्ध िएको आक्रमण रोक्न तत्काल\nप्रमतकार गन यु परेकोमा।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२७", "title": "मामलु ी िामन, नोक्सानी िएकोमा कसूर निनु ेाः साधारण समझको व्र्त्तिले गरेको मामलु ी", "content": "हकमसमको िामन, नोक्सानीलाई कसूर मामनने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२८", "title": "बालबामलकाबाट गराएको कसूरमा उमेर पगु के ोलाई सजार् िनु ेाः कसैले कुनै", "content": "बालबामलकालाई फकाई, मसकाई िा प्रिािमा पारी कुनै कसूर गन य लगाएको रिेछ िने\nत्र्सरी कसूर गन य लगाउन े व्र्त्तिलाई मनज आफै ले त्र्स्तो कसूर गरे सरि सजार्\nिनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२९", "title": "मनरपेि दाहर्त्ि (स्रीक्ट लार्हिमलहट) िनु े कसूरमा आपरामधक मनसार् परीिण निनु ेाः", "content": "र्स संहिता िा कानून बमोत्तजम मनरपेि आपरामधक दाहर्त्ि िनु े कसूरमा त्र्स्तो कसूर\nमनसार्पूिकय गरेको िो िा िोइन िन् ने कुरा परीिण िनु े छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३०", "title": "सङ्गठठत संस्थाबाट िएको कसूरमा काम गने गराउनेको आपरामधक दाहर्त्ि िनु ेाः कुनै फम,य", "content": "कम्पनी िा सङ्गठठत संस्थाले र्स संहिता िा कानून बमोत्तजम कसूर मामनने कुनै काम\nगरेको िा गराएकोमा जसले त्र्स्तो काम गरे िा गराएको िो सोिी व्र्त्ति त्तजम्मेिार\nिनु ेछ र त्र्स्तो व्र्त्ति हकटान िनु नसके मा फमकय ो िकमा त्र्स्ता काम गने सम्बत्तन्धत\nधनी िा हिस्सेदारिरु र कम्पनी िा सङ्गठठत संस्था िए त्र्स्तो काम गने िा गराउने\nसञ् चालक, प्रबन्ध सञ् चालक, मिाप्रबन्धक र त्र्स्तो व्र्त्ति पमन हकटान िनु नसके मा\nत्र्स्तो संस्थाको कार्कय ारी प्रमिु ले आपरामधक दाहर्त्ि व्र्िोन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३१", "title": "समूिबाट िएको कसूरमा सबै सदस्र्लाई सजार् िनु ेाः दईु िा दईु िन्दा बढी व्र्त्तिको", "content": "समूिबाट कुनै कसूर िएकोमा सो समूिका सबै सदस्र्लाई त्र्स्तो कसूरको सजार्\nिनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३२", "title": "अपराध पीमडतलाई मद्दु ाको कारबािीको जानकारी र िमतपूमत य पाउने िक िनु ेाः (१) अपराध", "content": "पीमडतलाई आफू पीमडत िएको मद्दु ाको अनसु न्धान तथा कारबािी सम्बन्धी जानकारी\nपाउने िक िनु ेछ।\n(२) अपराध पीमडतलाई कानून बमोत्तजम सामात्तजक पनु ाःस्थापना र िमतपूमत य\nसहितको न्र्ार् पाउने िक िनु ेछ।\n11\nwww.lawcommission.gov.np\nपररच्छेद-३\nआपरामधक षड्र् न्र, उद्योग, दरुु त्सािन र ममतर्ार", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३३", "title": "आपरामधक षड्र् न्र गन य निनु ेाः (१) कसैले कुनै आपरामधक षड् र्न्र गन य िाँदु ैन।", "content": "(२) दईु िा दईु िन्दा बढी व्र्त्तििरुले कुनै कसूर गन य िा गराउन मन्जरु गरी\n\nकुनै एकजना मार िा दईु िा दईु िन्दा बढी व्र्त्तििरुले कुनै कार् य गरेमा मनजिरुले\nआपरामधक षड् र्न्र गरेको मामनने छ।\n(३) जघन्र् िा गम्िीर प्रकृ मतको कसूरको आपरामधक षड् र्न्र गने िा गराउने\nव्र्त्तिलाई र्स संहितामा अन्र्र छुटैृ सजार्को व्र्िस्था िएकोमा सोिी बमोत्तजम र\nनिएकोमा देिार् बमोत्तजम सजार् िनु ेछाः-\n(क) आपरामधक षड् र्न्र बमोत्तजमको कसूर गरेको िए त्र्स्तो कसूर\nगरे सरिको सजार्,\n(ि) आपरामधक षड् र्न्र बमोत्तजमको कसूर निई अन्र् कसूर िएकोमा\nत्र्स्तो कसूर त्र्स्तो षड् र्न्र कार्ायन्िर्नको मसलमसलामा िा\nत्र्सैको सम्िाहित पररणामस्िरुप िएको रिेछ िने त्र्स्तो कसूर\nबापत िनु े सजार्,\n(ग) आपरामधक षड् र्न्र बमोत्तजमको कसूरको अमतररि अन्र् कसूर\nपमन िएकोमा त्र्स्तो कसूर पमन सोिी षडर्न्र कार्ायन्िर्नको\nमसलमसलामा िा त्र्सैको सम्िाहित पररणामस्िरुप िएको रिेछ\nिने त्र्स्तो कसूरको समेत थप सजार्,\n(घ) आपरामधक षडर्न्र गने कार् य पूरा िई नसके को िएमा त्र्स्तो\nकसूरमा िनु े सजार्को आधा सजार्।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३४", "title": "कसूर गने उद्योग गन य निनु ेाः (१) कसैले कुनै कसूर गने उद्योग गन य िाँदु ैन।", "content": "(२) जनु कसूरको उद्योग िएको िो त्र्स्तो कसूर िनु असम्िि िएमा पमन\nउद्योग गरेको मामननेछ।\n(३) र्स संहितामा अन्र्था व्र्िस्था िएकोमा बािेक कसूर गन य उद्योग गने िा\nगराउने व्र्त्तिलाई त्र्स्तो कसूरको लामग तोहकएको सजार्को आधा सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३५", "title": "दरुु त्सािन ठदन निनु ेाः (१) कसैले कसैलाई कुनै कसूर गन य दरुु त्सािन ठदन ु िाँदु ैन।", "content": " मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n12\nwww.lawcommission.gov.np\n(२) उपदफा (१) को प्रर्ोजनको लामग कसैले कसैलाई कुनै कसूर गन य\nउक्साएमा मनजले दरुु त्सािन ठदएको मामननेछ।\n(३) दरुु त्सािन ठदने व्र्त्तिलाई र्स संहितामा छुट्टै सजार्को व्र्िस्था गररएकोमा\nसोिी बमोत्तजम र नगररएकोमा देिार् बमोत्तजम सजार् िनु ेछाः–\n(क) दरुु त्सािन ठदए बमोत्तजम कसूर िएको िए मनज स्िर्ंले कसूर गरे\nसरिको सजार्,\n(ि) दरुु त्सािन ठदए बमोत्तजम कसूर िई नसके कोमा सो कसूरका लामग\nतोहकएको सजार्को आधा सजार्।\n(४) कुनै व्र्त्तिलाई एउटा कसूर गन य दरुु त्सािन ठदएकोमा त्र्स्तो व्र्त्तिले\nत्र्स्तो दरुु त्सािनको प्रिाि िा सम्िाहित पररणाम स्िरुप कुनै अको कसूर गरेमा\nदरुु त्सािन ठदने व्र्त्तिलाई त्र्स्तो कसूर पमन मनज स्िर्ंले गरे सरि सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३६", "title": "ममतर्ार िनु निनु ेाः (१) कुनै व्र्त्ति कुनै कसूरको ममतर्ार िनु ु िाँदु ैन।", "content": "(२) कुनै कसूर गने मनर्तले त्र्स्तो कसूर िा अन्र् कसूर गन य सिर्ोग पर्ु ाउय ने\nिा कसूर गररसके पमछ कसूरदारलाई िगाउने, लकु ाउने िा कसूर गन य िा गराउन साधन\nउपलब्ध गराउने िा अन्र् कुनै हकमसमले सिर्ोग पर्ु ायउने व्र्त्ति ममतर्ार मामननेछ।\n(३) ममतर्ारलाई देिार् बमोत्तजम सजार् िनु ेछाः-\n(क) आपरामधक षड् र्न्रमा संलगन िई कसूर गने, साधन िा ठााँउ\nउपलव्ध गराइठदने, जसको हिरुद्ध कसूर गररएको िो त्र्स्तो\nव्र्त्तिलाई मनजी रिाको अमधकारबाट बत्तित गराउने िा कसूर\nगन य आदेश िा सल्लाि ठदनेलाई त्र्स्तो कसूर मनजले गरे सरिको\nसजार्,\n(ि) िण्ड (क) मा लेत्तिएको बािेक अन्र् ममतर्ार िए कसूर िए\nगरेको काममा मनजको संलगनताको मारा अनसु ार त्र्स्तो कसूर\nगरे बापत िनु े सजार्को बढीमा आधासम्म सजार्।\n३७ िदम्र्ाद लागू िनु ेाः र्स संहितामा कुनै कसूरका सम्बन्धमा व्र्िस्था गररएको उजरु गने\nिदम्र्ाद त्र्स्तो कसूरको षड् र्न्र, उद्योग, दरुु त्सािन िा ममतर्ारको सम्बन्धमा समेत लागू\nिनु ेछ।\n13\nwww.lawcommission.gov.np\nपररच्छेद-४\nकसूरको गम्िीरता बढाउने तथा घटाउने अिस्थािरु", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३८", "title": "कसूरको गम्िीरता बढाउने अिस्थााः र्स संहिताको प्रर्ोजनका लामग देिार्का अिस्थािरु", "content": "हिद्यमान रिेमा कसूरको गम्िीरता बढाएको मामनने छाः\n(क) राष्‍ट रपमत िा सरकार प्रमिु िा हिदेशी राज्र् प्रमिु को हिरुद्ध कसूर\nगरेको,\n(ि) राष्‍ट रपमत िा सरकार प्रमिु िा हिदेशी राज्र् प्रमिु को उपत्तस्थमतमा कसूर\nगरेको,\n(ग) हिश्ि ासको दरुु पर्ोग गरी कसूर गरेको,\n(घ) कुनै सािजय मनक पदको लाि उठाई िा दरुु पर्ोग गरी कसूर गरेको,\n(ङ) सािजय मनक पद धारण गरेको व्र्त्तिले आफ्नो पदीर् कतव्य र् पालन गन य\nलागेकोमा बाधा पर्ु ायउने िा मनजलाई कुनै गैरकानूनी काम गन य लगाउने\nमनर्तले कसूर गरेको,\n(च) कुनै सरकारी कार्ायलर्, सािजय मनक कार्ायलर् िा धाममकय स्थलमा कसूर\nगरेको,\n(छ) पााँच िा पााँचिन्दा बढी व्र्त्तििरु समूिमा आिद्ध िई कसूर गरेको,\n(ज) सािजय मनक शात्तन्त िलबमलएको, बाढी, पहिरो, िकू म्प िा त्र्स्तै प्रकृ मतको\nदैिी प्रकोप िएको मिामारी फै मलएको, अमनकाल परेको िा त्र्स्तै\nहकमसमको अन्र् कुनै सङ्कटको लाि मलई कसूर गरेको,\n(झ) िातिमतर्ार िा हिषाल ु िा हिष्‍टफोटक पदाथ य साथमा मलई िा प्रर्ोग गरी\nिा हिद्यतु प्रिाि गरी िा हिद्यतु ीर् उपकरण प्रर्ोग गरी कसूर गरेको िा\nिातिमतर्ार िा हिषाल ु िा हिष्‍टफोटक पदाथ य मलएको मामनसको मद्दतबाट\nकसूर गरेको,\n\n(झ१) तेजाब, अन्र् घातक रासार्मनक िा ज्िलनशील पदाथ य कसैमामथ प्रिार िा\nप्रर्ोग गरी िा कसैलाई सेिन गराई कसूर गरेको,\n(ञ) एक पटक कै द सजार् पाएको कसूरदारले पनु ाः कसूर गरेको,\n फौजदारी कसूर तथा फौजदारी कार्हयिमध सम्बन्धी के िी ऐन संशोधन गने ऐन, २०७९ द्वारा थप।\n14\nwww.lawcommission.gov.np\n\n(ट) कुनै पाररतोहषक िा आश्ि ासन िा लाि पाई िा लाि पाउने प्रलोिनमा\nपरी कसूर गरेको,\n(ठ) आफ्नो संरिण िा मनर्न्रणमा रिेको व्र्त्ति िा त्तजम्मामा रिेको\nसम्पत्तिको हिरुद्ध कसूर गरेको,\n(ड) कसैलाई  र्ातना ठदई िा क्रू र, अमानिीर् िा अपमानजन्र् व्र्ििार गरी\nकसूर गरेको,\n(ढ) एकै िारदातमा एकिन्दा बढी कसूर गरेको,\n(ण) एकै िारदातमा एकिन्दा बढी व्र्त्तिका हिरुद्ध कसूर गरेको,\n(त) कसैलाई अपिरण गरी िा शरीर बन्धक मलई कसूर गरेको,\n(थ) थनु ा, हिरासत, कै द िा मनर्न्रणमा रिेको व्र्त्ति हिरुद्ध कसूर गरेको,\n(द) कुनै व्र्त्तिको सरु िाको कतव्य र् िएका व्र्त्तिले आफू ले सरु िा गन यु पने\nव्र्त्तिको हिरुद्ध कसूर गरेको,\n\n(ध) कुनै जात, जामत िा सम्प्रदार्को अत्तस्तत्ि नै हिनाश गने गरी जामतित्र्ा\n(जेनोसाइड) को उद्देश्र्ले कसूर गरेको,\n(न) कुनै जात, जामत, धाममकय िा सााँस्कृ मतक समदु ार् हिरुद्ध घृणा उत्पन् न गने\nउद्देश्र्ले कसूर गरेको,\n(प) मानिता हिरुद्धको कसूर गरेको,\n(फ) मनर्ोत्तजत िा सङ्गठठत रुपमा कसूर गरेको,\n(ब) पचििर िषमय ामथको िद्धृ ािस्था िा शारीररक िा मानमसक अस्िस्थताले\nगदाय िोस ठेगानमा नरिेको िा अपाङ्गताको कारणले आफ्नो बचाउ गन य\nसक्ने त्तस्थमतमा निएको व्र्त्ति िा बालबामलकाको हिरुद्ध कसूर गरेको,\n(ि) सिारी िा हिमान दघु टय ना िा प्राकृ मतक प्रकोप पदाय उद्धार गने काममा\nिहटाँदा कसूर गरेको,\n(म) एकपटक कुनै कसूरबाट पीमडत िैसके को व्र्त्तिका हिरुद्ध सोिी\nकसूरदारले अको कसूर गरेको।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३९", "title": "कसूरको गम्िीरता घटाउने अिस्थााः र्स संहिताको प्रर्ोजनको लामग देिार्का अिस्थािरु", "content": "हिद्यमान रिेमा कसूरको गम्िीरता घटाएको मामननेछाः-\n(क) कसूरदारको उमेर अठार िषिय न्दा कम िा पचििर िषिय न्दा मामथ िएको,\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा थप।\n15\nwww.lawcommission.gov.np\n(ि) कसूरदारको कसूर गने मनर्त निएको,\n(ग) जनु व्र्त्तिको हिरुद्ध कसूर िएको छ त्र्स्तो व्र्त्तिले कसूरदारलाई\nकसूर िनु िु न्दा तत्कालअत्तघ उिेत्तजत गरेको िा धम्की ठदएको,\n(घ) कसूरदार िा मनजको कुनै नत्तजकको नातेदारका हिरुद्ध गररएको कुनै\nगम्िीर कसूरको प्रमतकारको रुपमा तत्कालै कसूर िएको,\n(ङ) कसूरदारले स्िेच्छाले कसूर स्िीकार गरेको िा त्र्स्तो कसूर गरे बापत\nपिाताप गरेको,\n(च) कसूरदारले सम्बत्तन्धत अमधकारी समि आत्मसमपय ण गरेको,\n(छ) कसूरदारले आफू ले गरेको कसूर स्िीकार गरी पीमडतलाई िमतपूमत य\nठदइसके को िा ठदन मञ्जुर गरेको,\n(ज) शारीररक, मानमसक तथा अपाङ्गताको कारणले गदा य कसूरदारको िमता\nह्रास िएको,\n(झ) पीमडत पि र समाजलाई िनु गएको िामन, नोक्सानीको मारा उल्लेिनीर्\nनदेत्तिएको,\n(ञ) अदालतमा सााँचो कुरा व्र्ि गरी न्र्ाहर्क प्रकृ र्ामा सिर्ोग पर्ु ायएको,\n(ट) कसूर स्िीकार गरी िहिष्‍टर्मा फौजदारी कसूर नगने प्रमतिद्घता व्र्ि\nगरेको,\n(ठ) कसैको बिकाउ िा दबाबमा अपराध गरेको।\nपररच्छेद-५\nसजार् र अन्तररम िमतपूमत य सम्बन्धी व्र्िस्था", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४०", "title": "सजार्का प्रकाराः (१) र्स संहितामा उत्तल्लत्तित कसूर गरे बापत िनु े सजार् देिार्", "content": "बमोत्तजम िनु े छनाः् -\n(क) जन्म कै द,\n(ि) कै द,\n(ग) जररबाना,\n(घ) कै द र जररबाना,\n(ङ) िमतपूमत,य\n(च) जररबाना िा िमतपूमत य नमतरे बापतको कै द,\n16\nwww.lawcommission.gov.np\n\n(छ) कै दको सट्टा सधु ार गिृ िा सामदु ाहर्क सेिा।\n(२) कानूनमा कुनै कसूर बापत सिस्य िको सजार् िनु े रिेछ िने र्ो संहिता\nप्रारम्ि िएपमछ त्र्स्तो कसूरमा सजार् गदाय सिस्य ि िनु े गरी सजार् गररने छैन।\n(३) र्स दफामा अन्र्र जनु सकु ै कुरा लेत्तिएको िए तापमन एक रुपैर्ािाँ न्दा कम\nजररबाना र एक ठदनिन्दा कम कै द िनु े गरी सजार् गररने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४१", "title": "जन्म कै द िनु ेाः र्स संहितामा अन्र्र जनु सकु ै कुरा लेत्तिएको िए तापमन देिार्को कुनै", "content": "कसूर गने कसूरदारलाई जन्मकै दको सजार् गदाय त्र्स्तो कसूरदार जीहित रिेसम्म कै द\nगन यु पनेछाः-\n(क) क्रू र र्ातना ठदई िा मनममय तापूिकय ज्र्ान मारेको,\n(ि) िार्र्ु ान अपिरण गरी िा िार्र्ु ान हिष्‍टफोट गरी ज्र्ान मारेको,\n(ग) अपिरण गरी िा शरीरबन्धक मलई ज्र्ान मारेको,\n(घ) सािजय मनक रुपमा उपिोग िनु े पेर् िा िाद्य पदाथमय ा हिष िाली ज्र्ान\nमारेको,\n\n(घ१) आतङ्ककारी कार् य सम्बन्धी कसूर गरी ज्र्ान मारेको,\n\n(ङ) कुनै जात, जामत िा सम्प्रदार्को अत्तस्तत्ि नै हिनाश गने गरी जामतित्र्ा\n(जेनोसाइड) गरेको िा गने उद्देश्र्ले कसूर गरेको िा\n(च) जिजस्य ती करणी गरी ज्र्ान मारेको।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४२", "title": "जन्म कै दको गणनााः दफा ४१ मा उत्तल्लत्तित अिस्थामा बािेक जन्म कै दको सजार्", "content": "गणना गदाय पच्चीस िर्रष य कै द सजार् िनु े गरी गणना गन यु पनेछ।\n४३. एकीकृ त कसूर बापत थप सजार् िनु ेाः (१) कुनै व्र्त्तिले एउटै िारदातमा एकिन्दा बढी\nकसूर गरेमा त्र्स्तो व्र्त्तिले एकीकृ त कसूर गरेको मामननेछ।\n(२) उपदफा (१) बमोत्तजमको एकीकृ त कसूर गने कसूरदारलाई सजार् गदाय\nसबैिन्दा बढी सजार् िनु े कसूर बापतको सजार् र त्र्सपमछको अमधकतम सजार् िनु े\nअको कसूर बापतको सजार्को आधा सजार् थप गरी सजार् गन यु पनेछ।\nतर जन्मकै दको सजार् िनु े अिस्थाको कसूरदारको िकमा र्ो उपदफा लागू िनु े\nछैन।\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n सम्पत्ति शद्धु ीकरण (मनी लाउण्डररङ्ग) मनिारण तथा व्र्ािसाहर्क िातािरण प्रिद्धयन सम्बन्धी के िी ऐनलाई\nसंशोधन गने ऐन, २०८० द्वारा थप।\n17\nwww.lawcommission.gov.np\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४४", "title": "थप सजार् िनु ेाः (१) जघन्र् िा गम्िीर कसूरमा सजार् पाएको व्र्त्तिले अको कसूर", "content": "गरेमा मनजले पमछल्लो पटक गरेको कसूरमा िनु े सजार्को दोब्बरसम्म सजार् िनु ेछ।\nतर जन्म कै दको सजार् पाएको कसूरदारको िकमा र्ो दफा लागू िनु े छैन।\n(२) उपदफा (१) बमोत्तजमको कसूर बािेक अन्र् कसूरमा सजार् पाएको\nव्र्त्तिले त्र्स्तो सजार् ििु ान गरेको पााँच िषमयिर अको कसूर गरेमा मनजलाई पमछल्लो\nपटक गरेको सजार्को दोब्बरसम्म सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४५", "title": "बालबामलकालाई िनु े सजार्ाः (१) कानून बमोत्तजम कसूर ठिररने कुनै काम गने व्र्त्तिको", "content": "उमेर त्र्स्तो काम गदायका बित दश िष य पगु ेको रिेनछ िने मनजलाई कुनै सजार् िनु े\nछैन।\n\n(२) दश िष य िा दश िषिय न्दा मामथ र चौध िषिय न्दा कम उमेर िएको\nव्र्त्तिले कानून बमोत्तजम जररबाना िनु े कुनै कसूर गरेकोमा जररबाना नगरी मनजलाई\nसम्झाई बझु ाई गन यु पनेछ र कै द िनु े कसूर गरेकोमा कसूर िेरी छ महिनासम्म कै द\nसजार् गन य िा कै द नगरी बढीमा एक िषसय म्म सधु ार गिृ मा राख् न सहकनेछ।\n(३) चौध िष य िा चौध िषिय न्दा मामथ र सो¥ि िषिय न्दा कम उमेरको व्र्त्तिले\n\n......... कुनै कसूर गरेमा मनजलाई उमेर पगु ेको व्र्त्तिलाई कानून बमोत्तजम िनु े\nसजार्को आधा सजार् िनु ेछ।\n(४) सोह्र िष य िा सोह्र िषिय न्दा मामथ र अठार िषिय न्दा कम उमेरको व्र्त्तिले\n\n......... कुनै कसूर गरेमा मनजलाई उमेर पगु ेको व्र्त्तिलाई कानून बमोत्तजम िनु े\nसजार्को दईु मतिाई सजार् िनु ेछ।\n\n(५) उपदफा (२), (३) र (४) मा जनु सकु ै कुरा लेत्तिएको िए तापमन सोह्र\nिष य उमेर पूरा निएका बालबामलकालाई सजार् गदाय जघन्र् कसूर, गम्िीर कसूर िा\nपटके रुपमा कसूर गरेकोमा बािेक कै दको सजार् गन यु िाँदु ैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४६", "title": "जररबाना बापत कै द गन य सहकनेाः (१) कुनै कसूरदारलाई तोहकएको जररबाना मनजको", "content": "सम्पत्तिबाट असूल उपर गररनेछ। मनजको कुनै सम्पत्ति निएमा िा त्र्सरी जररबाना\nबापतको रकम मनजबाट असूल उपर िनु नसके मा मनजलाई कै द गन य सहकनेछ।\n(२) उपदफा (१) बमोत्तजम कै द मनधायरण गदाय देिार् बमोत्तजम गन यु पनेछाः-\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा त्तझहकएको।\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा थप।\n18\nwww.lawcommission.gov.np\n\n(क) कै द र जररबाना दिु ै सजार् िनु े ठिर िएको कसूरमा जररबाना\nनमतरे बापतको कै द मनधायरण गर्रदाय दश िषिय न्दा बढी निनु े गरी\nकै द गन यु पनेछ।\n(ि) कै द िा जररबानामध्र्े कुनै िा दिु ै सजार् िनु सक्ने कसूरमा\nजररबाना मारको सजार् िई त्र्स्तो जररबाना नमतरे बापतको कै द\nमनधायरण गदाय त्र्स्तो कसूरमा िनु सक्ने कै दको उपल्लो िदको\nआधािन्दा बढी निनु े गरी कै द गन यु पनेछ।\n(ग) जररबाना मार सजार् िनु े कसूरमा जररबानाको सजार् िई सो\n\nनमतरे बापत कै द मनधायरण गदाय दईु िषिय न्दा बढी निनु े गरी\nकै द गन यु पनेछ।\n(३) उपदफा (२) मा जनु सकु ै कुरा लेत्तिएको िए तापमन अठार िष य उमेर\nनपगु ेको बालबामलकाको िकमा जररबाना बापत कै द गदाय देिार् बमोत्तजम गन यु पनेछाः-\n(क) जररबाना मार िनु े िा कै द िा जररबानामध्र्े कुनै एक सजार् िनु े\nकसूरमा जररबाना नमतरेकोमा कै द नगरी जररबाना ममनाि गन यु\nपनेछ।\n(ि) कै द िा जररबाना िा दिु ै सजार् िनु े कसूरमा जररबाना मार\n\nसजार् िएकोमा त्र्स्तो जररबाना नमतरे बापत कै द मनधायरण गन यु\nपदाय तीन महिनािन्दा बढी निनु े गरी कै द गन यु पनेछ।\n(ग) चौध िष य उमेर पगु ेको तर अठार िषिय न्दा कम उमेर िएको\nव्र्त्तिलाई उपदफा (२) बमोत्तजम कै द मनधायरण गर्रदाय अठार िष य\nउमेर पगु ेको व्र्त्तिलाई गन यु पने कै द सजार्को आधािन्दा बढी\nनिनु े गरी कै द गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४७", "title": "सजार् छुट ठदन सहकनेाः (१) कुनै कसूरदारले आफू ले गरेको कसूर स्िीकार गरी त्र्स्तो", "content": "कसूरका सम्बन्धमा प्रमाण जटु ाउन, अन्र् अमिर्िु िा त्र्सको मगरोि िा ममतर्ारलाई\nपक्राउ गन य िा अनसु न्धान िा अमिर्ोजन पि िा अदालतलाई सघाउ पर्ु ायएकोमा कानून\nबमोत्तजम िनु े सजार्को बढीमा पचास प्रमतशतसम्म सजार् छुट ठदन सहकनेछ।\n(२) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापमन देिार्को कसूरदारले\nसजार्मा छुट पाउन सक्ने छैनाः-\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n19\nwww.lawcommission.gov.np\n(क) उपदफा (१) अन्तगतय एक पटक सजार् छुट पाइसके को,\n(ि) कै द सजार् िनु े कसूरमा दोषी ठिर िई कै द ििु ान गरेको\nअिमध तीन िष य पूरा नगरेको,\n(ग) जनु कसूरमा सजार् छुट माग गररएको िो सोिी प्रकृ मतको\nकसूरमा एक पटक सजार् पाइसके को।\n(३) उपदफा (१) बमोत्तजम सजार्मा छुट ठदाँदा अमिर्िु ले अनसु न्धान िा\nपपु िय को कुन अिस्थामा कसूर स्िीकार गरेको िो र कस्तो पररत्तस्थमतमा त्र्स्तो कसूर\nस्िीकार गरेको िो त्र्स्तो कुरालाई समेत हिचार गन यु पनेछ।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४८", "title": "अन्तररम िमतपूमतकय ो लामग आदेश ठदन सक्नेाः (१) र्स संहितामा अन्र्र जनु सकु ै कुरा", "content": "लेत्तिएको िए तापमन कुनै कसूर िएको कारणबाट त्र्स्तो कसूरबाट पीमडत व्र्त्ति िा\nमनजमा आत्तश्रत व्र्त्तिलाई तत्काल उपचार गराउन ु पने िएमा िा िमतपूमत य िा कुनै\nप्रकारको राित रकम ठदन ु परेमा त्र्स्तो व्र्त्तिलाई औषधोपचार गराउन िा अन्तररम\nरुपमा िमतपूमत य िा राित रकम उपलब्ध गराउन अदालतले आदेश ठदन सक्नेछ।\n(२) उपदफा (१) बमोत्तजमको आदेश िएमा कसूरबाट पीमडत िा मनजका\nआत्तश्रत व्र्त्तिलाई फौजदारी कसूरमा सजार् मनधारय ण र कार्ायन्िर्न सम्बन्धी प्रचमलत\nकानून बमोत्तजम स्थापना िएको पीमडत राित कोषबाट िमतपूमत य िा राित रकम उपलब्ध\nगराउन ु पनेछ।\n(३) उपदफा (२) बमोत्तजम उपलब्ध गराइएको िमतपूमत य िा राित रकम\nअदालतबाट फै सला िाँदु ा अमिर्ोग लागेको व्र्त्ति कसूरदार ठिर िएमा त्र्स्तो\nकसूरदारलाई फै सला िएको पैंतीस ठदनमिर त्र्स्तो रकम पीमडत राित कोषमा जम्मा\nगन य अदालतले आदेश ठदनेछ।\n(४) उपदफा (३) बमोत्तजम अदालतले आदेश ठदएकोमा त्र्स्तो कसूरदारले\nिमतपूमत य िा राित बापतको रकम पीमडत राित कोषमा जम्मा गन यु पनेछ र मनजले सो\nअिमधमा त्र्स्तो रकम जम्मा नगरेमा फै सला िएको साठी ठदनमिर त्र्स्तो कसूरदारको\nजनु सकु ै जार्जेथाबाट सरकारी बााँकी सरि असूल उपर गन यु पनेछ।\n(५) र्स दफा बमोत्तजम िमतपूमत य िा राित रकम पाएको व्र्त्तिले झट्टु ा उजरु ी\nगरेको ठिरेमा िा िारदात स्थाहपत निएमा मनजले िमतपूमत य िा राित बापत पाएको रकम\nहफताय गन य अदालतले आदेश ठदनेछ।\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n20\nwww.lawcommission.gov.np\n(६) उपदफा (५) बमोत्तजम अदालतले आदेश ठदएकोमा त्र्स्तो व्र्त्तिले िमतपूमत य\nिा राित बापत पाएको रकम फै सला िएको पैंतीस ठदनमिर पीमडत राित कोषमा हफताय\nगन यु पनेछ र मनजले सो अिमधमा त्र्स्तो रकम हफताय नगरेमा फै सला िएको साठी\nठदनमिर त्र्स्तो व्र्त्तिको जनु सकु ै जार्जेथाबाट सरकारी बााँकी सरि असलु उपर गन यु\nपनेछ।\nिाग-२\nफौजदारी कसूरिरु\nपररच्छेद-१\nराज्र् हिरुद्धका कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४९", "title": "साििय ौमसिा, अिण्डता िा रात्तष्‍टर र् एकता उपर िलल गन य निनु ेाः (१) कसैले नेपालको", "content": "स्ितन्रता, साििय ौमसिा, िौगोमलक िा प्रादेत्तशक अिण्डता िा रात्तष्‍ट रर् एकतामा िलल\nपाने मनर्तले मामनस, िातिमतर्ार र िरिजाना जम्मा गन,य िातिमतर्ार सहित सैमनक िा\nअधसय ैमनक सङ्गठन मनमायण गन य िा त्र्स्तो कार् य गने उद्योग गन यु िाँदु ैन।\n(२) कसैले नेपालको स्ितन्रता, साििय ौमसिा, िौगोमलक िा प्रादेत्तशक अिण्डता\nिा रात्तष्‍ट रर् एकतामा िलल पान य सक्ने गरी कुनै हिदेशी राज्र्, सरकार िा सङ्गठठत\nशत्तिसाँग ममली कुनै प्रकारको षड् र्न्र गन यु िा गराउन ु िाँदु ैन।\n(३) कसैले उपदफा (१) िा (२) अन्तगतय को कसूर गन य दरुु त्सािन ठदन ु\nिाँदु ैन।\n(४) कसैले नेपालको साििय ौमसिा, िौगोमलक िा प्रादेत्तशक अिण्डता, रात्तष्‍ट रर्ता\nिा रात्तष्‍ट रर् एकता, नेपालको स्िाधीनता, स्िामिमान िा सङ्घीर् इकाईमबचको ससु म्बन्ध\nिलल पन य सक्ने गरी िगीर्, जातीर्, धाममकय , िरे ीर्, साम्प्रदार्ीक र र्स्तै अरु कुनै\nआधारमा घृणा, द्वेष िा अििेलना उत्पन्न िनु े कुनै काम कारबािी गन य िा गराउन िा\nत्र्स्तो गने उद्योग गन य िा दरुु त्सािन ठदन िा त्र्स्तो काम गने षडर्न्र गन य िा हिमिन् न\nजात, जामत िा सम्प्रदार्मबचको ससु म्बन्ध िलल गन यु िा गराउन ु िाँदु ैन।\n(५) र्स दफा बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई देिार् बमोत्तजम\nसजार् िनु ेछाः-\n(क) उपदफा (१) िा (२) बमोत्तजमको कसूर िए जन्मकै द,\n(ि) उपदफा (३) बमोत्तजमको कसूर िए दश िषसय म्म कै द र एक\nलाि रुपैर्ासाँ म्म जररबाना,\n21\nwww.lawcommission.gov.np\n(ग) उपदफा (४) बमोत्तजमको कसूर िए पााँच िषसय म्म कै द र पचास\nिजार रुपैर्ासाँ म्म जररबाना।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५०", "title": "राजद्रोिाः (१) नेपाल सरकार िा संिैधामनक संरचनालाई पल्टाउने मनर्तले कसैले सैमनक,", "content": "अधसय ैमनक िा आपरामधक बलको प्रदशनय िा प्रर्ोग गरी कुनै अव्र्िस्था उत्पन् न गन य िा\nिातिमतर्ार सहित सैमनक िा अधसय ैमनक सङ्गठन मनमायण गन य िा त्र्स्तो षड् र्न्र िा\nउद्योग गन य िा गराउन िा दरुु त्सािन ठदन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई पच्चीस िषसय म्म कै द\nिनु ेछ।\n(३) नेपाल सरकार िा नेपाल सरकारको काम कारबािीको सम्बन्धमा कसैले\nलेिेर, िचनले, आकार िा त्तचह्नद्वारा िा अरु कुनै हकमसमबाट मनराधार िा अप्रमात्तणत कुरा\nदेिाई नेपाल सरकारप्रमत घृणा, द्वेष िा अििेलना गन य िा गराउन िा त्र्स्तो उद्योग गन य\nगराउन िाँदु ैन।\nतर र्स उपदफामा लेत्तिएको कुनै कुराले नेपाल सरकारको स्िस्थ र मर्ायठदत\nआलोचना गरेकोलाई कसूर गरेको मामनने छैन।\n(४) उपदफा (३) बमोत्तजमको कसूर गने व्र्त्तिलाई तीन िषसय म्म कै द िा तीस\nिजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५१", "title": "राष्‍टर हित प्रमतकू ल काम गन य निनु ेाः (१) कसैले राष्‍ट रहित प्रमतकू ल िनु े कुनै काम गन यु िा", "content": "गराउन ु िाँदु ैन।\n(२) उपदफा (१) को प्रर्ोजनका लामग कसैले देिार्को कुनै काम गरे िा\nगराएमा राष्‍ट रहित प्रमतकू ल काम गरेको मामननेछाः-\n(क) नेपालको स्ितन्रता, साििय ौमसिा, िौगोमलक िा प्रादेत्तशक\nअिण्डता, रात्तष्‍ट रर्ता, स्िाधीनता, स्िामिमान िा नेपालको\nअन्तररात्तष्‍ट रर् छहि उपर अपमान िनु े, िोच्र्ाउने िा घृणा िा द्वैष\nफै लाउने,\n(ि) नेपालको अन्तररात्तष्‍ट रर् सीमा अमतक्रमण गने िा मछमेकी\nमलु कु साँग सिममत िएको अिस्थामा बािेक सीमास्तम्ि िटाउने\nिा सीमास्तम्ि रात्तिएको ठाउाँ पररितनय गने िा नेपालको\nिौगोमलक िा प्रादेत्तशक अिण्डता उपर प्रमतकू ल िनु े गरी\nसीमास्तम्ि पररितनय गने।\n22\nwww.lawcommission.gov.np\n(३) नेपालको प्रमतमनमधत्ि गरी नेपालमा िा हिदेशी मलु कु मा कुनै िेलाडी िा\nिेलाडीिरुसाँग प्रमतस्पधाय गन य कुनै िेल िेल्ने नेपाली िेलाडी िा िेलाडीिरुको समूिले\nत्र्स्तो िेलको प्रमतस्पधायबाट आउने स्िािाहिक पररणामलाई प्रमतकू ल िनु े गरी\nममलोमतोमा िा कसैको प्रलोिनमा िा कुनै बाजी त्तजताउने िा िराउने गरी त्र्स्तो िेल\nिेल्न िा िेलाउन िाँदु ैन र त्र्सरी कुनै िेल िेमलएको रिेछ िने रात्तष्‍ट रर् हित हिरुद्धको\nकसूर िएको मामननेछ।\n(४) उपदफा (२) िा (३) बमोत्तजमको कसूर गने व्र्त्तिलाई देिार्को सजार्\nिनु ेछाः-\n(क) उपदफा (२) बमोत्तजमको कसूर िए पााँच िषसय म्म कै द र पचास\nिजार रुपैर्ासाँ म्म जररबाना,\n(ि) उपदफा (३) बमोत्तजमको कसूर िए तीन िषसय म्म कै द र तीस\nिजार रुपैर्ासाँ म्म जररबाना।\n(५) कसैले उपदफा (२) िा (३) बमोत्तजमको कसूर गदाय कुनै रकम लेनदेन\nगरेको िएमा उपदफा (४) बमोत्तजमको सजार्का अमतररि लेनदेन गरेको रकम समेत\nजफत िनु ेछ।\n(६) उपदफा (३) बमोत्तजमको कसूर गने आदेश िा मनदेशन ठदने, त्र्स्तो कसूर\nगन य दरुु त्सािन ठदने िा उक्साउने, त्र्स्तो कसूर गन य मद्दत गने व्र्त्तिलाई मख्ु र् कसूरदार\nसरि सजार् िनु ेछ।\n(७) उपदफा (२) िा (३) बमोत्तजमको कसूर सािजय मनक पद धारण गरेको\nव्र्त्ति िा नेपाललाई प्रमतमनमधत्ि गने व्र्त्तिले हिदेशमा गएका बित गरेको रिेछ िने\nमनजलाई तीन िषसय म्म थप कै द िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५२", "title": "जामतित्र्ा गन य निनु ेाः (१) कसैले पमन जामतित्र्ा (जेनोसाइड) को कसूर गन यु िा गराउन ु", "content": "िाँदु ैन।\n(२) उपदफा (१) को प्रर्ोजनका लामग कुनै जात, जामत, सम्प्रदार् िा धममकय\nसमूिको अत्तस्तत्ि पूण य िा आंत्तशक रुपमा हिनाश गने मनर्तले देिार्को कुनै काम गरेमा\nिा त्र्सको उद्योग िा षडर्न्र गरेमा जामतित्र्ाको कसूर गरेको मामननेछाः-\n(क) एकै पटक िा पटकपटक गरी त्र्स्तो समूिका सदस्र्िरुको\nर्ोजनाबद्ध रुपमा आमित्र्ा गरेमा,\n23\nwww.lawcommission.gov.np\n(ि) एकै पटक िा पटकपटक गरी र्ोजनाबद्ध रुपमा त्र्स्तो समूिका\nसदस्र्िरुको शारीररक अङ्गिङ्ग गरेमा िा मनजिरुलाई शारीररक िा\nमानमसक अशि बनाएमा,\n(ग) त्र्स्तो समूिका सदस्र्िरुको पूण य िा आंत्तशक रुपमा िौमतक\nहिनाश िनु े आकाँ लन गरी त्र्स्ता सदस्र्िरुले प्रर्ोग गने पानी,\nिाद्यान् न, इन्धन, औषमध जस्ता अत्र्ािश्र्क िस्तकु ो आपूमत य िा\nआिागमनमा अिरोध गरी त्र्स्ता समूिका सदस्र्को जीिन\nर्ापनका शतिय रुलाई मनर्ोत्तजत रुपमा कष्टप्रद बनाएमा,\n(घ) स्िैच्छाले अपनाएको पररिार मनर्ोजनका साधन प्रर्ोग गरेकोमा\nबािेक त्र्स्ता समूिमिर त्तशशिु रुको जन्म रोक्ने मनर्तले त्र्स्ता\nसमूिका सदस्र्िरुलाई जबरजस्ती गि य मनरोधक उपार् अपनाउन\nबाध्र् पाररएमा,\n(ङ) त्र्स्ता समूिबाट जत्तन्मएका बालबामलकालाई जबरजस्ती अको\nसमूिमा िस्तान्तरण गरेमा।\n(३) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई देिार् बमोत्तजम सजार्\nिनु ेछाः-\n(क) िण्ड (क) बमोत्तजमको कसूर िए जन्मकै द,\n(ि) िण्ड (ि) बमोत्तजमको कसूर िए र्स संहिता बमोत्तजम शारीररक\nअङ्गिङ्ग िा कुटहपट बापत िनु े सजार्मा थप पााँच िषसय म्म कै द र\nपचास िजार रुपैर्ााँसम्म जररबाना,\n(ग) िण्ड (ग), (घ) िा (ङ) बमोत्तजमको कसूर िए दश िषसय म्म\nकै द।\n(४) र्स दफा बमोत्तजमको कसूर कुनै व्र्त्ति िा कुनै सङ्गठठत िा असङ्गठठत\nसमूिको आदेश िा मनदेशनबाट िएको रिेछ िने त्र्स्तो मनदेशन ठदने व्र्त्ति िा त्र्स्तो\nसमूिको त्तजम्मेिार व्र्त्ति िा व्र्त्तििरुलाई मख्ु र् कसूरदार सरि सजार् िनु ेछ।\n(५) र्स दफा बमोत्तजमको कसूर सामहुिक रुपमा िा हिमिन् न व्र्त्तििरुको\nसंलगनतामा िएको रिेछ िने त्र्स्तो कसूरमा संलगन प्रत्र्ेक व्र्त्ति समान रुपमा\nकसूरदार मामननेछ।\n(६) र्स दफा बमोत्तजमको कसूर गने कुनै व्र्त्तिले सािजय मनक पद धारण गरेको\nिए मनजले आफू िन्दा मामथको अमधकारीको आदेश पालना गने िा कानून र व्र्िस्था\n24\nwww.lawcommission.gov.np\nकार्म गने िा कानून कार्ायन्िर्न गने मसलमसलामा त्र्स्तो कसूर िएको दाबी मलन सक्ने\nछैन र मनजले त्र्स्तो दाबी मलएको आधारमा सजार्बाट छुट िा उन्मत्तुि पाउने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५३", "title": "नेपाल हिरुद्व र्द्धु गन य िा नेपालसगाँ र्द्धु मा संलगन राज्र्का सेनालाई सिार्ता गन य निनु ेाः", "content": "(१) कसैले नेपाल हिरुद्ध िातिमतर्ार उठाई र्द्धु गन य िा र्द्धु गने घोषणा गन,य र्द्धु गने\nउद्योग गन य िा धम्की ठदन िा नेपाल हिरुद्ध र्द्धु गने मनर्तले िातिमतर्ार, िरिजाना\nजम्मा गन य िा सैमनक िा अधसय ैमनक सङ्गठन मनमायण गन यु िाँदु ैन।\n(२) कसैले र्द्धु त्तस्थमतको घोषणा िएको िा निएको जनु सकु ै अिस्थामा पमन\nनेपालसाँग र्द्धु मा संलगन रिेका कुनै हिदेशी सेनालाई कुनै हकमसमको सामररक िा सैमनक\nसूचना ठदन िा अन्र् कुनै हकमसमबाट सिार्ता गन य िा त्र्सको उद्योग गन य िाँदु ैन।\n(३) नेपालसाँग र्द्धु मा संलगन रिेको राज्र्, त्र्स्तो राज्र्का नागररक िा सङ्गठठत\nसंस्थासाँग सम्बन्ध राख् न, कारोबार गन य िा त्र्स्तो राज्र्का िस्त ु िा सेिा पैठारी िा प्राप्त\nगन य नसक्ने गरी नेपाल सरकारबाट घोषणा िएकोमा कसैले त्र्स्तो राज्र्, नागररक िा\nसंस्थासाँग त्र्स्तो सम्बन्ध राख् न, कारोबार गन य िा त्र्स्ता िस्त ु िा सेिा पैठारी िा प्राप्त\nगन य िाँदु ैन।\n(४) उपदफा (१) िा (२) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई जन्म\nकै द र उपदफा (३) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई पच्चीस िषसय म्म कै द\nर एक लाि पचास िजार रुपैर्ााँेाँसम्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५४", "title": "ममर राष्‍टर हिरुद्ध र्द्धु िा हिद्रोि गन य निनु ेाः (१) कसैले नेपालको िमू ी प्रर्ोग गरी", "content": "नेपालसाँग दौत्र् सम्बन्ध िएको ममर राष्‍ट र हिरुद्ध िातिमतर्ार उठाई र्द्धु गन,य त्र्सको\nधम्की ठदन िा र्द्धु गने उद्योग गन य िा मबद्रोि गन य िा सोको उद्योग गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई सात िषसय म्म\nकै द र सिरी िजार रुपैर्ााँसम्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५५", "title": "सैमनक िा प्रिरीलाई िडकाउन निनु ेाः (१) कसैले नेपाली सेना, नेपाल प्रिरी िा सशस्त्र", "content": "प्रिरी बल, नेपालमा बिाल रिेका सैमनक, प्रिरी िा सशस्त्र प्रिरी जिान िा अमधकृ तलाई\nनेपाली सेना िा नेपाल प्रिरी िा सशस्त्र प्रिरी बल, नेपाल छाडी िागन िा िड्काउन िा\nअनशु ासन िङ्ग गन य दरुु त्सािन ठदन िा कतव्य र्बाट हिचमलत गराउने उद्योग गन य िा\nत्र्सरी सेना िा प्रिरी िा बलबाट िागेको व्र्त्ति िो िन् ने जानीजानी िा हिश्ि ास गने\nकारण िई त्र्स्तो व्र्त्तिलाई आश्रर् ठदन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई दश िषसय म्म\nकै द र एक लाि रुपैर्ााँसम्म जररबाना िनु ेछ।\n25\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५६", "title": "जासूसी गन य निनु ेाः (१) कसैले नेपालको साििय ौमसिा, सरु िा िा िौगोमलक िा प्रादेत्तशक", "content": "अिण्डतामा िलल पाने िा नेपालको हितमा कुनै प्रमतकू ल असर पाने मनर्तले िा त्र्स्तो\nिनु सक्छ िन् ने जानीजानी िा कुनै हिदेशी राज्र् िा अन्तररात्तष्‍ट रर् संघ, संस्थाको\nप्रलोिनमा परी कसैलाई नेपालको सैमनक त्तस्थमत, सामररक व्र्िस्था िा आन्तररक\nसरु िाको हिषर् िा नेपाल सरकारले राजनीमतक, आमथकय िा कू टनीमतक दृहष्टकोणले गोप्र्\nराख् न पने हिषर् िा गोप्र् मलित िा कानून बमोत्तजम गोप्र् रिेको िा राख् न ु पने हिषर्को\nसूचना ठदन िा त्र्सको षड् र्न्र िा उद्योग गन य िा दरुु त्सािन ठदन िा त्र्स्तो सूचना ठदने\nमनर्तले अन्र् कुनै काम गन य िाँदु ैन र गरेमा जासूसी गरेको मामननेछ।\n(२) उपदफा (१) बमोत्तजम जासूसी गने िा गराउने व्र्त्तिलाई देिार्\nबमोत्तजमको सजार् िनु ेछाः-\n(क) नेपालको सैमनक त्तस्थमत, सामररक व्र्िस्था िा आन्तररक सरु िाको\nहिषर्का सम्बन्धमा जासूसी गने िा गराउने व्र्त्तिलाई पच्चीस\nिषसय म्म कै द,\n(ि) नेपाल सरकारले राजनीमतक, आमथकय िा कू टनीमतक दृहष्टकोणले\nगोप्र् राख् न ु पने हिषर् िा अन्र् कुनै गोप्र् मलितका सम्बन्धमा\nजासूसी गने िा गराउने व्र्त्तिलाई पााँचदेत्ति दश िषसय म्म कै द,\n(ग) िण्ड (क) र (ि) बािेक अन्र् कुराको जासूसी गने िा गराउने\n\nव्र्त्तिलाई पााँच िषसय म्म कै द र पचास िजार रुपैर्ााँसम्म\nजररबाना,\n(घ) कसैले जासूसी गन य लागेको थािा पाएर पमन नेपाल सरकारलाई\nत्र्स्तो कुराको जनाउ नठदने व्र्त्तिलाई एक िषसय म्म कै द र\n\nएक लाि रुपैर्ााँसम्म जररबाना।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५७", "title": "राष्‍टर पमत उपर आक्रमण गन य निनु ेाः (१) कसैले नेपालको राष्‍ट रपमतको ज्र्ान मलन िा", "content": "ज्र्ान मलने उद्योग गन य िाँदु ैन।\n(२) कसैले नेपालको राष्‍ट रपमतलाई कुनै हकमसमले अपिरण गन यु िा गराउन ु िा\nमनजको शरीर बन्धक मलन िा मलन लगाउन ु िाँदु ैन।\n(३) कसैले नेपालको राष्‍ट रपमत उपर कुनै हकमसमले आक्रमण गन यु िा गराउन ु\nिाँदु ैन।\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n26\nwww.lawcommission.gov.np\n(४) र्स दफा बमोत्तजमको कसूर गने व्र्मतmलाई देिार् बमोत्तजम सजार् िनु ेछाः–\n(क) उपदफा (१) बमोत्तजमको कसूर िए जन्मकै द,\n(ि) उपदफा (२) बमोत्तजमको कसूर िए दश िषदय ेत्ति पन्र िषसय म्म\nकै द,\n(ग) उपदफा (३) बमोत्तजमको कसूर िए पााँच िषदय ेत्ति दश िषसय म्म\nकै द।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५८", "title": "राष्‍टर पमत िा संसदलाई धम्की ठदन निनु ेाः (१) कसैले नेपालको राष्‍ट रपमत िा संसदलाई", "content": "संहिधान तथा कानून बमोत्तजम गन यु पने कार् य सम्पादन गनबय ाट रोक लगाउन िा बत्तित\nगन य िा कुनै िास तररकाबाट कार् य सम्पादन गन य िाध्र् गराउन कुनै हकमसमको बल\nप्रर्ोग गरी िा नगरी कुनै हकमसमको धम्की ठदन, डर िा रास देिाउन िा अन्र् कुनै\nहकमसमले दबाि ठदन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई सात िषसय म्म\nकै द िा सिरी िजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनको लामग “संसद” िन् नाले नेपालको संहिधान\nबमोत्तजमको सङ्घीर् संसद र प्रदेश सिा सम्झन ु पछ य र सो शब्दले व्र्िस्थाहपका–\nसंसदलाई समेत जनाउाँछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५९", "title": "िदम्र्ादाः (१) दफा ४९, ५०, ५१, ५२, ५३ र ५७ अन्तगतय का कसूरमा जहिले सकु ै", "content": "पमन उजरु लागन सक्नेछ।\n(२) उपदफा (१) मा उत्तल्लत्तित दफा बािेक र्स पररच्छेद अन्तगतय का अन्र्\nदफा अन्तगतय को कसूरमा त्र्स्तो कसूर िएको थािा पाएको मममतले दईु िष य नाघेपमछ\nउजरु लागने छैन।\nपररच्छेद-२\nसािजय मनक शात्तन्त हिरुद्धको कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६०", "title": "गैरकानूनी िेला गन य निनु ेाः (१) कसैले गैरकानूनी िेला गन य िाँदु ैन।", "content": "(२) देिार्को कुनै काम गने उद्देश्र्ले िएको पााँचजना िा पााँचजना िन्दा बढी\nव्र्त्तििरुको िेलालाई गैरकानूनी िेला मामनने छाः-\n(क) बलको प्रर्ोग िा प्रदशनय गरी िा जोत्तिमी िातिमतर्ार प्रदशनय\nगरी,\n(१) राष्‍ट रसेिकलाई कानूनले तोके को काम गन य िा कतव्य र्\nपालना गन य नठदने,\n27\nwww.lawcommission.gov.np\n(२) कसैको सम्पत्ति मलने िा कब्जा गने,\n(३) कसैलाई बाटो, पानी, सािजय मनक र्ातार्ात िा सिार िा\nअन्र् र्स्तै कुनै कुरा उपिोग गने िकबाट बत्तित गने,\n(४) कुनै व्र्त्तिलाई कानूनले गन य निनु े काम गन य लगाउने िा\nकानूनले गन य पाउने काम गन य नठदने।\n(ि) कुनै कानून िा कानूनी कारबािीको कार्ायन्िर्नमा बाधा अिरोध\nिडा गने,\n(ग) कै दको सजार् िनु े कुनै कसूर गने।\n(३) गैरकानूनी िेला िो िन् ने कुरा थािा पाउाँदा पाउाँदै कुनै व्र्त्ति त्र्स्तो\nिेलामा सििागी िएमा मनजलाई िातिमतर्ार नमलई सििागी िएको िए छ महिनासम्म\nकै द र पााँच िजार रुपैर्ासाँ म्म जररबाना र िातिमतर्ार मलएर सििागी िएको िए एक\nिषसय म्म कै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।\n(४) कसैले आफू सििागी निई कसैलाई ज्र्ाला ठदई िा अरु कुनै हकमसमले\nप्रलोिन िा दिािमा पारी कुनै गैरकानूनी िेलामा सििागी गराएमा मनज स्िर्ं त्र्स्तो\nगैरकानूनी िेलामा सििागी िएको मानी उपदफा (३) बमोत्तजमको सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६१", "title": "गैरकानूनी िेला रोक्ने िा िङ्ग गने आदेश उल्लङ्घन गन य निनु ेाः (१) अमधकार प्राप्त", "content": "अमधकारीले कुनै गैरकानूनी िेलालाई रोक्न िा िङ्ग गन य आदेश ठदएकोमा कसैले त्र्स्तो\nिेलामा रहिरिन िा सििागी िनु िाँदु ैन।\n(२) उपदफा (१) बमोत्तजम गैरकानूनी िेलामा रिी रिने, सििागी िनु े िा\nसििागी िनु आउने व्र्त्तिलाई एक िषसय म्म कै द िा दश िजार रुपैर्ााँसम्म जररबाना िा\nदिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६२", "title": "प्रत्र्ेक सदस्र्ले कसूर गरेको मामननेाः गैरकानूनी िेलाको कुनै सदस्र्ले त्र्स्तो िेलाको", "content": "उद्देश्र् प्राप्त गनकय ो लामग कुनै कसूर गरेमा त्र्स्तो कसूर िाँदु ाको बित त्र्स्तो कसूर गन य\nजानीजानी सिर्ोग पर्ु ायउने सो िेलाका प्रत्र्ेक सदस्र्ले त्र्स्तो कसूर गरेको मामननेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६३", "title": "िूलदङ्गा गन य निनु ेाः (१) कसैले िूलदङ्गा गन य िा गराउन िाँदु ैन।", "content": "(२) कुनै गैरकानूनी िेलाले िा त्र्स्तो िेलाको सििागीले त्र्स्तो िेलाको उद्देश्र्\nप्राप्त गने मसलमसलामा बल प्रर्ोग गरेमा िा सािजय मनक िा मनजी सम्पत्ति तोडफोड िा\nिामन, नोक्सानी गरेमा त्र्स्तो िेलाको प्रत्र्ेक सििागीले िूलदेंगा गरेको मामननेछ।\n(३) उपदफा (१) बमोत्तजमको कसूर गने प्रत्र्ेक व्र्त्तिलाई जोत्तिमी िातिमतर्ार\nमलई गरेको िए दईु िषसय म्म कै द र बीस िजार रुपैर्ााँसम्म जररबाना र जोत्तिमी\n28\nwww.lawcommission.gov.np\nिातहितर्ार नमलई गरेको िए एक िषसय म्म कै द र दश िजार रुपैर्ााँसम्म जररबाना\nिनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६४", "title": "िूलदङ्गा गन य दरुु त्सािन ठदन निु नु ेाः (१) कसैले िूलदङ्गा गराउने मनर्तले िा िूलदङ्गा िनु", "content": "सक्छ िन् ने जानीजानी कुनै व्र्त्तिलाई िूलदङ्गा गन य दरुु त्सािन ठदन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजम दरुु त्सािन ठदने व्र्त्तिलाई िूलदङ्गा िइसके कोमा\nएक िषसय म्म र िूलदङ्गा िइसके को रिेनछ िने छ महिनासम्म कै द िा पााँच िजार\nरुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६५", "title": "सािजय मनक शात्तन्त िलल पान य निनु ेाः (१) कसैले लेिेर, िचनले िा आकार िा त्तचह्नद्वारा", "content": "िा अरु कुनै हकमसमबाट धम,य िण,य जात, जामत, सम्प्रदार् िा िाषाको आधारमा नेपालका\nहिमिन् न िग,य िेर िा समदु ार्का व्र्त्तििरुका मबचको ससु म्बन्धमा िलल पाने काम गन य\nिाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक िषसय म्म\nकै द र दश िजार रुपैर्ााँसम्म जररबाना िनु ेछ।\n(३) उपदफा (१) बमोत्तजमको कसूर कुनै देिस्थल िा पूजा िा प्राथनय ा गने ठाउाँ\nिा धाममकय , सााँस्कृ मतक चाड िा समारोि िइरिेको ठाउाँमा गरेको िए उपदफा (२)\nबमोत्तजमको सजार्मा थप एक िषसय म्म कै द िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६६", "title": "राष्‍टर सेिकलाई बाधा हिरोध गन य निनु ेाः (१) कुनै राष्‍ट रसेिकले आफ्नो कतव्य र् पालन गने", "content": "मसलमसलामा गैर कानूनी िेला रोक्ने, िङ्ग गने िा िूलदङ्गा रोक्ने कुनै काम गदाय कसैले\nबाधा हिरोध पर्ु ायउन िा पर्ु ाउय ने उद्योग गन यु िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक िषसय म्म\nकै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६७", "title": "सािजय मनक स्थानमा आिागमनमा बाधा गन य निनु ेाः (१) कसैले सािजय मनक सडक, बाटो", "content": "घाटो, रज्जमु ाग,य के िलु कार माग,य हिमानस्थल, रेल्िे िा जलपररििन माग य िा िलु ाक र कुनै\nसािजय मनक सेिाको सञ् चालनमा कुनै हकमसमको डर, रास, िर् देिाई बन्द गन य िा कुनै\nहकमसमबाट सािजय मनक सडक, बाटोघाटो, रज्जमु ाग,य के िलु कार माग,य हिमानस्थल, रेल्िे िा\nजलपररििन माग य अिरुद्ध गरी पैदल र्ारी, सिारी साधन िा पशकु ो आिागमनलाई बाधा\nपर्ु ायउन िा कानून बमोत्तजम अमधकार प्राप्त अमधकारीको आदेशले बािेक सािजय मनक\nठाउाँमा कसैलाई प्रिेश गन य कुनै हकमसमले बाधा, अिरोध गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द िा तीस िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।\n29\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६८", "title": "सािजय मनक सेिा अिरुद्ध गन य निनु ेाः (१) कसैले सािजय मनक हिद्यतु िा दूरसिार िा त्र्स्तै", "content": "प्रकृ मतका अन्र् सािजय मनक सेिा िा कानून बमोत्तजमको सािजय मनक सेिा सञ् चालनमा कुनै\n\nहकमसमको डर रास, देिाई बन्द गन य िा कुनै हकमसमले अिरुद्ध गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द िा तीस िजार रुपैर्ााँसम्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६९", "title": "कफ्र्ू य उल्लङ्घन गन य निनु ेाः (१) गैरकानूनी िेला िा िूलदङ्गा िा शात्तन्त िङ्ग िनु े अन्र्", "content": "कुनै कामलाई रोक्न कानून बमोत्तजम अमधकार प्राप्त अमधकारीले ठदएको कफ्र्ू य आदेशलाई\nकसैले जानीजानी उल्लङ्घन गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक िषसय म्म\nकै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७०", "title": "झठ्ठु ा अफबाि फै लाउन निनु ेाः (१) कसैले सािजय मनक शात्तन्त िङ्ग गने, िूलदङ्गा गने िा", "content": "नेपालको साििय ौमसिा, िौगोमलक िा प्रादेत्तशक अिण्डता िा हिमिन् न जात, जामत िा\nसम्प्रदार्मबचको समु धरु सम्बन्धलाई िलल पाने मनर्तले कसैलाई उक्साउने गरी निए\nनगरेको अफबाि फै लाउन, प्रचार प्रसार गन य िा नारा जलु शु गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक िषसय म्म\n\nकै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७१", "title": "शात्तन्त िङ्ग गन य घर, जगगा िा सिारी साधन ठदन निनु ेाः (१) कुनै व्र्त्तिले सािजय मनक", "content": "शात्तन्त िङ्ग गन य िा िूलदङ्गा गन य लागेको कुरा थािा पाउाँदा पाउाँदै िा थािा पाउन ु पने\nमनामसब कारण िाँदु ा िाँदु ै त्र्स्तो व्र्त्तिलाई कसैले पमन आफ्नो घर, जगगा, सिारी साधन\nिा िातिमतर्ार उपलव्ध गराउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई छ महिनासम्म कै द िा पााँच\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७२", "title": "संिदे नशील सािजय मनक िरे मा मशाल जलु शु गन य निनु ेाः (१) नेपालको साििय ौमसिा,", "content": "िौगोमलक िा प्रादेत्तशक अिण्डता, सरु िा, सािजय मनक शात्तन्त िा त्तशष्टाचारको कारणले\nअमधकार प्राप्त अमधकारीको आदेशबाट संिेदनशील सािजय मनक िेर िनी तोहकएको कुनै\nठाउाँमा कसैले सािजय मनक शात्तन्त िङ्ग गने मनर्तले मशाल जलु शु , आगोजन्र् िा\nप्रज्िलनशील िस्त ु मलई जलु शु , सिा गन य िा गराउन िाँदु ैन।\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n30\nwww.lawcommission.gov.np\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई छ महिनासम्म कै द िा पााँच\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७३", "title": "आिश्र्क िस्त ु तोडफोड िा िामन, नोक्सानी गन य निनु ेाः (१) कसैले र्स पररच्छेद", "content": "अन्तगतय को कुनै कसूर गरी कानून बमोत्तजम आिश्र्क िस्त ु मामनने कुनै िस्त ु िा\nसािजय मनक िा मनजी सम्पत्ति िामन, नोक्सानी, तोडफोड िा आगजनी गन य िा गराउन िा\nअरु कसैलाई प्रर्ोग गरी िा आफैँ ले त्र्स्तो िस्त ु िा सम्पत्ति मबगान यु िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई र्स पररच्छेद बमोत्तजमको\nकसूरमा िनु े सजार्मा थप एक िष य कै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै\nसजार् िनु ेछ।\n(३) उपदफा (१) बमोत्तजमको कसूरबाट त्र्स्तो िस्त ु िा सम्पत्तिको िामन,\nनोक्सानी िइसके को रिेछ िने त्र्सको हिगो बमोत्तजमको िमतपूमत य समेत मनजबाट िराउन ु\nपनेछ।\n(४) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्ति र्हकन िएकोमा सोिी व्र्त्ति र\nत्र्स्तो व्र्त्ति र्हकन निएकोमा त्र्स्तो काम गन य उक्साउने िा आदेश ठदने व्र्त्तिले\nकसूर गरेको मामननेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७४", "title": "िदम्र्ादाः र्स पररच्छेद अन्तगतय को कसूरमा त्र्स्तो कसूर िएको मममतले तीन महिना", "content": "नाघेपमछ उजरु लागने छैन।\nपररच्छेद-३\nसािजय मनक अमधकारीको अत्तख्तर्ारीको अिज्ञा सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७५", "title": "समाह्वान, इतलार्नामा इत्र्ाठदको तामेलीमा बाधा पर्ु ाउय न निनु ेाः (१) कानून बमोत्तजम", "content": "जारी िएको समाह्वान, इतलार्नामा, पक्राउ पूजी, सूचना िा आदेश तामेल गदाय िा\nिानतलासी, बरामद िा नाप नक्सा िा सजमयमन गदाय िा िारेन्ट बमोत्तजम कसैलाई पक्राउ\nगदाय कसैले पमन बाधा मबरोध गन य िा गराउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई छ महिनासम्म कै द िा पााँच\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।\n(३) उपदफा (१) बमोत्तजमको कसूर राष्‍ट रसेिकले गरेको िए मनजलाई तीन\nमहिनासम्म थप कै द सजार् िनु ेछ।\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n31\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७६", "title": "समाह्वान, इतलार्नामा, सूचना िा आदेश नबझु ी फकाउय न निनु ेाः (१) कुनै व्र्त्तिलाई", "content": "मनजका नाममा कानून बमोत्तजम जारी िएको समाह्वान, इतलार्नामा, पक्राउ पूजी, सूचना\nिा आदेश बझु ाउन ल्र्ाएकोमा मनजले त्र्स्तो समाह्वान, इतलार्नामा, पक्राउ पूजी, सूचना\nिा आदेश बदमनर्तपूिकय नबझु ी फकायउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई तीन महिनासम्म कै द िा\nपााँच िजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७७", "title": "समाह्वान, इतलार्नामा, सूचना िा आदेश तामेल िनु नठदई छली हिड्न निनु ेाः (१)", "content": "अमधकार प्राप्त अमधकारीले जारी गरेको समाह्वान, इतलार्नामा, पक्राउ पूजी, सूचना िा\nआदेश बझु न ु पने व्र्त्तिले त्र्स्तो समाह्वान, इतलार्नामा, पक्राउ पूजी, सूचना िा आदेश\nतामेल िनु नठदनको लामग बठिर्तपूिकय छली हिड्न िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई तीन महिनासम्म कै द िा\nपााँच िजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७८", "title": "समाह्वान, इतलार्नामा इत्र्ाठद च्र्ात्न िा उप्काउन निनु ेाः (१) कसैले कानून बमोत्तजम", "content": "टााँसेको समाह्वान, इतलार्ानामा, पक्राउ पूजी, सूचना िा आदेश त्र्सको प्रर्ोजन बााँकी छाँदै\nबदमनर्तपूिकय च्र्ात्न िा उप्काउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजम कसूर गने िा गराउने व्र्त्तिलाई छ महिनासम्म\nकै द िा पााँच िजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७९", "title": "झठ्ठु ो तररकाले म्र्ाद तामेल गन य निनु ेाः (१) कानून बमोत्तजम म्र्ाद तामेल गने िा गराउन ु", "content": "पने कतव्य र् िएको व्र्त्तिले झट्टु ो तररकाले म्र्ाद तामेल गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई एक िषसय म्म कै द िा दश\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८०", "title": "मलित पेश गन य इन्कार गन य निनु ेाः (१) कानून बमोत्तजम कुनै अड्डा, अदालत िा", "content": "राष्‍ट रसेिक समि कुनै मलित पेश गन यु पने िा पठाउन ु पने कानूनी कतव्य र् िएको\nव्र्त्तिले त्र्स्तो मलित पेश गन य िा पठाउन इन्कार गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई छ महिनासम्म कै द िा पााँच\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८१", "title": "शपथ मलएको व्र्त्तिले झठ्ठु ा कुरा व्र्ि गन य निनु ेाः (१) अमधकार प्राप्त अमधकारी समि", "content": "सााँचो कुरा व्र्ि गने कानूनी कतव्य र् िएको िा शपथ मलएको व्र्त्तिले िा कानून\nबमोत्तजम शपथ मलई सािजय मनक पद धारण गरेको व्र्त्तिले त्र्स्तो िैमसर्तमा झठ्ठु ा कुरा\nव्र्ि गन य िाँदु ैन।\n32\nwww.lawcommission.gov.np\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई दईु िषसय म्म कै द िा बीस\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८२", "title": "शपथ गन य इन्कार गन य निनु ेाः (१) अमधकार प्राप्त अमधकारी समि सााँचो कुरा व्र्ि गन य", "content": "उपत्तस्थत िएको व्र्त्तिले त्र्स्तो कुरा व्र्ि गने प्रर्ोजनको लामग शपथ मलन आदेश\nठदएकोमा त्र्स्तो शपथ मलन इन्कार गन यु िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई तीन महिनासम्म कै द िा\nपााँच िजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८३", "title": "जिाफ ठदन इन्कार गन य निनु ेाः (१) अमधकार प्राप्त अमधकारी समि कुनै हिषर्मा सााँचो", "content": "कुरा व्र्ि गने कानूनी कतव्य र् िएको व्र्त्तिले त्र्स्तो हिषर्मा त्र्स्तो अमधकारीले\nसोधेको प्रश्नको जिाफ ठदन इन्कार गन य िाँदु ैन।\nतर कसैलाई पमन आफ्नो हिरुद्ध बर्ान ठदन कर लागने छैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई छ महिनासम्म कै द िा पााँच\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८४", "title": "झठ्ठु ा जानकारी ठदन निनु ेाः (१) कसैले कुनै राष्‍ट रसेिकलाई मनजले कानून बमोत्तजम गन यु", "content": "पने काम गनबय ाट रोक लगाउन िा गन य नपने िा गन य निनु े काम गन य लगाउने मनर्तले\nकसैलाई झठ्ठु ा जानकारी ठदन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई एक िषसय म्म कै द िा दश\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८५", "title": "बाधा हिरोध गन य निनु ेाः (१) आफ्नो पदीर् कतव्य र्को पालना गन य लागेको कुनै", "content": "राष्‍ट रसेिकलाई कसैले जोर जलु मु िा िूल िज्ु जत गरी िा अन्र् कुनै हकमसमले बाधा\nहिरोध गरी कतव्य र् पालन गन य अबरोध पर्ु ाउय न ु िाँदु ैन।\n(२) कसैले कानून बमोत्तजम िनु लागेको कुनै सम्पत्तिको जार्जात, तार्दाती, रोक्का,\nमललाम िा मबक्रीको प्रहक्रर्ामा जानीजानी बाधा हिरोध गन यु िाँदु ैन।\n(३) उपदफा (१) िा (२) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक\nिषसय म्म कै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८६", "title": "राष्‍टर सेिकलाई मद्दत ठदन इन्कार गन य निनु ेाः (१) कुनै राष्‍ट रसेिकले आफ्नो पदीर् कतव्य र्", "content": "पालन गदाय त्र्स्तो काममा मद्दत ठदन ु पने कानूनी कतव्य र् िएको व्र्त्तिले त्र्स बमोत्तजम\nमद्दत ठदन ईन्कार गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई छ महिनासम्म कै द िा पााँच\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।\n33\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८७", "title": "आदेशको अिज्ञा गन य निनु ेाः (१) कसैले अमधकारप्राप्त अमधकारीको कानून बमोत्तजमको", "content": "आदेश अनसु ार कानून बमोत्तजम गन यु पने काम नगरी िा गन य निनु े काम गरी त्र्स्तो\nआदेशको अिज्ञा गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई छ महिनासम्म कै द िा पााँच\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८८", "title": "िदम्र्ादाः र्स पररच्छेदको दफा ७८, ८० र ८३ अन्तगतय को कसूरमा त्र्स्तो कसूर", "content": "िएको कुरा थािा पाएको मममतले र अन्र् दफा अन्तगतय का कसूरमा त्र्स्तो कसूर िएको\nमममतले तीन महिना नाघेपमछ उजरु लागने छैन।\nपररच्छेद-४\nसािजय मनक न्र्ार् हिरुद्धका कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८९", "title": "झठ्ठु ा प्रमाण बनाउन निनु ेाः (१) र्स संहितामा अन्र्था व्र्िस्था िएकोमा बािेक कसैले", "content": "न्र्ाहर्क िा अन्र् कानूनी कारबािीमा प्रमाणको रुपमा प्रर्ोग गराउने मनर्तले कुनै झठ्ठु ा\nप्रमाण बनाउन िा झठ्ठु ा पररत्तस्थमतको मसजनय ा गन य िा कुनै झठ्ठु ा मलित िा हिद्यतु ीर्\nअमिलेि बनाउन िा कुनै मलित िा हिद्यतु ीर् अमिलेिमा झठ्ठु ा कुरा जनाउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई पााँच िषसय म्म\nकै द र पचास िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\nतर त्र्स्तो झठ्ठु ा प्रमाणको आधारमा कुनै व्र्त्तिलाई जन्मकै दको सजार् िएको\nरिेछ िने सात िषसय म्म कै द र सिरी िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\n(३) र्स दफामा अन्र्र जनु सकु ै कुरा लेत्तिएको िए तापमन जनु कसूरको\nसम्बन्धमा झठ्ठु ा प्रमाण िडा िएको िो त्र्स्तो कसूरमा िनु सक्ने अमधकतम सजार्िन्दा\nबढी िनु े गरी र्ो दफा अन्तगतय सजार् िनु े छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९०", "title": "झठ्ठु ा प्रमाण पर बनाउन र ठदन निनु ेाः (१) कुनै कुराको सम्बन्धमा कानून बमोत्तजम पेश", "content": "गने, प्रमात्तणत गने, प्रमाणीकरण गने, सत्र्तथ्र्र्िु हििरण (एहफडेमिट) पेश गने िा\nप्रमाणपर ठदने अत्तख्तर्ारी िा कतव्य र् िएको व्र्त्तिले जानीजानी झठ्ठु ा कुरा उल्लेि गरी\nपेश गन,य प्रमात्तणत गन,य प्रमाणीकरण गन य िा प्रमाणपर ठदन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई दईु िषसय म्म\nकै द र बीस िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\n34\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९१", "title": "झठ्ठु ा प्रमाण िा प्रमाण पर प्रर्ोग गन य निनु ेाः (१) कसैले कुनै प्रमाण िा प्रमाणपर झठ्ठु ा", "content": "िो िन् ने जानीजानी त्र्स्तो प्रमाण िा प्रमाणपरलाई सााँचो प्रमाण िा प्रमाणपरको रुपमा\nप्रर्ोग गन य िा गराउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई तीन िषसय म्म कै द र तीस\nिजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९२", "title": "मलित नष्‍टट गन य निनु ेाः (१) कुनै न्र्ाहर्क िा अन्र् कानूनी कारबािीमा कुनै मलित िा", "content": "हिद्यतु ीर् अमिलेि प्रमाणको रुपमा पेश गने कानूनी कतव्य र् िएको व्र्त्तिले जानीजानी\nत्र्स्तो मलित िा अमिलेि नष्‍ट ट गन,य के रमेट गरी नबत्तुझने पान य िा अन्र् कुनै प्रकारले\nप्रमाणमा प्रर्ोग गन य नममल्ने बनाउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई दईु िषसय म्म\nकै द र बीस िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\n(३) कुनै न्र्ाहर्क िा अन्र् कानूनी कारबािीमा पेश िएको कुनै मलित िा\nहिद्यतु ीर् अमिलेि कसैले कानून हिपरीत जानीजानी नष्‍ट ट गन,य के रमेट गरी नबत्तुझने पान य\nिा अन्र् कुनै प्रकारले प्रमाणमा प्रर्ोग गन य नममल्ने बनाउन िा गैरकानूनी रुपमा िटाउन\nिा अनमधकृ त रुपमा कसैलाई ठदन ु िाँदु ैन।\n(४) उपदफा (३) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई चार िषसय म्म\nकै द र चालीस िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\n(५) उपदफा (१) िा (३) बमोत्तजमको कसूर कुनै राष्‍ट रसेिकले गरेमा मनजलाई\nसोिी उपदफामा उत्तल्लत्तित सजार्को दोब्बर सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९३", "title": "कसूरको प्रमाण दिाउन निनु ेाः (१) कसैले कुनै कसूरदारलाई बचाउने मनर्तले मनजले", "content": "गरेको कसूर सम्बन्धी कुनै प्रमाण दबाउन, नष्‍ट ट गन य िा त्र्सलाई प्रमाणको रुपमा प्रर्ोग\nगन य नसहकने गरी मबगान य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द र तीस िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९४", "title": "सूचना ठदन अिरोध पर्ु ाउय न निनु ेाः (१) कुनै कसूर िएको िा िनु लागेको छ िन् ने थािा", "content": "पाई त्र्स्तो कसूरको हिषर्मा प्रिरी िा अमधकार प्राप्त अमधकारी समि िबर िा सूचना\nठदन जाने व्र्त्तिलाई कसैले छेकथनु गन य िा अन्र् कुनै हकमसमले बाधा अिरोध पर्ु ाउय न ु\nिाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई दईु िषसय म्म\nकै द िा बीस िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।\n35\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९५", "title": "कसूरदारलाई आश्रर् ठदन निनु ेाः (१) कसैले कुनै कसूरदारलाई जानीजानी पक्राउ िनु बाट", "content": "िा कानून बमोत्तजम िनु े सजार्बाट बचाउने मनर्तले आश्रर् ठदन ु िाँदु ैन।\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनको लामग “कसूरदार” िन् नाले कुनै कसूरमा शङ्कास्पद\nरिेको, अमिर्िु बनाइएको िा अदालतबाट दोषी ठिर िएको व्र्त्ति सम्झन ु पछ।य\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई देिार् बमोत्तजम\nसजार् िनु ेछाः-\n(क) जन्मकै द िा बीस िषसय म्म कै द सजार् िनु सक्ने कसूरको\nकसूरदारलाई आश्रर् ठदएको िए पााँच िषसय म्म कै द र पचास\nिजार रुपैर्ासाँ म्म जररबाना,\n(ि) दश िषसय म्म कै दको सजार् िनु सक्ने कसूरको कसूरदारलाई\nआश्रर् ठदएको िए तीन िषसय म्म कै द र तीस िजार रुपैर्ााँसम्म\nजररबाना,\n(ग) िण्ड (क) िा (ि) मा लेत्तिएदेत्ति बािेक अन्र् कसूरको\nकसूरदारलाई आश्रर् ठदएको िए त्र्स्तो कसूरमा िनु सक्ने कै द\nिा जररबानाको उपल्लो िदको चार िण्डको एक िण्डसम्म कै द\nिा जररबाना िा दिु ै।\n(३) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापमन कसूरदारको पमत िा\nपत्नी िा बाब,ु आमा, छोरा, छोरी, दाज,ु िाइ, ठददी, बहिनी, बाजे, बज्र्ै, नामत, नामतनी, सास,ु\nससरु ा, बिु ारी, ज्िाइाँले आश्रर् ठदएकोमा र्स दफा बमोत्तजमको कसूर िएको मामनने\nछैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९६", "title": "कसूर िएको जानकारी ठदन ु पनेाः (१) कुनै कसूर िएको िा िनु लागेको छ िन् ने थािा", "content": "पाई त्र्स्तो कसूरको जानकारी ठदन ु पने कानूनी कतव्य र् िएको व्र्त्तिले जानकारी नठदई\nबस्न िा कुनै कसूर िएको थािा पाएको व्र्त्तिले जानीजानी झठ्ठु ा जानकारी ठदन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई दईु िषसय म्म कै द िा बीस\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९७", "title": "सम्पत्ति दिाउन िा सम्पत्तिमा झठ्ठु ा दािी गन य निनु ेाः (१) कसैले अदालत िा अमधकार", "content": "प्राप्त अमधकारीको मनणर्य बमोत्तजम जफत िनु े िएको िा तार्दाती, रोक्का, मललाम िा मबक्री\nिनु े िा चलन चलाई ठदन ु पने िएको सम्पत्ति िा त्र्स्तो सम्पत्ति िा जार्जात उपरको\nअमधकार िदमनर्त साथ जफत, तार्दाती, जार्जात, रोक्का, मललाम िा मबक्री िनु बाट िा\nचलन चलाउनबाट रोक्नको लामग त्र्स्तो सम्पत्ति िा त्र्स उपरको अमधकार दबाउन,\n36\nwww.lawcommission.gov.np\nकसैलाई िस्तान्तरण गन य िा गराउन िा त्र्स्तो सम्पत्ति िा अमधकार उपर दािी गन य\nिाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई दईु िषसय म्म\nकै द िा बीस िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९८", "title": "झठ्ठु ा उजरु ी ठदन निनु ेाः (१) कसैले कसैलाई िमत पर्ु ायउने िा िैरान गने मनर्तले कुनै", "content": "न्र्ाहर्क कारबािी गने अमधकारी समि झठ्ठु ा कुराको दािी मलई िा अमिर्ोग लगाई कुनै\nव्र्त्तिका हिरुद्ध उजरु ी िा सूचना ठदन ु िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई जनु कसूरको\nझठु ो अमिर्ोग लगाएको िो त्र्स्तो कसूरमा िनु सक्ने सजार्को उपल्लो िदको\nआधासम्म सजार् िनु ेछ।\nतर नेपाल सरकारिादी िनु े मद्दु ाको िकमा र्स दफाको व्र्िस्था लागू िनु े\nछैन।\n(३) उपदफा (१) बमोत्तजमको कसूरबाट पीमडत व्र्त्तिलाई कुनै हकमसमको िामन,\nनोक्सानी पगु ेको िए मनजलाई त्र्स बापतको िमतपूमत य कसूरदारबाट िराई ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९९", "title": "बदमनर्तपिू कय अनसु न्धान िा अमिर्ोजन गन य निनु ेाः (१) कानून बमोत्तजम अनसु न्धान िा", "content": "अमिर्ोजन गने त्तजम्मेिारी िएको अमधकारीले मनदोष व्र्त्तिलाई फसाउने िा िास्तहिक\nकसूरदारलाई जोगाउने मनसार्ले बदमनर्तपूिकय अनसु न्धान गन य िा अमिर्ोग लगाउन ु\nिाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई छ महिनासम्म\nकै द िा पााँच िजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।\n(३) उपदफा (१) बमोत्तजमको कसूरबाट कुनै व्र्त्तिलाई कुनै हकमसमको िामन,\nनोक्सानी िएमा मनजले त्र्स्तो कसूरदारबाट िमतपूमत य िराई मलन सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१००", "title": "जमानतको शत य हिपरीत अनपु त्तस्थत िनु निनु ेाः (१) कुनै कसूरको अमिर्ोग लामग", "content": "जमानतमा छुटेको व्र्त्ति मनामसब कारण हिना जमानतको शत य हिपरीत जमानत ठदएको\nकार्ायलर् िा अदालतमा अनपु त्तस्थत िनु ु िाँदु ैन।\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनको लामग “जमानत” िन् नाले नगद,  जेथा, बैङ्क जमानत\nिा िात्तजर जमानत सम्झन ु पछ।य\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n37\nwww.lawcommission.gov.np\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई एक िषसय म्म कै द िा दश\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।\n(३) र्स दफा बमोत्तजम अनपु त्तस्थत िएको व्र्त्ति मनजलाई आरोप लागेको\nकसूरको कसूरदार ठिररएमा मनजलाई त्र्स्तो कसूरमा िनु े सजार्मा र्स दफा\nबमोत्तजमको सजार् समेत थप िनु ेछ।\n(४) कानून बमोत्तजम िात्तजर जमानीमा छुटेको व्र्त्ति त्र्स्तो जमानत बमोत्तजम\nकार्ायलर् िा अदालतमा उपत्तस्थत निएमा त्र्सरी िात्तजर जमानी ठदने व्र्त्तिलाई पचास\nिजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\n(५) र्स दफा बमोत्तजम सजार् पाएको व्र्त्ति तीन िषसय म्म िात्तजर जमानी िनु\nर्ोगर् िनु े छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१०१", "title": "पक्राउको बाधा हिरोध गन य िा थनु ाबाट िागन निनु ेाः (१) कुनै व्र्त्तिलाई पक्राउ गन य", "content": "कानून बमोत्तजम पक्राउ पूजी जारी िएकोमा त्र्स्तो व्र्त्तिले पक्राउको मसलमसलामा िा\nपक्राउ पदाय िा पक्राउ पररसके को िए पक्राउबाट बच्नको लामग जानीजानी बल प्रर्ोग\nगरी बाधा हिरोध गन य िा कानून बमोत्तजम थनु ामा रिेको व्र्त्तिले थनु ाबाट िागन िा\nिागने उद्योग गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द िा तीस िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१०२", "title": "पक्राउबाट उम्काउन िा थनु ाबाट िगाउन निनु ेाः (१) कानून बमोत्तजम पक्राउ गन य पक्राउ", "content": "पूजी जारी गररएको व्र्त्तिलाई पक्राउको मसलमसलामा िा पक्राउ गदा य िा मनजलाई\nपक्राउ गररसके को िए मनजलाई पक्राउबाट उम्काउनको लामग कसैले जानीजानी बाधा\nमबरोध गन य िा कानून बमोत्तजम थनु ामा रिेको व्र्त्तिलाई जानीजानी िगाउन िा िागनको\nलामग मद्दत गन यु िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द िा तीस िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।\n(३) उपदफा (१) बमोत्तजमको कसूर कुनै राष्‍ट रसेिकले गरे िा गराएमा मनजलाई\nउपदफा (२) मा उत्तल्लत्तित सजार्को दोब्बर सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१०३", "title": "िदम्र्ादाः (१) दफा १०१ िा १०२ अन्तगतय का कसूरमा जहिलेसकु ै पमन उजरु", "content": "लागनेछ।\n38\nwww.lawcommission.gov.np\n(२) दफा १०० अन्तगतय को कसूरमा त्र्स्तो कसूर िएको मममतले र र्स\nपररच्छेद अन्तगतय का अन्र् कसूरमा कसूर िएको कुरा थािा पाएको मममतले तीन महिना\nनाघेपमछ उजरु लागने छैन।\nपररच्छेद-५\nसािजय मनक हित, स्िास्थ्र्, सरु िा, सहुिधा र नैमतकता हिरुद्धका कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१०४", "title": "सङ्क्क्रामक रोग फै लाउन निनु ेाः (१) कसैले कसैको ज्र्ानलाई ितरा पर्ु ाउय न सक्ने कुनै", "content": "हकमसमको सङ्क्क्रामक रोग फै लाउने िा फै मलन सक्ने कुनै काम गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई मनर्तपूिकय िा\nजानीजानी गरेको िए दश िषसय म्म कै द र एक लाि रुपैर्ााँसम्म जररबाना,\nलापरिािीपूिकय गरेको िए पााँच िषसय म्म कै द र पचास िजार रुपैर्ााँसम्म जररबाना र\nिेलचक्राईँपूिकय गरेको िए तीन िषसय म्म कै द र तीस िजार रुपैर्ासाँ म्म जररबाना\nिनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१०५", "title": "मानि रोग प्रमतरोधक िमता उन्मत्तुि गने त्तजिाण ु (एच.आई.िी.) को रोग फै लाउन निनु ेाः", "content": "(१) कसैले आफनो िा अरु कसैको शरीरमा रोग प्रमतरोधक िमता उन्मत्तुि गने त्तजिाणु\n(एच.आइ.िी.) िा िेपाटाइहटस ् बी को त्तजिाण ु रिेको थािा पाउाँ दा पाउाँदै कसैलाई त्र्स्तो\nरोग साने मनर्तले आफ्नो रगत ठदन िा त्र्स्तो व्र्त्तिको रगत ठदन लगाउन िा कुनै\nहकमसमको पूि य सािधानी नमलई कसैसाँग र्ौन सम्पकय कार्म गन य िा कुनै हकमसमबाट\nआफ्नो िा त्र्स्तो व्र्त्तिको रगत, िीर्,य ¥र्ाल, थकु िा कुनै मानि अङ्ग अकायको शरीरमिर\nपठाउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजम कसूर गने िा गराउने व्र्त्तिलाई दश िषसय म्म कै द\nर एक लाि रुपैर्ााँसम्म जररबाना िनु ेछ।\nतर त्र्स्तो रोग साने मनर्त निई लापरबािी िा िेलचेक्र्र्ाइाँबाट सन य गएको रिेछ\nिने तीन िषसय म्म कै द र तीस िजार रुपैर्ााँसम्म जररबाना िनु ेछ।\n(३) पीमडत आफैँ मानि रोग प्रमतरोधक िमता उन्मत्तुि गने त्तजिाण ु िा\nिेपाटाइहटस ् बी को त्तजिाण ु रिेको व्र्त्तिसाँग र्ौन सम्पकय गन य गएको रिेछ िने त्र्स्तो\nत्तजिाण ु रिेको व्र्त्तिले र्स दफा बमोत्तजमको कसूर गरेको मामनने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१०६", "title": "सरुिा रोग सम्बन्धी कानूनको उल्लङ्घन गन य निनु ेाः (१) कसैले नेपाल सरकार, प्रदेश", "content": "सरकार िा स्थानीर् तिले िा कानून बमोत्तजम अमधकार प्राप्त अमधकारीले सरुिा रोगको\nसम्बन्धमा जारी गरेको मनर्म, मनदेशन िा आदेश उल्लङ्घन गन य िाँदु ैन।\n39\nwww.lawcommission.gov.np\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई छ महिनासम्म\nकै द िा पााँच िजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।\nतर त्र्स्तो मनर्म, मनदेशन िा आदेश उल्लङ्घन गरेको कारणबाट कसैको ज्र्ान\nजान सक्ने अिस्था रिेछ िने मनजलाई दफा १०४ बमोत्तजम सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१०७", "title": "िाद्य पदाथमय ा ममसािट गन य निनु ेाः (१) कसैले सिसय ाधारणले िाने, हपउने िा सेिन गने", "content": "पदाथमय ा िान, हपउन िा सेिन गन य निनु े कुनै िामनकारक पदाथ य िा िान हपउन िा सेिन\nगन य िनु े कमसल पदाथ य िा िामनकारक रासार्मनक पदाथ य ममसािट गरी उत्पादन गन,य\nमबक्री हितरण गन य िा म्र्ाद नाघेको िा ममसािट िएको िाद्य पदाथ य मबक्री हितरण गन य\nिा मनधायररत स्तरिन्दा न्र्ून स्तरको िाद्य पदाथ य िा अिाद्य पदाथ य मबक्री हितरण गन य िा\nपैठारी गन य िा मबक्री हितरणको लामग राख् न िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई पााँच िषसय म्म\nकै द र पचास िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१०८", "title": "झक्ु र्ानमा पारी िाद्य पदाथ य मबक्री हितरण गन य निनु ेाः (१) कसैले कुनै एक िाद्य", "content": "पदाथलय ाई अको िाद्य पदाथ य िो िनी िा न्र्ून गणु स्तरको िाद्य पदाथ य िा अिाद्य\nपदाथलय ाई उच्च गणु स्तरको िाद्य पदाथ य िो िनी ढााँटी िा झक्ु र्ाई िा कुनै उच्च\nगणु स्तरको िाद्य पदाथमय ा मनम्न स्तरको िाद्य पदाथ य िा अिाद्य पदाथ य ममसािट गरी\nमबक्री हितरण गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई पााँच िषसय म्म\nकै द िा पचास िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१०९", "title": "झक्ु र्ानमा पारी कुनै िस्त ु मबक्री–हितरण गन य निनु ेाः (१) कसैले िाद्य पदाथ य बािेक", "content": "कमसल िस्तलु ाई असल िस्त ु िो िनी िा एक िस्तलु ाई अको िस्त ु िो िन् ने िान पारी\nिा कुनै िस्तमु ा त्र्स्तो िस्तकु ो गणु स्तर घट्ने गरी ममसािट गरी मबक्री गन य िा कुनै\nिस्तमु ा रिेको लेिल साट्न िा म्र्ाद नाघेको िस्त ु मबक्री गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द िा तीस िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "११०", "title": "मबक्री गने उपिोगर्िस्त ु मबक्री नगरी जम्मािोरी गन य निनु ेाः (१) कसैले कुनै उपिोगर्", "content": "िस्तकु ो बजारमा कृ मरम अिाि िडा गरी त्र्स्तो िस्तकु ो मूल्र् िहृद्ध गन य िा त्र्स्तो िस्त ु\nबढी मूल्र्मा मबक्री गन य िा गराउन िा त्र्स्तो िस्तकु ो मबक्रीबाट अनत्तुचत नाफा मलने\nउद्देश्र्ले त्र्स्तो िस्त ु मबक्री हितरण नगरी थपु ान य िा सत्तित गरी राख् न िा जम्मािोरी\nगन य िाँदु ैन।\n40\nwww.lawcommission.gov.np\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई पााँच िषसय म्म\nकै द र पचास िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१११", "title": "पानी दहुषत पान य निनु ेाः (१) कसैले सिसय ाधारणले हपउने पानी िा हपउने पानीको", "content": "मिु ानलाई हपउन निनु े गरी दहुषत गन य िा हपउने बािेक अन्र् कुनै काममा प्रर्ोग िनु े\nपानीलाई त्र्स्तो काममा प्रर्ोग गन य निनु े गरी दहुषत पान य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई देिार्\nबमोत्तजमको सजार् िनु ेछाः-\n(क) हपउने पानी िा पानीको मिु ान दहुषत गने िा गराउने व्र्त्तिलाई\nतीन िषसय म्म कै द िा तीस िजार रुपैर्ााँसम्म जररबाना िा दिु ै\nसजार्,\n(ि) अन्र् प्रर्ोजनका लामग प्रर्ोग िनु े पानी दहुषत पाने िा पान य\nलगाउने व्र्त्तिलाई छ महिनासम्म कै द िा पााँच िजार रुपैर्ााँसम्म\nजररबाना िा दिु ै सजार्।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "११२", "title": "िातािरण प्रदहुषत गन य निनु ेाः (१) कसैले िातािरणमा उल्लेिनीर् प्रमतकू ल प्रिाि पर्ु ायउने", "content": "\nगरी फोिोरमैलाको उत्पादन, प्रशोधन, प्रसारण, मनष्‍टकाशन, उत्सजनय , ओसारपसार गन य िा\nथपु ान य िाँदु ैन।\n(२) कसैले सिसय ाधारणको स्िास्थ्र्मा िामन पर्ु ायउने गरी िा जीउ ज्र्ानको लामग\nितरा िनु सक्ने गरी प्रदृषण गन य िा कानून बमोत्तजम अमधकार प्राप्त अमधकारीको इजाजत\nहिना र्ात्तन्रक साधनबाट ध्िनी, ताप, रेमडर्ोधमी हिहकरण िा जोत्तिमपूण य फोिर मैलाको\n\nउत्पादन, प्रशोधन, प्रसारण, मनष्‍टकाशन, उत्सजनय , ओसारपसार गन य िा थपु ान य िदु ैन।\n(३) उपदफा (१) बमोत्तजम कसूर गने िा गराउने व्र्त्तिलाई एक िषसय म्म कै द\nिा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।\n(४) उपदफा (२) िमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई पााँच िषसय म्म\nकै द िा पचास िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "११३", "title": "सािजय मनक बाटो, नदी िा स्थलमा ितरा िा बाधा पर्ु ाउय न निनु ेाः (१) कसैले कुनै काम", "content": "गरी िा आफ्नो िा आफ्नो मनर्न्रण िा त्तजम्मामा रिेको सम्पत्तिको स्र्ािार सम्िार नगरी\nसािजय मनक बाटो, नदी िा अन्र् कुनै सािजय मनक स्थलमा कसैलाई कुनै ितरा, बाधा िा\nअबरोध पर्ु ायउन िाँदु ैन।\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n41\nwww.lawcommission.gov.np\n(२) उपदफा (१) बमोत्तजम कसूर गने िा गराउने व्र्त्तिलाई पच्चीस िजार\nरुपैर्ााँसम्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "११४", "title": "हिषाल ु िा हिष्‍टफोटक पदाथ य प्रर्ोग गदा य लापरबािी गन य निनु ेाः (१) कसैले हिषाल ु पदाथ,य", "content": "आगोजन्र् पदाथ,य प्रज्िलनशील पदाथ,य हिष्‍टफोटक पदाथ य िा जोत्तिमी िमतर्ार िा र्न्र\nचलाउाँदा िा प्रर्ोग गदाय कसैको शरीर िा ज्र्ानमा ितरा िा िमत पगु न सक्ने गरी\nलापरबािी गन य िा आफ्नो िा आफ्नो कब्जा िा त्तजम्मा रिेको त्र्स्तो बस्तबु ाट कसैको\nज्र्ान जान सक्ने ितरालाई रोक्ने आिश्र्क बन्दोबस्त जानीजानी नगन य िा त्र्स्तो\nबन्दोिस्त गनमय ा लापरबािी गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक िषसय म्म\nकै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "११५", "title": "घर मनमाणय गदा,य ित्काउाँदा िा ममतय गदा य लापरबािी गन य निनु ेाः (१) कसैले घर मनमायण", "content": "गदाय, ित्काउाँदा िा ममतय गदाय त्र्स्तो कार्बय ाट िा त्र्स्तो घर िा त्र्सको के िी िाग\nढली िा िसी कसैको ज्र्ान जान िा अङ्गिङ्ग िनु सक्ने ितरालाई रोक्न िा टान य\nआिश्र्क बन्दोबस्त नगरी िा त्र्स्तो बन्दोबस्त गन य लापरबािी गरी घर मनमायण गन,य\nित्काउन िा ममतय गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई एक िषसय म्म कै द िा दश\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "११६", "title": "पशपु ंिी राख्दा लापरबािी गन य निनु ेाः (१) कसैले आफ्नो िा आफ्नो मनर्न्रण िा", "content": "त्तजम्मामा रिेको हिंस्रक िा अन्र् कुनै पशपु ंिी राख्दा िा पाल्दा त्र्स्तो कार्बय ाट िा\nत्र्स्तो पशपु ंिीबाट कसैको ज्र्ान जान सक्ने िा कसैलाई चोट पगु न सक्ने ितरालाई\nरोक्न आिश्र्क पूिसय ािधानीको बन्दोिस्त नगरी िा लापरबािी गरी त्र्स्तो पशपु ंिी\nराख् न िा पाल्न िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक िषसय म्म\nकै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "११७", "title": "पशपु ंिी छाडा छाड्न निनु ेाः कसैले आफ्नो िा आफ्नो मनर्न्रण िा त्तजम्मा रिेको कुनै", "content": "पशपु ंिी अकायको घर, जगगामा िा सािजय मनक बाटो घाटो िा सािजय मनक स्थलमा छाडा\nछोड्न िाँदु ैन।\n(२) उपदफा (१) बमोत्तजम कसूर गने िा गराउने व्र्त्तिलाई तीन महिनासम्म\nकै द िा पााँच िजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।\n42\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "११८", "title": "अिद्र व्र्ििार गन य निनु ेाः (१) कसैले सािजय मनक स्थान िा प्रिेश गन य कानूनी अमधकार", "content": "निएको ठाउाँमा प्रिेश गरी कसैलाई अिद्र व्र्ििार गन य िा सािजय मनक स्थानमा महिला,\nबालबामलका िा शारीररक रुपमा अशि व्र्त्तिलाई िातपात िा िैरानी गन य िा त्र्सको\nउद्योग गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक िषसय म्म\nकै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "११९", "title": "िेश्र्ागमनको प्रचार गन य निनु ेाः (१) कसैले िेश्र्ागमनको लामग प्रचार, प्रसार गन य", "content": "िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाईय तीन िषसय म्म\nकै द र तीस िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२०", "title": "िेश्र्ािमृत िा िश्े र्ागमनका लामग घर, जगगा प्रर्ोग गन य ठदन निनु ेाः (१) कसैले िेश्र्ाित्तृि", "content": "िा िेश्र्ागमनको लामग जानीजानी आफ्नो घर, जगगा, सिारी साधन उपलव्ध गराउन\nिाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई छ महिनासम्म कै द िा पााँच\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२१", "title": "अत्तश्ल ल हकताब, पचा य इत्र्ाठद बनाउन िा मबक्री गन य निनु ेाः (१) कसैले सािजय मनक रुपमा", "content": "अत्तश्ल ल हकताब, पचाय बनाउने लगार्तका देिार्को कुनै काम गन य िाँदु ैनाः-\n(क) शारीररक कामोिेजना बढाउने िा काम िासनामा आशि गराउने\nिा चरररिीन बनाउने कुनै अश्लील हकताब, पचाय, रेिात्तचर, चलत्तचर,\nतस्िीर, रेकड य िा अरु कुनै िस्त ु बनाउन, मद्रु ण गन य िा प्रकात्तशत\nगन य िा हिद्यतु ीर् सिार माध्र्मबाट प्रचार प्रसार गन,य\n(ि) त्र्स्तो अश्लील िस्त ु िरीद मबक्री िा हितरण गन य िा िाडामा ठदन\nिा सिसय ाधारणलाई देिाउन िा त्र्स्तो गने मनर्तले आपm्ना\nसाथमा राख् न,\n(ग) कुनै व्र्त्तिबाट त्र्स्तो अत्तश्ल ल िस्त ु र्स प्रकार प्राप्त िनु सक्छ\nिनी हिज्ञापन ठदन,\n(घ) त्र्स्तो अत्तश्ल ल िस्त ु मबक्री हितरण गने उद्देश्र्ले मनकासी िा\nपैठारी गन य िा आफू साँग बोक्न।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक िषसय म्म\nकै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।\n43\nwww.lawcommission.gov.np\n(३) र्स दफामा अन्र्र जनु सकु ै कुरा लेत्तिएको िए तापमन िैज्ञामनक, शैत्तिक,\nकलात्मक, साहित्तत्र्क, अनसु न्धानमूलक, ज्ञानिद्र्र्धक मित्ि िा अमिरुचीको िा धाममकय\nप्रर्ोजनको लामग रात्तिएको िा बनाइएको कुनै कृ मतको िकमा र्स दफाको व्र्िस्था लागू\nिनु े छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२२", "title": "सािजय मनक स्थानमा र्ौनाङ्ग देिाउन निनु ेाः (१) दश िषिय न्दा मामथको व्र्त्तिले स्िास्थ्र्", "content": "हिज्ञान िा त्तचहकत्सा सम्बन्धी उपचारको प्रर्ोजनका लामग बािेक सािजय मनक स्थानमा\nअश्लील कृ र्ाकलाप िा व्र्ििार गन य िा र्ौनाङ्ग देिाउन िा कसैलाई अत्तश्ल ल शब्द बोल्न\nिा इशारा गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई छ महिनासम्म कै द िा पााँच\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२३", "title": "सािजय मनक स्थानमा र्ौन हक्रर्ा गन य निनु ेाः (१) कसैले सािजय मनक स्थानमा िा अरु", "content": "मामनसले देख्न े गरी अन्र् कुनै स्थानमा कसैसाँग र्ौन हक्रर्ा गन य िा कुनै हकमसमको\nअप्राकृ मतक मैथनु गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई एक िषसय म्म कै द िा दश\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२४", "title": "सािजय मनक उपद्रर्ाईं गन य निनु ेाः (१) कानूनमा अन्र्था व्र्िस्था िएकोमा बािेक कसैले", "content": "कुनै काम गरी िा कानून बमोत्तजम गन यु पने कुनै काम नगरी छरमछमेक िा\nसिसय ाधारणलाई कुनै प्रकारको िामन, नोक्सानी, िमत िा ितरा पर्ु ायउन िा त्तझिm्र्ािट गन य\nिाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई पच्चीस िजार रुपैर्ााँसम्म\nजररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२५", "title": "जिु ा िेल्न िा सट्टाबाजी गन यु निनु ेाः (१) कसैले जिु ा िेल्न ु िा िेलाउन ु िाँदु ैन।", "content": "(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई देिार् बमोत्तजमको सजार्\nिनु ेछाः-\n(क) पहिलो पटक जिु ा िेल्ने िा िेलाउनेलाई तीन महिनासम्म कै द\nिा तीसिजार रुपैर्ााँसम्म जररबाना,\n(ि) दोस्रो पटकदेत्ति जिु ा िेल्ने िा िेलाउनेलाई एक िषसय म्म कै द र\nपचास िजार रुपैर्ासाँ म्म जररबाना र त्र्सपमछको कसूरमा पटकै\nहपच्छे थप तीन महिनासम्म कै द र दश िजार रुपैर्ााँसम्म\nजररबाना।\n44\nwww.lawcommission.gov.np\nस्पष्‍ट टीकरणाः र्स संहिताको प्रर्ोजनको लामगाः\n(१) “जिु ा” िन् नाले कुनै संर्ोगको आधारमा कुनै हकमसमको चल िा अचल\nसम्पत्ति िा प्रमतफल पाउने िा गमु ाउने िा िाने िा त्तजत्ने गरी बाजी थापी\nिेल्ने कुनै हकमसमको िेल िा प्रहक्रर्ा सम्झन ु पछ य र सो शब्दले आफू ले\nजिु ा निेली अरुको िार िा त्तजतमा आफू ले कुनै चल अचल सम्पत्ति िा\nप्रमतफल पाउने िा गमु ाउने गरी थापेको बाजी िा च्र्ााँिेलाई समेत\nजनाउाँछ।\nतर देिार्को कुनै िेल िा कार्क्रय मलाई जिु ा मामनने छैनाः–\n(क) कुनै सािजय मनक मिोत्सि, मेला, पि,य चाड, प्रदशनय ी\nिा समारोिमा मनोरञ्जनका लामग कुनै सानोमतनो\nचल सम्पत्ति पाउने िा गमु ाउने गरी नेपाल\nसरकारको स्िीकृ मत मलई सञ् चालन िनु े िेल,\n(ि) अमधकार प्राप्त अमधकारीको स्िीकृ मत मलई\nसञ् चालन िएको त्तचठ्ठा।\n(२) “जिु ा िेलाउने” िन् नाले आफ्नो िक, िोग, चलन, स्िाममत्ि िा त्तजम्मामा\nरिेको घर, कोठा, ठाउाँ िा सिारी साधन जानीजानी उपलब्ध गराई िा\nजिु ा िेल्नको लामग कुनै हकमसमको साधन उपलब्ध गराई जिु ा िेलाउने\nव्र्त्ति सम्झन ु पछ।य\n(३) जिु ा िेल्न प्रर्ोग िएको साधन र जिु ाबाट प्राप्त सम्पूण य चल अचल\nसम्पत्ति जफत िनु ेछ।\nतर जिु ा िेलेको घर, कोठा, ठाउाँ िा सिारी साधन जफत िनु े छैन।\n(४) कसैले सट्टाबाजी गन यु िा गराउन ु िाँदु ैन।\n(५) उपदफा (४) को प्रर्ोजनको लामग कसैले कानून बमोत्तजम िेल्न िेलाउन\nिनु े कुनै िेल िा प्रहक्रर्ामा िास पिले िारेमा िा त्तजतेमा कुनै चल अचल सम्पत्ति िा\nप्रमतफल पाउने िा गमु ाउने गरी बाजी थापेमा सट्टाबाजीको कसूर गरेको मामननेछ।\n(६) उपदफा (४) बमोत्तजमको कसूर िएमा त्र्समा प्रर्ोग िएको हिगो जफत\nगरी कसूर गने व्र्त्तिलाई एक िषसय म्म कै द र दश िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\n(७) र्स दफा बमोत्तजमको कसूरमा पटके कार्म गदाय अदालतबाट कसूरदार\nठिरेको आधारमा कार्म गररनेछ।\n45\nwww.lawcommission.gov.np\n\n१२५क. िण्ु डी सम्बन्धी कारोबार गन य निनु ेाः (१) कसैले पमन िण्ु डी सम्बन्धी कारोबार गन य िा\nगराउन िाँदु ैन।\nस्पष्‍ट टीकरण: र्स दफाको प्रर्ोजनको लामग \"िण्ु डी सम्बन्धी कारोबार\" िन् नाले प्रचमलत\nकानून बमोत्तजम मान्र्ताप्राप्त संस्था िा ििु ानी उपकरणको माध्र्मबाट बािेक अन्र्\nव्र्त्ति, उपकरण िा अन्र् कुनै पमन माध्र्मबाट नेपालबाट हिदेशमा िा हिदेशबाट\nनेपालमा कुनै रकम िा मूल्र् स्थानान्तर िा हिसाब ममलान िा ििु ानी मलने, ठदने िा िनु े\nगरी व्र्िसार् बनाई गररने कारोबार सम्झन ु पछय।\n(२) उपदफा (१) हिपरीत कसैले कुनै व्र्ािसाहर्क कारोबारको िास्तहिक\nहिसाब हकताब नदेत्तिने गरी सो सम्बन्धी रकम कुनै पमन माध्र्मबाट ििु ानी मलने ठदने\nगन यु िाँदु ैन।\n(३) कसैले उपदफा (१) िा (२) बमोत्तजमको कसूर गरेमा मबगो र सोबाट बढे\nिा बढाएको सम्पत्ति समेत जफत गरी एक िषसय म्म कै द िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२६", "title": "मििा मागन िा मागन लगाउन निनु ेाः (१) कसैले कुनै सािजय मनक स्थानमा मििा मागन", "content": "िा बालबामलकालाई गीत गाउने, नाच्ने, िेल्ने िा कुनै काम गने ििानामा िा अन्र्\nव्र्त्तिलाई कुनै प्रकारको रकम िा ज्र्ाला ठदई मििा मागन िा मििा मागन दरुु त्सािन\nठदन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई देिार् बमोत्तजमको सजार्\nिनु ेछ र मििाको मबगो जफत समेत िनु ेछाः-\n(क) पहिलो पटक मििा मागेको िए एक महिनासम्म कै द िा एक\nिजार रुपैर्ासाँ म्म जररबाना र दोस्रो पटकदेत्ति प्रत्र्ेक पटक दईु\nमहिनासम्म कै द िा दईु िजार रुपैर्ााँसम्म जररबाना,\n(ि) पहिलो पटक मििा मागन लगाएको िए एक िषसय म्म कै द िा\nदश िजार रुपैर्ासाँ म्म जररबाना िा दिु ै र दोस्रो पटकदेत्ति प्रत्र्ेक\nपटक तीन िषसय म्म कै द िा तीस िजार रुपैर्ााँसम्म जररबाना िा\nदिु ै।\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनको लामगाः\n(१) कुनै साध,ु सन्त, जोगी िा मििुले सनातनदेत्ति चली आएको\nपरम्परा अनसु ार घर घरमा पगु ी मििा माग गरेमा िा कुनै\n सम्पत्ति शद्धु ीकरण (मनी लाउण्डररङ्ग) मनिारण तथा व्र्ािसाहर्क िातािरण प्रिद्धयन सम्बन्धी के िी ऐनलाई\nसंशोधन गने ऐन, २०८० द्वारा थप।\n46\nwww.lawcommission.gov.np\nधाममकय िा सााँस्कृ मतक कार्मय ा मििा मामगएकोमा त्र्स्तोेे\nकार्लय ाई र्स दफा अन्तगतय को कसूर मामनने छैन,\n(२) “सािजय मनक स्थान” िन् नाले सडक, गल्ली, पाकय, सिारी हिसौनी\nस्थल, सरकारी कार्ायलर् िा कार्ायलर्को पररसर सम्झन ु पछय र\nसो शब्दले सािजय मनक प्रर्ोगमा रिेको सिारी साधनलाई समेत\nजनाउाँछ।\n\n१२६क. कसूर पीमडतको नाममा सिर्ोग मलन निनु ेाः (१) कसैले कुनै व्र्त्ति कसूर पीमडत िएको\nकारण देिाई मनजको तस्िीर रािी िा नरािी सािजय मनक रुपमा िा सामात्तजक सञ्जाल\nमाफय त आह्वान गरी िा नगरी मनजलाई औषमध उपचार गने, अन्र् कुनै हकमसमको राित,\nसहुिधा ठदने िा अन्र् कुनै प्रर्ोजनका लामग कसूर पीमडत िा मनजका पररिारको सदस्र्को\nतफय बाट कसैलाई चन्दा, सहुिधा, सिर्ोग, अनदु ानको नाममा कुनै हकमसमको नगद िा\nत्तजन्सी मागन,ु मलन ु िा प्राप्त गन यु िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन महिनासम्म\nकै द िा पााँच िजार रुपैर्ााँसम्म जररबाना िनु ेछ र त्र्सरी प्राप्त गरेको नगदी िा त्तजन्सी\nजफत िनु ेछ।\n(३) र्स दफामा अन्र्र जनु सकु ै कुरा लेत्तिएको िए तापमन कसूर पीमडत िा\nमनजका पररिारका सदस्र्ले नेपाल सरकार, प्रदेश सरकार िा स्थानीर् तिबाट कुनै\nसिर्ोग िा कुनै सहुिधा प्राप्त गरेकोमा िा कुनै सामात्तजक संस्था िा कुनै व्र्त्तिले\nआफू िुसी ठदएको सिर्ोग प्राप्त गरेकोमा र्स दफा बमोत्तजम कसूर गरेको मामनने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२७", "title": "िमतपूमत य िराउन ु पनेाः र्स पररच्छेदको दफा १०४, १०५, १०६, १०७, १०८, १०९,", "content": "११०, १११, ११३, ११४, ११५, ११६, ११७, ११८ र १२४ बमोत्तजमको कसूरबाट\nकसैलाई िामन, नोक्सानी िा कसैको सम्पत्तिमा िमत िएमा कसूरदारबाट त्र्स्तो िामन,\nनोक्सानी िनु े व्र्त्तिलाई िमतपूमत य िराई ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२८", "title": "िदम्र्ादाः (१) र्स पररच्छेद अन्तगतय को कुनै कसूरबाट कसैको ज्र्ान मरेकोमा", "content": "जहिलेसकु ै पमन उजरु गन य सहकनेछ।\n(२) दफा ११३, ११४, ११५, ११६, ११७, ११८, ११९, १२०, १२१ र १२२\nअन्तगतय को कसूरमा त्र्स्तो कसूर िएको मममतले तीन महिना नाघेपमछ र र्स पररच्छेद\n फौजदारी कसूर तथा फौजदारी कार्हयिमध सम्बन्धी के िी ऐन संशोधन गने ऐन, २०७९ द्वारा थप।\n47\nwww.lawcommission.gov.np\nअन्तगतय को अन्र् कसूरमा त्र्स्तो कसूर िएको कुरा थािा पाएको मममतले छ महिना\nनाघेपमछ उजरु लागने छैन।\nपररच्छेद-६\nिातिमतर्ार तथा िरिजाना सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२९", "title": "इजाजत पर प्राप्त नगरी िातिमतर्ार उत्पादन गन य निनु ेाः (१) कसैले इजाजतपर प्राप्त", "content": "नगरी िा इजाजतपर प्राप्त गरेको िए पमन इजाजतपरमा उत्तल्लत्तित शत य तथा बन्देज\nहिपरीत िनु े गरी िातिमतर्ार िा िरिजानाको उत्पादन गन य िा त्र्सकोेे ममतय संिार\nगन य िाँदु ैन।\nस्पष्‍ट टीकरणाः र्स संहिताको प्रर्ोजनका लामगाः\n(क) “िातिमतर्ार” िन् नाले तोप, मोटायर, बख्तरबन्द गाडी, मेत्तशनगन, राइफल,\nबन्दकु , हपस्तोल, ररिल्िर िा िरिजाना प्रर्ोग गरी िा नगरी चलाइने\nत्र्स्तै प्रकृ मतका अन्र् र्न्र सम्झन ु पछय र सो शब्दले िातिमतर्ार\nबनाउने मेत्तशन, उपकरण र िातिमतर्ारको पाटपूजाय समेतलाई जनाउाँछ,\n(ि) “मेत्तशनगन” िन् नाले ब्रेनगन, लइु सगन, स्टेगन, मेत्तशन, कारबाइन, टम्स\nमेत्तशन कारबाइन, जी.एम.जी, सटय मेमसन गन िा त्र्स्तै प्रकृ मतका\nस्िचामलत िातिमतर्ार सम्झन ु पछ य र सो शब्दले मेत्तशनगन बनाउने\nमेत्तशन, उपकरण र मेत्तशन गनको पाटपूजाय समेतलाई जनाउाँछ,\n(ग) “िरिजाना” िन् नाले िातिमतर्ारमा राख् ने बारुद, के प, गोली, छरा,य\nमडटोरेनेटर, कातसयु , फ्र्ूज िा त्र्स्तै प्रकृ मतका अन्र् पदाथ य समेतलाई\nजनाउाँछ।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई िातिमतर्ार िा\nिरिजानाको जोत्तिमको गम्िीरता िेरी दश िषसय म्म कै द र एक लाि रुपैर्ााँेाँसम्म\nजररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३०", "title": "इजाजत पर प्राप्त नगरी िातिमतर्ारको कारोबार गन य निनु ेाः (१) कसैले इजाजतपर प्राप्त", "content": "नगरी िा इजाजतपर प्राप्त गरेको िएपमन इजाजत परको शत य तथा बन्देज हिपरीत िनु े\nगरी िातिमतर्ार तथा िरिजानाको कारोबार गन य िाँदु ैन।\nस्पष्‍टट ीकरणाः र्स पररच्छेदको प्रर्ोजनको लामग “कारोबार” िन् नाले िररद गने, मबक्री गने,\nओसार पसार गन,े स्िाममत्ि प्राप्त गने, िस्तान्तरण गने, सिर् िा सङ्कलन गने, िण्डारण\nगने, मनकासी िा पैठारी गने काम सम्झन ु पछ।य\n48\nwww.lawcommission.gov.np\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई सात िषसय म्म\nकै द र सिरी िजार रुपैर्ााँसम्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३१", "title": "िास हकमसमका िातिमतर्ार प्राप्त गन य निनु ेाः (१) कसैले देिार्का िातिमतर्ार िररद", "content": "मबक्री गरी िा दान, उपिार, परु स्कार, अंश, अपतु ालीबाट िा अन्र् कुनै हकमसमबाट प्राप्त\nगन,य राख् न, सिर् गन,य िण्डारण गन य र अमधकार प्राप्त अमधकारीको आदेश हिना प्रर्ोग गन,य\nओसार पसार गन य िा मनकासी िा पैठारी गन य िाँदु ैनाः-\n(क) बख्तरबन्द गाडी (ट्याङ्क) तथा त्र्सको िरिजाना,\n(ि) तोप िा मोटायर तथा त्र्सको िरिजाना,\n(ग) मेत्तशनगन तथा त्र्सको िरिजाना,\n(घ) जनु सकु ै प्रकारको राइफल तथा त्र्सको िरिजाना,\n(ङ) सिसय ाधारणले प्राप्त गन य िा राख् न निनु े िनी अमधकार प्राप्त\nअमधकारीले तोके का अन्र् िातिमतर्ार तथा त्र्सको िरिजाना।\n(२) उपदफा (१) मा उत्तल्लत्तित िातिमतर्ार प्राप्त गने व्र्त्तिले त्र्स्तो\nिातिमतर्ार प्राप्त िएको मममतले पैँतीस ठदनमिर सम्बत्तन्धत त्तजल्ला प्रशासन कार्ायलर्मा\nबझु ाउन ु पनेछ।\n(३) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई सात िषसय म्म\nकै द र सिरी िजार रुपैर्ााँसम्म जररबाना िनु ेछ।\n(४) र्स दफामा अन्र्र जनु सकु ै कुरा लेत्तिएको िए तापमन सरु िाको कामसाँग\nसम्बत्तन्धत नेपाली सेना, नेपाल प्रिरी, सशस्त्र प्रिरी बल, नेपालका अमधकृ त तथा जिानले\nिा कानून बमोत्तजम िातिमतर्ार प्रर्ोग गन य पाउने अन्र् सरु िाकमीले आफनो कतव्य र्\nपालनको मसलमसलामा त्र्स्ता िातिमतर्ार राख् न िा प्रर्ोग गन य बाधा पगु ेको मामनने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३२", "title": "इजाजतपर हिना िातिमतर्ार राख्न िा मलएर हिड्न निनु ेाः (१) कसैले कानून बमोत्तजम", "content": "प्राप्त गन,य राख् न, िण्डारण गन,य प्रर्ोग गन य िा मलएर हिड्न सहकने िातिमतर्ार इजाजतपर\nप्राप्त नगरी िा इजाजतपर प्राप्त गरेको िए पमन इजाजतपरको शत य तथा बन्देज हिपरीत\nिनु े गरी प्राप्त गन,य राख् न, िण्डारण गन,य प्रर्ोग गन य िा मलएर हिड्न िाँदु ैन।\nतर सरु िाको कामसाँग सम्बत्तन्धत नेपाली सेना, नेपाल प्रिरी, सशस्त्र प्रिरी बल,\nनेपालका अमधकृ त तथा जिानले िा कानून बमोत्तजम िातिमतर्ार प्रर्ोग गन य पाउने अन्र्\nसरु िाकमीले आफनो कतव्य र् पालनको मसलमसलामा त्र्स्तो िातिमतर्ार आफू मसत राख् न,\nप्रर्ोग गन य िा मलएर हिड्न बाधा पगु ने छैन।\n49\nwww.lawcommission.gov.np\n(२) उपदफा (१) बमोत्तजमका कसूर गने िा गराउने व्र्त्तिलाई पााँच िषसय म्म\nकै द र पचास िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३३", "title": "िातिमतर्ार िरिजानाको कारोबारको अमिलेि राख्न ु पनेाः (१) इजाजतपर प्राप्त गरी", "content": "िातिमतर्ार िा िरिजानाको कारोबार गने व्र्त्तिले आफू ले कारोबार गरेको िात\nिमतर्ार िा िरिजानाको छुट्टै अमिलेि राख् न ु पनेछ।\n(२) उपदफा (१) बमोत्तजम रात्तिएको अमिलेिमा अन्र् कुराको अमतररि\nदेिार्का कुरा िुलाउन ु पनेछाः-\n(क) आफू ले िररद िा मबक्री गरेको, ओसार पसार गरेको, िण्डारण\nगरेको, मनकासी िा पैठारी गरेको िातिमतर्ारको हकमसम, हििरण र\nपररमाण,\n(ि) िातिमतर्ार कसैलाई मबक्री गरेको िए िररद गने व्र्त्तिको नाम,\nथर, ितन, नागररकता िा रािदानीको नम्िर र जारी िएको मममत\nतथा स्थान।\n(३) िातिमतर्ार िा िरिजानाको कारोबार गने व्र्त्तिले उपदफा (२)\nबमोत्तजमको अमिलेि िातिमतर्ार तथा िरिजानाको मनर्न्रण िा प्रशासन गने अमधकारी,\nमद्दु ाको अनसु न्धान गने अमधकारी िा अदालतले मागेको बित देिाउन ु िा पेश गन यु\nपनेछ।\n(४) इजाजतपर प्राप्त गरी िातिमतर्ार िा िरिजानाको व्र्ािसाहर्क कारोबार\nगने व्र्त्ति बािेक अन्र् कसैले िातिमतर्ार िा िरिजानाको कारोबार गन यु पदाय\nसम्बत्तन्धत त्तजल्ला प्रशासन कार्ायलर्को स्िीकृ मत मलई गन यु पनेछ।\n(५) उपदफा (१), (३) िा (४) हिपरीतको कार् य गने िा गराउने व्र्त्तिलाई दईु\nिषसय म्म कै द र बीस िजार रुपैर्ााँसम्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३४", "title": "आणहिक, रासार्मनक, जैहिक (त्तजिाणर्ु िु ) िा हिषाल ु िातिमतर्ार उत्पादन िा कारोबार", "content": "गन य निनु ेाः (१) कसैले कुनै पमन प्रकारको आणहिक, रासार्मनक, जैहिक (त्तजिाणर्ु िु ) िा\nहिषाल ु िातिमतर्ारको मनमायण, उत्पादन, िररद, मबक्री, प्रामप्त, स्िामीत्ि धारण, िस्तान्तरण,\nिण्डारण, सिर्, ओसार पसार िा मनकासी िा पैठारी िा त्र्सको लामग लगानी िा\nव्र्िस्थापन गन य िा गराउन ु िाँदु ैन।\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनको लामगाः\n(क) “रासार्मनक िातिमतर्ार” िन् नाले सम्ित ् २०४९ साल पौष २९ गते\n(१३ जनिरी, १९९३ का ठदन पेररसमा सम्पन् न िएको रासार्मनक\n50\nwww.lawcommission.gov.np\nिातिमतर्ारको हिकास, उत्पादन, सिर् तथा उपर्ोगको प्रमतिन्ध गने तथा\nत्र्सकोेे हिनाशका सम्बन्धमा व्र्िस्था िएको मिासत्तन्ध (कन्िेन्सन अन\nठद प्रोहिमबशन अफ ठद डेिलपमेन्ट, प्रडक्शन, स्टकपाइमलङ्ग एण्ड र्जु अफ\nके ममकल हिपन्स एण्ड ठदर्र मडस्रक्शन) ले पररिाषा गरे बमोत्तजमको\nरासार्मनक िातिमतर्ार सम्झन ु पछ।य\n(ि) “जैहिक िा हिषाल ु िातिमतर्ार” िन् नाले सम्ित २०२८ साल चैर २८\nगते (१० अहप्रल, १९७२) का ठदन लण्डन, मस्को र िामसङ्गटनमा सम्पन् न\nिएको जैहिक (जीिाणर्ु िु ) र हिषाल ु िातिमतर्ारको हिकास, उत्पादन\nतथा सिर्को प्रमतिन्ध तथा त्र्सको हिनासका सम्बन्धमा व्र्िस्था िएको\nमिासत्तन्ध (कन्िेन्सन अन ठद प्रोहिहिशन अफ ठद डेिलपमेन्ट, प्रडक्टशन\nएण्ड स्टकपाइमलङ्ग अफ ब्र्ाक्टेररर्ोलत्तजकल (बार्ोलत्तजकल) एण्ड\nटत्तक्सन हिपन्स ् एण्ड अन ठदर्र मडस्रक्शन) ले पररिाषा गरे बमोत्तजमको\nजैहिक (त्तजिाणर्ु िु ) िा हिषाल ु िातिमतर्ार सम्झन ु पछ।य\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई बीस िषसय म्म कै द र दईु\nलाि रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३५", "title": "कसूरसाँग सम्बत्तन्धत चल अचल सम्पत्ति जफत िनु ेाः र्स पररच्छेद अन्तगतय को कुनै कसूर", "content": "िएकोमा त्र्स्तो कसूरसाँग सम्बत्तन्धत िातिमतर्ार र िरिजाना र त्र्स्ता िातिमतर्ारको\nउत्पादन गने, मनमायण गने, राख् ने िा ओसार पसार गने, र्न्र, उपकरण, औजार िा सिारी\nसाधन र त्र्स्तो िातिमतर्ार िा िरिजानाको िररद मबक्रीबाट प्राप्त रकम र त्र्सबाट\nबढे बढाएको रकम जफत िनु ेछ।\nतर ढुिानीको साधन िा सिारी साधनको धनीले िातिमतर्ार िा िरिजाना\nढुिानी िएको कुरा मनजलाई थािा निएको प्रमात्तणत गरेमा त्र्स्तो सिारी साधन जफत\nिनु े छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३६", "title": "िमतपूमत य िराउनेाः कसैले र्स पररच्छेद अन्तगतय को कुनै कसूर गरेको कारणबाट कसैको", "content": "जीउ िा सम्पत्तिको िामन, नोक्सानी िएको रिेछ िने कसूरदारबाट पीमडत व्र्त्तिलाई\nत्र्सको मनामसब िमतपूमत य िराई ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३७", "title": "िदम्र्ादाः दफा १३२ अन्तगतय को कसूरमा त्र्स्तो कसूर िएको मममतले तीन महिनामिर र", "content": "र्स पररच्छेद अन्तगतय का अन्र् कसूरमा त्र्स्तो कसूर िए गरेको थािा पाएको मममतले छ\nमहिना नाघेपमछ उजरु लागने छैन।\n51\nwww.lawcommission.gov.np\nपररच्छेद-७\nहिष्‍टफोटक पदाथ य सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३८", "title": "हिष्‍टफोटक पदाथ य उत्पादन गन य निनु ेाः (१) कसैले इजाजतपर प्राप्त नगरी िा इजाजतपर", "content": "प्राप्त गरेको िए पमन इजाजतपरमा उल्लेि िएका शत य र बन्देज हिपरीत िनु े गरी कुनै\nपमन हकमसमको हिष्‍टफोटक पदाथ य बनाउन, तर्ार गन य िा उत्पादन गन य िाँदु ैन।\nस्पष्‍ट टीकरणाः र्स संहिताको प्रर्ोजनका लामगाः\n(क) “हिष्‍टफोटक पदाथ”य िन् नाले हिष्‍टफोटन िई िमत पर्ु ायउने\nआइ.इ.डी; टी.एन.सी. एमाटोल, बारोटोल, पेन्टोलाइट, र्रर् ाहपड\nमडटोनेहटि एक्स्प्लोमसि (आर.डी. एक्स), टोर फे क्स, ब्लाहष्टक\nएक्स्प्लोमसि, डाइनामाइट, बारुद, नाइरोत्तगलमसररन, जेलेगनाइट,\nस्टेमाइट, सेल्साइट, मडटोनेटर, ब्लाहष्टक क्र्ाप, हिद्यतु ीर् ब्लाहष्टक\nक्र्ाप, फ्र्ूज, आमतसिाजी, पटाका, गन कटन, गन पाउडर\nब्लात्तस्टक पाउडर, पारो (मकयरी) िा अन्र् कुनै धातकु ो फुल्र्ूनेट,\nसोिी प्रकृ मतका हिष्‍टफोटन िनु े अन्र् कुनै पदाथ य िा नेपाल\nसरकारले नेपाल राजपरमा सूचना प्रकाशन गरी तोके को कुनै\nपदाथ य सम्झन ु पछ य र सो शब्दले बम समेतलाई जनाउाँछ।\n(ि) “बम” िन् नाले कुनै हिष्‍टफोटक पदाथ य िा अन्र् कुनै साधन, फमूलय ा,\nप्रहक्रर्ा िा उपार्द्वारा आफैँ िा अन्र् कुनै पदाथद्वय ारा हिष्‍टफोटन\nिनु े गरी बनाइएको मिनेड िा त्र्स्तै प्रकृ मतको अन्र् हिष्‍टफोटक\nपदाथर्य िु िस्त ु िा पदाथ य सम्झन ु पछय।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई देिार्\nबमोत्तजमको सजार् िनु ेछाः-\n(क) कडा हिष्‍टफोटक पदाथ य (िाइ एक्सप्लोमसि) िए दश िषसय म्म कै द\nर एक लाि रुपैर्ााँसम्म जररबाना,\n(ि) नरम हिष्‍टफोटक पदाथ य (लो एक्स्प्लोमसि) िए पााँच िषसय म्म कै द\nर पचास िजार रुपैर्ासाँ म्म जररबाना,\n(ग) सामान्र् हिष्‍टफोटक पदाथ य िए तीन िषसय म्म कै द र तीस िजार\nरुपैर्ााँसम्म जररबाना,\n52\nwww.lawcommission.gov.np\n(घ) हिष्‍टफोटक पदाथ य उत्पादन िा मनमायण गने संर्न्र, मेशीन िा\nज्र्ािलको उत्पादन गने, प्रर्ोग गने, राख् ने िा अन्र् कारोबार\nगनेलाई दईु िषसय म्म कै द र बीस िजार रुपैर्ासाँ म्म जररबाना।\nस्पष्‍ट टीकरणाः र्स पररच्छेदको प्रर्ोजनका लामगाः-\n(१) “कडा हिष्‍टफोटक पदाथ”य िन् नाले डाइनामाइट, नाइरोत्तगलसररन,\nहट.एन.सी., जेलेगनाइट, मनक्य टनरलाि, पारोको फुल्र्ूनेट, आर.डी.\nएक्स, एमाटोल, बारोटोल, पेन्टोलाइट, स्टेमाइट, सेल्साइटल,\nब्लाहष्टक एक्स्पोमलिस बम र त्र्स्तै प्रकृ मतका अन्र् हिष्‍टफोटक\nपदाथ य सम्झन ु पछ।य\n(२) “नरम हिष्‍टफोटक पदाथ”य िन् नाले ब्लाहष्टक पाउडर, गन पाउडर,\nगन कटन, पारो, बारुद िा अन्र् कुनै धातकु ो फुल्र्ूनेट र त्र्स्तै\nप्रकृ मतका अन्र् हिष्‍टफोटक पदाथ य सम्झन ु पछ।य\n(३) “सामान्र् हिष्‍टफोटक पदाथ”य िन् नाले मडटोनेटर, ब्लाहष्टक क्र्ाप,\nहिद्यतु ीर् ब्लाहष्टक क्र्ाप, पm्र्ूज, आमतसिाजी, पटाका र त्र्स्तै\nप्रकृ मतका अन्र् हिष्‍टफोटक पदाथ य सम्झन ु पछ।य", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३९", "title": "हिष्‍टफोटक पदाथकय ो कारोबार गन य निनु ेाः (१) कसैले इजाजतपर प्राप्त नगरी िा इजाजत", "content": "पर प्राप्त गरेको िएपमन इजाजतपरमा उल्लेि िएका शत य र बन्देज हिपरीत िनु े गरी\nहिष्‍टफोटक पदाथकय ो कारोबार गन य िा गराउन िाँदु ैन।\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनको लामग “कारोबार” िन् नाले िररद गने गराउने, मबक्री\nगने, राख् ने, प्रर्ोग गने, सिर् गने, िण्डारण गने, ओसार पसार गने, पररितनय गने, ममसािट\nगने, मनकासी िा पैठारी गने काम सम्झन ु पछ।य\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई देिार् बमोत्तजम सजार्\nिनु ेछाः-\n(क) कडा हिष्‍टफोटक पदाथ य िए दश िषसय म्म कै द र एक लाि\nरुपैर्ााँसम्म जररबाना,\n(ि) नरम हिष्‍टफोटक पदाथ य िए पााँच िषसय म्म कै द र पचास िजार\nरुपैर्ााँसम्म जररबाना,\n(ग) सामान्र् हिष्‍टफोटक पदाथ य िए तीन िषसय म्म कै द र तीस िजार\nरुपैर्ााँसम्म जररबाना।\n53\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४०", "title": "कृ मरम हिष्‍टफोटक पदाथ य बनाउन िा प्रर्ोग गन य निनु ेाः (१) कसैले सिसय ाधारणले प्रर्ोग", "content": "िा उपिोग गने सामान्र् उपिोगर् िस्तकु ो िा त्र्स्तो िस्तकु ो िौमतक िा रासार्मनक\nतत्िमा कुनै िौमतक िा रासार्मनक प्रहक्रर्ा, फमूलय ा, उपार् िा हिमधबाट िेरफे र, पररितनय\nगरी िा त्र्सको रुप, बनौट िा आकारमा पररितनय गरी कुनै हकमसमको बम िा अन्र्\nकुनै हिष्‍टफोटक पदाथकय ो रुपमा प्रर्ोग गन य िा गराउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई तीन िषसय म्म कै द िा तीस\nिजार रुपैर्ासाँ म्म जररबाना िा दबु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४१", "title": "बारुदी सरुु ङ्ग बनाउन िा हिष्‍टफोटक पदाथ य ओछ्याउन निनु ेाः (१) कसैले सािजय मनक", "content": "रुपमा प्रर्ोग िनु े सडक िा बाटो, स्थल, ििन, पलु , सरुु ङ्ग िा सिसय ाधारणले हिडडलु गने\nअन्र् कुनै ठाउाँमा हिष्‍टफोटक पदाथ य ओछ्याउन िा राख् न िा कुनै प्रज्िलनशील पदाथ य िा\nहिद्यतु ीर् धराप (एम्बसु ) राख् न िा त्र्स्तो पदाथ य रािी िा धराप ओछ्याई आिागमनमा\nिा सािजय मनक उपर्ोगका अन्र् कुनै कुराको प्रर्ोगमा अिरोध पर्ु ाउय न िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई दश िषसय म्म\nकै द र एक लाि रुपैर्ााँसम्म जररबाना िनु ेछ।\n(३) उपदफा (१) बमोत्तजमको कसूर गरेको कारणबाट कसैको जीउ, ज्र्ान िा\nसम्पत्तिमा िमत पगु ेमा कसूरदारलाई त्र्स बापत र्स संहिता बमोत्तजम िनु े सजार्मा\nउपदफा (२) बमोत्तजमको सजार् थप िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४२", "title": "उत्पादन िा कारोबारको अमिलेि राख्न ु पनेाः (१) हिष्‍टफोटक पदाथकय ो उत्पादन िा", "content": "कारोबार गन य इजाजत पर प्राप्त गरेको व्र्त्तिले त्र्स्तो पदाथकय ो उत्पादन, मनमायण, तर्ारी\nिा कारोबार गदाय प्रत्र्ेक पटक उत्पादन िा कारोबार गरेको प्रत्र्ेक हिष्‍टफोटक पदाथकय ो\nछुट्टै अमिलेि राख् न ु पनेछ।\n(२) उपदफा (१) बमोत्तजमको अमिलेिमा अन्र् कुराको अमतररि देिार्का\nहििरण िुलाउन ु पनेछाः-\n(क) के कस्ता हिष्‍टफोटक पदाथ,य के कमत पररमाणमा उत्पादन, तर्ारी\nिा मनमायण िएको िो,\n(ि) हिष्‍टफोटक पदाथकय ो कारोबार िएको िए के कस्तो प्रर्ोजनका\nलामग कारोबार िएको िो,\n(ग) हिष्‍टफोटक पदाथ य मबक्री हितरण िएको िए कुन व्र्त्तिलाई के\nकस्तो प्रर्ोजनका लामग के कमत पररमाण मबक्री हितरण िएको\nिो।\n54\nwww.lawcommission.gov.np\n(३) उपदफा (१) बमोत्तजम रात्तिएको अमिलेि मबस्फोटक पदाथकय ो कारोिार\nगने व्र्त्तिले हिष्‍टफोटक पदाथ य मनर्न्रण िा प्रशासन गने अमधकारप्राप्त अमधकारी, मद्दु ाको\nतिहककात िा अमिर्ोजन गने अमधकारी िा अदालतले मागेका बित उपलब्ध गराउन ु\nपनेछ।\n(४) र्स दफा हिपरीत काम गने िा गराउने व्र्त्तिलाई तीन महिनासम्म कै द िा\nपााँच िजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४३", "title": "हिष्‍टफोटक पदाथकय ो ओसार पसार, ढुिानी िा िण्डारण गदा य िोमसर्ारी अपनाउन ु पनेाः (१)", "content": "हिष्‍टफोटक पदाथकय ो कारोबार गन य इजाजतपर प्राप्त गरेको व्र्त्तिले त्र्स्ता िस्तकु ो प्रर्ोग\nगदाय, ढुिानी िा ओसार पसार गदाय िा िण्डारण गदाय त्र्स्तो पदाथकय ो प्रकृ मत अनसु ार\nपर्ायप्त सरु िा िनु े गरी प्रर्ोग गन यु िा उपर्िु म्र्ागत्तजनमा रािी ढुिानी िा ओसार पसार\nिा िण्डारण गन यु पनेछ।\n(२) उपदफा (१) हिपरीत काम गने िा गराउने व्र्त्तिलाई पचास िजार\nरुपैर्ााँसम्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४४", "title": "कसूरसाँग सम्बत्तन्धत चल िा अचल सम्पत्ति जफत िनु ेाः र्स पररच्छेद अन्तगतय सजार् िनु े", "content": "कुनै कसूर िएकोमा त्र्स्तो कसूरसाँग सम्बत्तन्धत सम्पूण य हिष्‍टफोटक पदाथ,य त्र्स्तो पदाथ य\nउत्पादन, तर्ारी िा मनमायण गन य प्रर्ोग िनु े मालसामान, उपकरण, औजार िा कच्चा पदाथ,य\nत्र्स्तो पदाथ य ओसार पसार िा ढुिानी गने सिारी साधन िा ढुिानी साधन र त्र्स्तो\nपदाथकय ो उत्पादन, तर्ारी, मनमायण िा कारोबार गरी प्राप्त गरेको रकम र त्र्सबाट बढे\nबढाएको रकम जफत िनु ेछ।\nतर ढुिानीको साधन िा सिारी साधनको धनीले हिष्‍टफोटक पदाथ य ढुिानी िएको\nकुरा मनजलाई थािा निएको प्रमात्तणत िएमा त्र्स्तो ढुिानीको साधन िा सिारी साधन\nजफत िनु े छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४५", "title": "िमतपूमत य िराउनेाः कसैले र्स पररच्छेद अन्तगतय को कुनै कसूर गरेको कारणबाट कसैको", "content": "जीउ, धनको िामन, नोक्सानी िएको रिेछ िने कसूरदारबाट पीमडत व्र्त्तिलाई त्र्सको\nमनामसब िमतपूमत य िराई ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४६", "title": "िदम्र्ादाः दफा १४३ अन्तगतय का कसूरमा त्र्स्तो कसूर िए गरेको मममतले तीन महिना", "content": "र र्स पररच्छेद अन्तगतय का अन्र् कसूरमा त्र्स्तो कसूर िए गरेको थािा पाएको मममतले\nछ महिना नाघेपमछ उजरु लागनेछैन।\n55\nwww.lawcommission.gov.np\n\nपररच्छेद-७क.\nआतङ्ककारी कार् य सम्बन्धी कसूर\n१४६क. आतङ्ककारी कार् य सम्बन्धी कसूर गरेको मामननेाः (१) कसैले पमन आतङ्ककारी कार् य\nसम्बन्धी कसूर गन य िा गराउन िाँदु ैन।\n(२) उपदफा (१) को प्रर्ोजनको लामग र्ो दफा प्रारम्ि िएपमछ कसैले नेपाल\nसरकार, प्रदेश सरकार िा स्थानीर् ति िा हिदेशी राज्र् िा अन्तरायत्तष्‍ट रर् सङ्गठनलाई\nप्रत्र्ि िा अप्रत्र्ि तिरबाट कुनै कार् य गन य िा नगन य बाध्र् तल्ु र्ाउने िा कुनै कार् य गन य\nरोक्ने िा सिसय ाधारणलाई रमसत पाने िा नेपाल िा हिदेशी राज्र्को साििय ौमसिा,\nिौगोमलक अिण्डता र स्ितन्रतामा िामन पर्रु र्ाउने उद्देश्र्ले देिार्को कुनै कार् य गरे िा\nगराएमा आतङ्ककारी कार् य सम्बन्धी कसूर गरेको मामननेछ:-\n(क) कुनै गैरसैमनक व्र्त्ति (मसमिमलर्न) िा सशस्त्र द्वन्द्वका बित\nशरतु ापूण य कार्मय ा संलगन निएको व्र्त्तिको ज्र्ान मलने िा\nअङ्गिङ्ग गने,\n(ि) कुनै व्र्त्तिलाई अपिरण गने िा बन्धक बनाउने,\n(ग) कुनै िातिमतर्ार, हिष्‍टफोटक पदाथ य िा अन्र् कुनै उपकरण प्रर्ोग\nगरी िानेपानी, सािजय मनक र्ातार्ात, सूचना तथा सिार, हिद्यतु िा\nहिद्यतु ीर्, हििीर् िा अन्र् र्स्तै सािजय मनक सेिा िा उपिोग\nप्रणाली कब्जा गने, गम्िीर रूपमा अिरोध गने, िमत पर्रु र्ाउने िा\nनष्‍ट ट गने,\n(घ) अन्तरायत्तष्‍ट रर् रूपमा संरत्तित व्र्त्तिको ित्र्ा, अपिरण िा त्र्स्ता\nव्र्त्तिको स्ितन्रता उपर िमला गने िा त्र्स्तो व्र्त्तिको मनजी\nआिास िा त्र्सको पररसर िा र्ातार्ातको साधन उपर हिंसात्मक\nआक्रमण गने,\nस्पष्‍ट टीकरण: र्स िण्डको प्रर्ोजनको लामग \"अन्तरायत्तष्‍ट रर् रूपमा\nसंरत्तित व्र्त्ति\" िन् नाले आफ्नो राष्‍ट र बाहिर रिाँदा अन्तरायत्तष्‍ट रर्\nकानून बमोत्तजम हिशेष संरिण प्राप्त गने राष्ट्राध्र्ि, सरकार प्रमिु ,\nपरराष्‍ट र मन्री, दूतािास र अन्र् कू टनीमतक मनर्ोग िा अन्तरायत्तष्‍ट रर्\n सम्पत्ति शद्धु ीकरण (मनी लाउण्डररङ्ग) मनिारण तथा व्र्ािसाहर्क िातािरण प्रिद्धयन सम्बन्धी के िी ऐनलाई\nसंशोधन गने ऐन, २०८० द्वारा थप।\n56\nwww.lawcommission.gov.np\nसङ्गठनमा कार्रय त हिमिन् न राष्‍ट रको स्थार्ी तथा अस्थार्ी प्रमतमनमध\nर मतनको पररिारको सदस्र् सम्झन ु पछय।\n(ङ) आमहिनासका िातिमतर्ारको मनमायण, हिस्तार िा मबक्री हितरण\nगने, त्र्स्ता िातिमतर्ारको प्रामप्त, कब्जा, स्थानान्तरण िा चोरी,\nडकै ती गने,\n(च) गैरकानूनी रुपले बल प्रर्ोग गरी िा सो प्रर्ोग गने धम्की ठदई िा\nअरु कुनै प्रकारको डर, रास देिाई िार्र्ु ान िा जलर्ानलाई\nकब्जामा मलने िा त्र्स उपर मनर्न्रण गने िा िमूमस्थ िार्र्ु ान\nिा जलर्ान नष्‍ट ट गने िा त्र्सको कुनै िागमा सरु िा ितरा पैदा\nगने,\n(छ) िण्ड (क) देत्ति (च) सम्मको कार् य गन य िा गराउन सङ्गठन\nमनमायण गने िा र्ोजना बनाउने, सङ्गठनमा आबद्ध िनु े, सङ्गठन\nहिस्तार गने िा सदस्र्ता बढाउने िा प्रत्तशिण ठदने,\n(ज) आतङ्ककारी सङ्गठन िा समूिको सदस्र्ता मलने िा सो कार् य गन य\nसिर्ोग गने,\n(झ) हिदेशी आतङ्ककारी लडाकुको रूपमा कार् य गने।\n(३) देिार् बमोत्तजमको कसूर गने व्र्त्तिलाई देिार् बमोत्तजमको सजार् िनु ेछ:-\n(क) उपदफा (२) को िण्ड (क) िा (ि) बमोत्तजमको कसूर गरी\nकसैको जीउ ज्र्ान गएकोमा जन्म कै द,\n(ि) उपदफा (२) को िण्ड (क) िा (ि) बमोत्तजमको कसूर गरी\nकसैको जीउ ज्र्ान नगएको तर चोटपटक लागके ो िा अङ्गिङ्ग\nिएकोमा पन्र िषदय ेत्ति बीस िषसय म्म कै द,\n(ग) उपदफा (२) को िण्ड (ि) बमोत्तजमको कसूर गरी कसैलाई\nचोटपटक नलागेको र अङ्गिङ्ग निएकोमा दश िषदय ेत्ति पन्र\nिषसय म्म कै द,\n(घ) उपदफा (२) को िण्ड (ग), (घ), (ङ) िा (च) बमोत्तजमको\nकसूर गरेमा दश िषदय ेत्ति पन्र िषसय म्म कै द,\n(ङ) उपदफा (२) को िण्ड (छ) बमोत्तजमको कसूर गरेमा पन्र\nिषसय म्म कै द,\n57\nwww.lawcommission.gov.np\n(च) उपदफा (२) को िण्ड (ज) िा (झ) बमोत्तजमको कसूर गरेमा\nदश िषसय म्म कै द।\nपररच्छेद-८\nरात्तष्‍टर र् तथा सािजय मनक सम्पदा हिरुद्धका कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४७", "title": "व्र्त्ति हिशेषले सािजय मनक घर, जगगा आफ्नो बनाउन निनु ेाः (१) कसैले देिार्को घर िा", "content": "जगगा नेपाल सरकार, प्रदेश सरकार िा स्थानीर् तिको पूिस्य िीकृ मत हिना दताय गरी िा\nनगरी आफ्नो बनाउन िा कुनै हकमसमले कब्जा, आिाद िा अमतक्रमण गन य िा त्र्स्तो घर\nिा जगगाको िोग चलनमा कुनै हकमसमको बाधा अबरोध गन य िाँदु ैनाः-\n(क) नेपाल सरकार, प्रदेश सरकार िा स्थानीर् ति िा नेपाल सरकार,\nप्रदेश सरकार िा स्थानीर् तिको पूण य िा अमधकांश स्िाममत्ि िा\n\nमनर्न्रण िएको सािजय मनक संस्थाको नाममा रिेको ....... घर\nजगगा,\n(ि) परापूिदय ेत्ति सामदु ाहर्क िा सािजय मनक िोग चलनमा रिेको\nसामदु ाहर्क िा सािजय मनक घर जगगा।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द िा तीस िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।\n(३) उपदफा (१) मा उत्तल्लत्तित घर, जगगा कुनै व्र्त्ति हिशेषको नाममा दताय\nिा नामसारी िइसके को िए त्र्स्तो दताय समेत स्िताः बदर िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४८", "title": "व्र्त्ति हिशेषले सािजय मनक सम्पदा आफ्नो बनाउन निनु ेाः (१) कसैले कुनै सािजय मनक", "content": "सम्पदा दताय गरी िा नगरी मनजी बनाउन िा त्र्स्तो सम्पदाको सािजय मनक िोग चलनमा\nकुनै हकमसमले बाधा अिरोध गन य िा अन्र् कुनै हकमसमले कब्जा, आिाद िा अमतक्रमण\nगन य िा त्र्स्तो सम्पदालाई कुनै हकमसमले िामन, नोक्सानी िा िमत पर्ु ायउन िाँदु ैन।\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनको लामग “सािजय मनक सम्पदा” िन् नाले देिार्\nबमोत्तजमका सम्पदा सम्झन ु पछयाः-\n(क) परापूिदय ेत्ति सािजय मनक रुपमा हिाँडी आएको बाटो,\n(ि) सािजय मनक रुपमा िोग चलन िदु ै आएको सडक, गौचर, पानीघाट,\nत्तचिान, मसानघाट, धारो, पधेरो, कुिा, पोिरी, पोिरीको मडल,\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा त्तझहकएको।\n58\nwww.lawcommission.gov.np\nिानेपानीको मूल, निर, कुलो, गाईिस्त ु चराउने चौर िा मनकाल्ने\nमनकाश,\n(ग) िाट बजार लागने स्थान,\n(घ) देिस्थल, मठ, मत्तन्दर, स्तपु , गम्ु िा, मत्तस्जद िा मगजायघर,\n(ङ) पाटी, पौिा सिल, चौतारो,\n(च) ऐमतिामसक मूमत,य शामलक, सााँस्कृ मतक स्तम्ि िा स्मारक,\n(छ) धाममकय िा सााँस्कृ मतक कार् य िा समारोि गने ठाउाँ,\n(ज) नेपाल सरकारले तोके को रात्तष्‍ट रर् िन िा नेपाल सरकार, प्रदेश\nसरकार िा स्थानीर् तिको स्िाममत्ि रिेको िन िा त्र्सको कुनै\nअंश।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई पााँच िषसय म्म\nकै द िा पचास िजार रुपैँर्ासम्म जररबाना िा दिु ै सजार् िनु ेछ।\n(३) उपदफा (१) बमोत्तजमको सािजय मनक सम्पदा कसैको नाममा दता य िा\nनामसारी िइसके को िए सो समेत स्िताः बदर िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४९", "title": "प्राकृ मतक सम्पदामामथ अमतक्रमण गन य निनु ेाः (१) कसैले कानून बमोत्तजम बािेक प्राकृ मतक", "content": "सम्पदामामथ कुनै हकमसमले अमतक्रमण िा कब्जा गन य िा त्र्स्तो सम्पदा मबक्री हितरण\nगन य िा त्र्सको प्राकृ मतक बनािट िा सौन्दर्मय ा कुनै हकमसमले िामन, नोक्सानी िा िमत\nपर्ु ायउन िाँदु ैन।\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनको लामग “प्राकृ मतक सम्पदा” िन् नाले देिार्का\nसम्पदालाई सम्झन ु पछयाः-\n(क) प्राकृ मतक िातािरण, िनस्पमत र िन्र्जन्तकु ो संरिणका लामग\nनेपाल सरकारले तोके को रात्तष्‍ट रर् मनकुञ्ज, िन्र्जन्त ु िा त्तशकार\nआरि,\n(ि) नेपाल सरकारले तोके को संरिण िेर, नदी, नाला, िोला, ताल\nतलैर्ा, सीमसार िेर िा प्राकृ मतक झरना, हिमत्तशिर िा त्र्सको\nकुनै अंश, उच्च पिाडी चचु रु ो,\n(ग) प्रचमलत कानून िा नेपाल सरकार, प्रदेश सरकार िा स्थानीर् तिले\nसंरिण गरेको िन्र्जन्त,ु िनस्पमत िा ि-ू बनौट,\n59\nwww.lawcommission.gov.np\n(घ) नेपाल सरकार, प्रदेश सरकार िा स्थानीर् तिले संरिण गरेका\nिन्र्जन्तकु ो िासस्थान, पर्ायिरणीर् पद्धमत िा मबक्री हितरण,\nमनकासी िा पैठारीमा मनषेध गरेका जमडबटु ी।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई दश िषसय म्म\nकै द र हिगो िुलेकोमा मबगो बमोत्तजम र मबगो निुलेकोमा दशलाि रुपैर्ााँेंसम्म\nजररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५०", "title": "सािजय मनक िौमतक संरचनाको अनमधकृ त कब्जा िा हिनाश गन य निनु ेाः (१) कानून", "content": "बमोत्तजम बािेक कसैले कुनै सािजय मनक िौमतक संरचना अनमधकृ त रुपमा कब्जा गन,य\nत्र्स्तो संरचना प्रर्ोग िनु नठदन िा कुनै हकमसमले िामन, नोक्सानी िा हिनाश गन य\nिाँदु ैन।\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनको लामग “सािजय मनक िौमतक संरचना” िन् नाले\nसािजय मनक रुपमा प्रर्ोग िनु े देिार्का संरचना सम्झन ु पछयाः-\n(क) सडक, बाटो, पलु , सरुु ङ्ग, हिमानस्थल,\n(ि) जलाशर्, निर, िानेपानीको मिु ान तथा पोिरी, हिद्यतु गिृ , हिद्यतु\nप्रसारण के न्द्र िा त्र्सको लाइन,\n(ग) रज्जमु ाग,य के िलु कार, दूरसिार सम्बन्धी उपकरण, रेमडर्ो स्टेशन,\nटेमलमिजन प्रशारण के न्द्र तथा त्र्सको टािर,\n(घ) रेल तथा रेलमाग,य\n(ङ) सािजय मनक बस हिसौनी, सािजय मनक उद्यान, िा\n(च) अन्र् र्स्तै संरचना।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई दश िषसय म्म\nकै द र एक लाि रुपैर्ााँसम्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५१", "title": "रात्तष्‍टर र् गान, झण्डा िा मनशान छापको अपमान िा िमत गन य निनु ेाः (१) कसैले नेपाल िा", "content": "नेपाल सरकार हिरुद्ध घृणा फै लाउने मनर्तले नेपालको रात्तष्‍ट रर् गानको अपमान गन,य\nनेपालको झण्डा जलाउन, त्र्सको जानीजानी अपमान गन य िा सािजय मनक नैमतकता,\nत्तशष्टाचार िा सदाचारको दृहष्टकोणले प्रर्ोग गन य निनु े ठाउाँ, िस्त ु िा अिस्थामा त्र्स्तो\nगान, झण्डा िा नेपालको मनशाना छाप प्रर्ोग गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द िा तीस िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।\n60\nwww.lawcommission.gov.np\n(३) कसैले नेपालसाँग मैरी सम्बन्ध िएको मलु कु हिरुद्ध घृणा फै लाउने िा\nत्र्स्तो मलु कु को अपमान गने मनर्तले त्र्स्तो मलु कु को रात्तष्‍ट रर् झण्डा जलाउन, त्र्सको\nजानीजानी दरुु पर्ोग गन य िा त्र्स्तो झण्डा िा त्र्स्तो मलु कु को मनशान छापको दरुु पर्ोग\nगन य िा सािजय मनक नैमतकता र त्तशष्टाचारको दृहष्टकोणबाट प्रर्ोग गन य निनु े िस्त,ु ठाउाँ िा\nअिस्थामा त्र्स्तो झण्डा िा छापको प्रर्ोग गन य िाँदु ैन।\n(४) कसैले संर्िु राष्‍ट र संघ िा संर्िु राष्‍ट र संघसाँग सम्िद्ध संस्था िा\nहित्तशष्टीकृ त मनकार् िा नेपाल सदस्र् रिेको कुनै अन्तररात्तष्‍ट रर् िा िेरीर् संस्थालाई घृणा\nिा अपमान गने मनर्तले त्र्स्ता संस्थाको झण्डा िा मनशान छाप कुनै हकमसमले दरुु पर्ोग\nगन य िा त्र्स्ता संस्थाको स्िीकृ मत हिना त्र्स्तो झण्डा िा त्र्स्तो संस्थाको त्तचह्न, सिारी\nसाधन िा अन्र् कुनै िस्त ु प्रर्ोग गन य िाँदु ैन।\n(५) उपदफा (३) िा (४) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक\nिषसय म्म कै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५२", "title": "रात्तष्‍टर र् हििमूतको अपमान गन य निनु ेाः (१) कसैले नेपाल सरकारले तोके का रात्तष्‍ट रर्", "content": "हििमूतलाई जानीजानी घृणा, अपमान िा बदनाम गन,य त्र्स्ता हििमूतको शामलक, स्तम्ि िा\nस्मारक ित्काउन िा िामन, नोक्सानी गन य िाँदु ैन।\nतर त्र्स्ता हििमूतको जीिनी अध्र्र्न अनसु न्धान िा मूल्र्ाङ्कनको सन्दिमय ा असल\nमनर्तले गररएको हटका हटप्पणीलाई र्स दफा बमोत्तजमको कसूर मामनने छैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई छ महिनासम्म\nकै द िा पााँच िजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५३", "title": "िमतपूमत य िराई ठदन ु पनेाः दफा १५० बमोत्तजमको कसूर गरेको कारणबाट िएको िामन,", "content": "नोक्सानी बापत कसूरदारबाट मनामसब िमतपूमत य िराई ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५४", "title": "िदम्र्ादाः र्स पररच्छेदको दफा १४७, १४८ र १४९ अन्तगतय का कसूरमा जहिलेसकु ै", "content": "पमन उजरु गन य सहकनेछ र अन्र् दफा अन्तगतय को कसूरको िकमा त्र्स्तो कसूर िए\nगरेको मममतले छ महिनापमछ उजरु लागने छैन।\nपररच्छेद-९\nधम य सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५५", "title": "धाममकय स्थल िा पहिर मामनएको स्थानलाई िमत पर्ु ाउय न निनु ेाः (१) कसैले कुनै जात,", "content": "जामत, सम्प्रदार् िा िगकय ो धाममकय आस्था िा धमकय ो घृणा गने िा अपमान गने मनर्तले\nिा सो िनु सक्छ िन् ने जानीजानी कुनै धाममकय पूजा, प्राथनय ा िा कम य गने स्थान िा पहिर\n61\nwww.lawcommission.gov.np\nमामनएको कुनै स्थान, िस्त,ु मशानघाट िा त्तचिानलाई िामन, नोक्सानी िा िमत पर्ु ायउन िा\nकुनै हकमसमले दहुषत गन,य मबगान,य फोिरमैला गन य िा र्स्तै अन्र् कार् य गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द र तीस िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\n(३) हिदेशीले उपदफा (१) बमोत्तजमको कसूर गरे िा गराएको रिेछ िने\nउपदफा (२) बमोत्तजमको कै द ििु ान िएको सात ठदनमिर मनजलाई नेपालबाट बाहिर\nपठाउन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५६", "title": "धाममकय िािनामा आघात पर्ु ाउय न निनु ेाः (१) कसैले लेिेर, िचनले िा आकार िा", "content": "त्तचह्नद्वारा िा अरु कुनै हकमसमबाट कुनै जात, जामत सम्प्रदार् िा िगकय ो धाममकय िािनामा\nआघात पर्ु ायउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई दईु िषसय म्म\nकै द र बीस िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५७", "title": "धाममकय रीमत-त्तस्थमतमा बाधा पर्ु ाउय न निनु ेाः (१) कसैले सनातनदेत्ति अपनाउदै िा चली", "content": "आएको अरुको धाममकय रीमत-त्तस्थमतमा जानीजानी बाधा पर्ु ायउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाईय एक िषसय म्म\nकै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५८", "title": "धम य पररितनय गराउन निनु ेाः (१) कसैले कसैको धम य पररितनय गराउन िा सो कुराको", "content": "उद्योग गन य िा दरुु त्सािन ठदन िाँदु ैन।\n(२) कसैले कुनै जात, जामत िा सम्प्रदार्मा सनातनदेत्ति चली आएको धम,य मत\nिा आस्थामा िलल पाने कुनै काम िा व्र्ििार गन य िा िलल िनु े गरी कुनै प्रलोिन\nदेिाई िा नदेिाई अन्र् कुनै धममय ा पररितनय गराउन िा धम य पररितनय गराउने मनर्तले\nत्र्स्तो धम य िा मत प्रचार गन य िाँदु ैन।\n(३) उपदफा (१) िा (२) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई पााँच\nिषसय म्म कै द र पचास िजार रुपैर्ााँसम्म जररबाना िनु ेछ।\n(४) उपदफा (१) िा (२) बमोत्तजमको कसूर गने िा गराउने व्र्त्ति हिदेशी\nरिेछ िने त्र्स्तो व्र्त्तिलाई र्स दफा बमोत्तजम िएको कै द ििु ान गरेको सात ठदनमिर\nनेपाल बाहिर पठाउन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५९", "title": "िदम्र्ादाः दफा १५८ अन्तगतय को कसूरमा त्र्स्तो कसूर िएको थािा पाएको मममतले छ", "content": "महिना र र्स पररच्छेद अन्तगतय को अन्र् कसूरमा त्र्स्तो कसूर िएकोेे मममतले तीन\nमहिना नाघेपमछ उजरु लागने छैन।\n62\nwww.lawcommission.gov.np\nपररच्छेद-१०\nिेदिाि तथा अन्र् अपमानजन्र् व्र्ििार सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६०", "title": "िेदिािपणू य व्र्ििार गन य निनु ेाः (१) कानूनमा अन्र्था व्र्िस्था िएकोमा बािेक कानून", "content": "बमोत्तजम अमधकार प्रर्ोग गने अमधकारीले त्र्स्तो अमधकार िा सामान्र् कानूनको प्रर्ोग\nगदाय उत्पत्ति, धम,य िण,य जात, जामत, मलङ्ग, शारीररक अिस्था, अपाङ्गता, स्िास्थ्र् त्तस्थमत,\nिैिाहिक त्तस्थमत, गिायिस्था, आमथकय अिस्था, िाषा िा िेर, िैचाररक आस्था िा र्स्तै अन्र्\nकुनै आधारमा कुनै पमन नागररकमामथ जानीजानी िेदिािपूण य व्र्ििार गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द िा तीस िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६१", "title": "िेदिाि गरी बस्त ु िा सेिा िररद मबक्री िा हितरण गन य निनु ेाः (१) कसैले कुनै बस्त ु िा", "content": "सेिाको िररद िा मबक्री हितरण गदाय गराउाँदा कुनै िास जात, जामत िा सम्प्रदार्को\nव्र्त्तिबाट मार िा त्र्स्ता व्र्त्तिलाई मार िररद िा मबक्री हितरण गने िा कुनै िास\nजात, जामत िा सम्प्रदार्का व्र्त्तिलाई उपलब्ध नगराउने िा मबक्री हितरण नगने कार् य\nगन य िाँदु ैन।\nतर आमथकय , सामात्तजक िा शैत्तिक दृहष्टले हपछमडएको िगकय ो हित संरिण िा\nहिकासका लामग कानून बमोत्तजम अमधकार प्राप्त अमधकारीको स्िीकृ मत मलई कुनै िास\nिस्त ु िा सेिा कुनै िास जात, जामत िा सम्प्रदार्का व्र्त्तिलाई मार उपलव्ध गराएकोमा\nिा मबक्री हितरण गरेकोमा र्स दफा बमोत्तजम कसूर गरेको मामनने छैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक िषसय म्म\nकै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६२", "title": "जिजस्य ती काममा लगाउन निनु ेाः (१) कसैले कसैलाई मनजको इच्छा हिरुद्ध काममा", "content": "लगाउन िाँदु ैन।\nतर सािजय मनक कामको लामग कानून बमोत्तजम श्रममा लगाउन र्स दफाले बाधा\nपर्ु ायएको मामनने छैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन महिनासम्म\nकै द िा पााँच िजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६३", "title": "दास बनाउन निनु ेाः (१) कसैले कुनै व्र्त्तिलाई दास िा कमारा, कमारी बनाउन, त्र्स्तो", "content": "िैमसर्तमा राख् न, काममा लगाउन िा सो सरिको अन्र् कुनै पमन व्र्ििार गन य िा गराउन\nिाँदु ैन।\n63\nwww.lawcommission.gov.np\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई पााँचदेत्ति दश\nिषसय म्म कै द र पचास िजारदेत्ति एक लाि रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६४", "title": "बन्धक बनाउन िा बाधाँ ा राख्न निनु ेाः (१) कसैले कुनै व्र्त्तिलाई कुनै पमन प्रकारको", "content": "प्रमतफल बापत कमैर्ा राख् न िा बन्धक बनाउन िा बााँधा राख् न िा बााँधाको िैमसर्तमा\nकाममा लगाउन िा सो सरिको अन्र् कुनै पमन प्रकारको व्र्ििार गन य िा गराउन\nिाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषदय ेत्ति\nसात िषसय म्म कै द र तीस िजार रुपैर्ााँेाँदेत्ति एक लाि रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६५", "title": "सामात्तजक रीमत त्तस्थमतमा िलल पान य निनु ेाः (१) कसैले कसैको सामात्तजक रीमत त्तस्थमतमा", "content": "िलल पने िा िलल िनु े गरी झक्ु र्ाई िा जबजस्य ती गरी कुनै काम गन य िा गराउन\nिाँदु ैन।\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनको लामग जातीर् िेदिाि िनु े रीमतत्तस्थमतलाई सामात्तजक\nरीमतत्तस्थमत मामनने छैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई एक िषसय म्म कै द िा दश\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६६", "title": "जामतपामतको आधारमा छुिाछुत िा अन्र् िेदिािपणू य व्र्ििार गन य निनु ेाः (१) कसैले", "content": "कसैलाई प्रथा, परम्परा, धम,य संस्कृ मत, ररमतररिाज, जात, जामत, समदु ार्, पेशा, व्र्िसार्,\nशारीररक अिस्था िा सामात्तजक सम्प्रदार्को उत्पमतको आधारमा छुिाछुत िा अन्र् कुनै\nहकमसमको िेदिाि गन य िा सािजय मनक स्थलमा उपत्तस्थत िनु िा कुनै सािजय मनक\nप्रकृ मतका धाममकय स्थलमा प्रिेश गन य रोक्न िा सािजय मनक प्रर्ोगमा रिेको पानी, पधेरो\nप्रर्ोग गन य बत्तित गन य िा अन्र् कुनै मनजी िा सािजय मनक उपर्ोग िा सहुिधाका कुराको\nप्रर्ोग गनबय ाट बत्तित गन य िाँदु ैन।\n(२) उदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द िा तीस िजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ र राष्‍ट रसेिकले र्स दफामा\nलेत्तिएको कसूर गरेमा थप तीन महिनासम्म कै द सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६७", "title": "र्ातना ठदन निनु ेाः (१) प्रचमलत कानून बमोत्तजम कसूरको अनसु न्धान गने, अमिर्ोजन गने,", "content": "कानूनको कार्ायन्िर्न गने िा कानून बमोत्तजम मनर्न्रण, हिरासत िा थनु ामा राख् ने\nअमधकार प्राप्त अमधकारीले कसैलाई शारीररक िा मानमसक र्ातना ठदन िा ठदन लगाउन\nिा क्रु र, मनममय , अमानिीर् िा अपमानजनक व्र्ििार गन य िा गराउन िाँदु ैन।\n64\nwww.lawcommission.gov.np\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनका लामग पक्राउ परेको, मनर्न्रणमा रिेको, हिरासत,\nथनु ा, कै द िा नजरबन्द िा आफ्नो सरु िामा रिेको कुनै व्र्त्ति िा त्र्स्तो व्र्त्तिको\nकारणले अन्र् कुनै व्र्त्तिलाई देिार्को उद्देश्र्ले जानीजानी शारीररक िा मानमसक पीडा\nिा कष्ट प¥ुर्ाएमा िा मनममय , अमानिीर् िा अपमानजनक व्र्ििार िा सजार् ठदएमा\nत्र्स्तो व्र्त्ति उपर र्ातना ठदएको िा क्रु र, मनममय , अमानिीर् िा अपमानजनक व्र्ििार\nगरेको मामननेछाः-\n(क) कुनै हिषर्मा जानकारी िामसल गनेेे,\n(ि) कुनै कसूरमा सामबत गराउने,\n(ग) कुनै कार्कय ो लामग दण्ड ठदने,\n(घ) जोर जलु मु िा रास देिाउने, िा\n(ङ) कानून हिपरीतका अन्र् कुनै कार् य गने।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई कसूरको गम्िीरता िेरी\nपााँच िषसय म्म कै द िा पचास िजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।\n(३) उपदफा (१) बमोत्तजमको कसूर गन य आदेश ठदने व्र्त्ति िा र्स दफा\nबमोत्तजमको कसूर गन य सिर्ोग गने ममतर्ारलाई मख्ु र् कसूरदार सरि सजार् िनु ेछ।\n(४) उपदफा (१) बमोत्तजम कसूर गने कुनै व्र्त्तिले आफू िन्दा मामथका\nअमधकारीको आदेश पालना गरी त्र्स्तो कसूर गरेको िन् ने दािी मलन पाउने छैन र\nमनजले त्र्स्तो आधारमा त्र्स्तो कसूर गरे बापत िनु े सजार्बाट उन्मत्तुि पाउने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६८", "title": "अपमानजनक िा अमानिीर् व्र्ििार गन य निनु ेाः (१) कसैले कसैलाई अपमानजनक िा", "content": "अमानिीर् व्र्ििार गन य िा गराउन ु िाँदु ैन।\n\n....................\n(क) बोक्सा बोक्सीको आरोप लगाउने,\n(ि) बोक्सा बोक्सीको आरोप लगाई बसोबास गरेको ठाउाँ बाट मनकाला\nगने,\n(ग) सामात्तजक बहिष्‍टकार गने, िा\n(घ) अन्र् जनु सकु ै काम गरी क्रु र, अमानिीर् िा अपमानजन्र् व्र्ििार\nगने।\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा त्तझहकएको।\n65\nwww.lawcommission.gov.np\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई पााँच िषसय म्म कै द र पचास\nिजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\n(३) महिलाको रजस्िला िा सत्ु के रीको अिस्थामा छाउपडीमा राख् न िा त्र्स्तै\nअन्र् कुनै हकमसमका िेदिाि, छुिाछुत िा अमानिीर् व्र्ििार गन यु िा गराउन ु िाँदु ैन।\n(४) उपदफा (३) बमोत्तजमको कसूर गने व्र्मतmलाई तीन महिनासम्म कै द िा\nतीन िजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।\n(५) राष्‍ट रसेिकले र्स दफामा लेत्तिएको कसूर गरेमा मनजलाई थप तीन\nमहिनासम्म कै द सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६९", "title": "िमतपूमत य िराई ठदन ु पनेाः र्स पररच्छेद बमोत्तजमको कसूर गने व्र्त्तिबाट पीमडत", "content": "व्र्त्तिलाई पगु ेको िमत िा पीडा बापत मनामसब िमतपूमत य िराई ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७०", "title": "िदम्र्ादाः (१) दफा १६३ र १६४ अन्तगतय का कसूरमा जहिले सकु ै उजरु लागनेछ।", "content": "(२) दफा १६७ अन्तगतय को कसूरमा त्र्स्तो कसूर िएको िा सम्बत्तन्धत व्र्त्ति\nपक्राउ, मनर्न्रण, हिरासत, थनु ा, कै द िा नजरबन्दबाट मिु िएको मममतले र र्स पररच्छेद\nअन्तगतय का अन्र् कसूरमा कसूर िए गरेको थािा पाएको मममतले छ महिना नाघेपमछ\nउजरु लागने छैन।\nपररच्छेद-११\nहििाि सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७१", "title": "मञ्ज रु ी हिना हििाि गन य निनु ेाः (१) हििाि गने व्र्त्तििरुको मञ् जरु ी हिना कसैले", "content": "कसैलाई हििाि गन य िा गराउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजम मञ् जरु ी हिना िएको हििाि बदर िनु ेछ।\n(३) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाईय दईु िषसय म्म कै द र बीस\nिजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनका लामग दफा १७३ बमोत्तजम हििाि गन य पूरा िनु ु पने\nउमेर पूरा निएको व्र्त्तिले ठदएको मञ् जरु ीलाई मञ् जरु ी मामनने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७२", "title": "िाडनातामा हििाि गन य निनु ेाः (१) कसैले परम्परा अनसु ार चली आएको अिस्थामा बािेक", "content": "िाडनाता करणीमा सजार् िनु े नातामा हििाि गन य िा गराउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको हििाि थािा नपाई िएको रिेछ िने त्र्स्तो\nहििाि बदर िनु ेछ।\n(३) उपदफा (१) बमोत्तजमको हििाि जानीजानी िएको रिेछ िने त्र्स्तो हििाि\nगनेलाई िाडनाता करणीको कसूरमा िनु े सजार् र गराउनेलाई तीन महिनासम्म कै द िा\n66\nwww.lawcommission.gov.np\nतीन िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ र त्र्स्तो हििाि स्िताः िदर\nिनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७३", "title": "बाल हििाि गन य निनु ेाः (१) हििाि गने व्र्त्तिको उमेर बीस िष य नपगु ी कसैले हििाि", "content": "गन य िा गराउन िाँदु ैन।\n(२) उपदफा (१) हिपरीत िएको हििाि स्िताः बदर िनु ेछ।\n(३) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई तीन िषसय म्म कै द र तीस\nिजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७४", "title": "हििािमा लेनदेन गन य निनु ेाः (१) आफ्नो परम्परादेत्ति चली आएको सामान्र् उपिार, िेटी,", "content": "दत्तिणा िा शरीरमा लगाएको एकसरो गिना बािेक हििाि गने दलु िा िा दलु िीका\nतफय बाट कुनै हकमसमको चल, अचल, दाइजो िा कुनै सम्पत्ति माग गरी िा लेनदेन शत य\nरािी हििाि गन य िा गराउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई तीन िषसय म्म कै द िा तीस\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।\n(३) कसैले हििाि गरी सके पमछ उपदफा (१) बमोत्तजमको चल, अचल सम्पत्ति\nिा दाइजो माग गन य िा त्र्स्तो चल, अचल सम्पत्ति िा दाइजो नठदएको कारणले दलु िी\nिा मनजका नातेदारलाई कुनै हकमसमले िैरान पान,य सताउन िा कुनै अमानिीर् िा\nअपमानजन्र् व्र्ििार गन य िाँदु ैन।\n(४) उपदफा (३) बमोत्तजमको कसूर गने व्र्त्तिलाई पााँच िषसय म्म कै द िा\nपचास िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।\n(५) उपदफा (१) िा (३) बमोत्तजम कुनै सम्पत्ति मलएकोमा त्र्स्तो सम्पत्ति\nसम्बत्तन्धत व्र्त्तिलाई हफताय ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७५", "title": "ििहुििाि गन य निनु ेाः (१) हििाहित परुु षले िैिाहिक सम्बन्ध कार्म रिेको अिस्थामा", "content": "अको हििाि गन यु िाँदु ैन।\n(२) कुनै परुु ष हििाहित िो िन् ने जानीजानी त्र्स्तो परुु षसाँग कुनै महिलाले\nहििाि गन यु िाँदु ैन।\n(३) उपदफा (१) िा (२) मा जनु सकु ै कुरा लेत्तिएको िए तापमन पमत पत्नीले\nकानून बमोत्तजम अंशिण्डा गरी मिन् न िएमा परुु ष िा महिलाले पनु ाः हििाि गन य\nसक्नेछ।\n67\nwww.lawcommission.gov.np\n(४) उपदफा (१) िा (२) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक\nिषदय ेत्ति पााँच िषसय म्म कै द र दश िजार रुपैर्ााँदेत्ति पचास िजार रुपैर्ााँसम्म जररबाना\nिनु ेछ।\n(५) उपदफा (१) बमोत्तजमको हििाि स्िताः बदर िनु ेछ।\n(६) र्स दफामा अन्र्र जनु सकु ै कुरा लेत्तिएको िए तापमन र्ो संहिता लागू\nिनु अु त्तघ तत्काल प्रचमलत कानून बमोत्तजम िएको हििािको िकमा र्स दफामा लेत्तिएको\nकुनै कुराले असर पारेको मामनने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७६", "title": "िदम्र्ादाः र्स पररच्छेद अन्तगतय को कसूरमा कसूर िए गरेको कुरा थािा पाएको मममतले", "content": "तीन महिना नाघेपमछ उजरु लागने छैन।\nपररच्छेद-१२\nज्र्ान सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७७", "title": "ज्र्ान माने मनर्तले कुनै काम गन य निनु ेाः (१) कसैले कसैको मनर्तपूिकय ज्र्ान मान य िा", "content": "ज्र्ान माने कुनै काम गन य िा गराउन िाँदु ैन।\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनको लामग कसैले कसैलाई मनजको ज्र्ान मन य सक्ने गरी\nमनर्तपूिकय गम्िीर शारीररक चोट िा िमत पर्ु ायएकोमा तत्कालै ज्र्ान नमरी सोिी चोटको\nपररणाम स्िरुपपमछ ज्र्ान मरेमा पमन सोिी व्र्त्तिले ज्र्ान मारेको मामननेछ।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई जन्म कै दको\nसजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७८", "title": "ज्र्ान जान सक्ने काम गन य निनु ेाः (१) कसैले कुनै काम गदाय साधारणतर्ा मामनसको", "content": "ज्र्ान जान सक्छ िन् ने जानीजानी िा हिश्ि ास गन यु पने कारण िाँदु ा िाँदु ै त्र्स्तो काम\nगन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कारणबाट कसैको ज्र्ान मरेमा कसूरदारलाई\nजन्मकै दको सजार् िनु ेछ।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७९", "title": "गम्िीर उिेजना िा रीसको आिेशबाट ज्र्ान मलन निनु ेाः (१) दफा १७७ िा १७८ मा", "content": "जनु सकु ै कुरा लेत्तिएको िए तापमन देिार्को अिस्थामा ज्र्ान मलने व्र्त्तिलाई दशदेत्ति\nपन्र िषसय म्म कै द र एक लाि रुपैर्ााँदेत्ति एक लाि पचास िजार रुपैर्ााँेाँसम्म जररबाना\nिनु ेछाः-\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n68\nwww.lawcommission.gov.np\n(क) कसैले तत्काल गम्िीर उिेजना ठदलाउने कुनै काम गरेबाट कसूरदारले\nआत्मसंर्म्को शत्ति गमु ाई त्र्स्तो उिेजना ठदलाउने व्र्त्तिको ज्र्ान\nमारेकोमा,\nतर देिार्को अिस्थामा र्ो िण्ड लागू िनु े छैनाः-\n(१) कसैले कानूनको पालना गदा,य मनजी रिाको\nअमधकारको प्रर्ोग गदाय, कुनै राष्‍ट रसेिकले आफ्नो\nपदीर् कतव्य र्को पालन गदाय िा पालन गन य\nलागेको कुनै कामबाट कसूरदार उिेत्तजत िनु\nगएमा,\n(२) कसैलाई कुनै िमत पर्ु ायउने मनर्तले कसूरदार\nस्िर्ंले उिेत्तजत गराएको र त्र्सरी उिेत्तजत िई\nत्र्स्तो व्र्त्तिले गरेको कामबाट कसैको ज्र्ान\nगएकोमा,\n(ि) मनजी रिाको अमधकार असल मनर्तले प्रर्ोग गदाय त्र्स्तो\nअमधकारको सीमा नाघ्न गई जसको हिरुद्ध त्र्स्तो अमधकार\nप्रर्ोग िएको िो सो व्र्त्तिको ज्र्ान मरेकोमा,\n(ग) एकाएक िएको झगडामा उठेको रीसको आिशे मा तत्काल\nकसैको ज्र्ान मरेकोमा,\nतर र्स िण्ड बमोत्तजमको काम गदाय कसूरदारले अनत्तुचत\nलाि िामसल गरेको िा क्रु र िा अस्ििाहिक तिरबाट काम गरेको\nिनु ु िाँदु ैन।\n(२) उपदफा (१) को िण्ड (ि) र (ग) मा जनु सकु ै कुरा लेत्तिएको िए तापमन\nइिी मलएर िा सोच हिचार गरेर ज्र्ान मलएकोमा सो िण्डिरुमा लेत्तिएको व्र्िस्था लागू\nिनु े छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८०", "title": "मान य चािेको व्र्त्ति नमरी अको व्र्त्ति मरेमा सजार् िनु ेाः दफा १७७, १७८ र १७९", "content": "मा जनु सकु ै कुरा लेत्तिएको िए तापमन कसैले कसैलाई माने मनर्तले िा कुनै व्र्त्ति मन य\nसक्छ िन् ने जानीजानी िा त्र्सको हिश्ि ास गन यु पने कारण िई कुनै काम गदाय त्र्स्तो\nव्र्त्ति नमरी अको व्र्त्ति मन य गएमा मनजलाई अिस्था अनसु ार दफा १७७, १७८ र\n१७९ मा लेत्तिए बमोत्तजमको सजार् िनु ेछ।\n69\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८१", "title": "लापरिािीपणू य काम गरी ज्र्ान मान य निनु ेाः (१) कसैले लापरिािीपूण य काम गरी कसैको", "content": "ज्र्ान मान य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई दफा १७७, १७८ र\n१७९ को अिस्थामा बािेक तीनदेत्ति दश िषसय म्म कै द र तीस िजार रुपैर्ादाँ ेत्ति एक\nलाि रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८२", "title": "िेलचक्र्र्ाईं गरी ज्र्ान मान य निनु ेाः (१) दफा १७९ को अिस्थामा बािेक कसैले", "content": "िेलचक्र्र्ाइपूण य कुनै काम गरी कसैको ज्र्ान मान य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई तीन िषसय म्म कै द र तीस\nिजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\n(३) उपदफा (१) मा लेत्तिएदेत्ति बािेक कसैको ज्र्ान मन य सक्छ जस्तो\nनदेत्तिएको अिस्थामा कसैले कुनै काम गदाय िहितव्र्मा परी कसैको ज्र्ान गएमा\nमनजलाई छ महिनादेत्ति दईु िषसय म्म कै द िा बीस िजार रुपैर्ासाँ म्म जररबाना िा दिु ै\nसजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८३", "title": "ज्र्ान माने उद्योग गन य निनु ेाः (१) कसैले कसैको ज्र्ान माने मनर्तले त्र्सको उद्योग", "content": "गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई दश िषसय म्म\nकै द र एक लाि रुपैर्ााँसम्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८४", "title": "आफ्नो संरिकत्िमा रिेको व्र्त्तिलाई फाल्न िा पररत्र्ाग गन य निनु ेाः (१) कुनै निजात", "content": "त्तशश,ु बालबामलका, अशि रोगी िा िद्धृ व्र्त्तिलाई आफू ले िेरचाि िा स्र्ािार सम्िार\nगने कतव्य र् िएको व्र्त्तिले मनजको त्तजउ, ज्र्ानमा ितरा पगु न सक्ने गरी फाल्न,\nपररत्र्ाग गन य िा िेिास्ता गरी छोड्न िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द र तीस िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\n(३) उपदफा (१) बमोत्तजमको कसूरबाट त्र्स्तो बालबामलका, अशि, रोगी िा\nबद्धृ व्र्त्ति मरेको रिेछ िने कसूरदारलाई सात िषसय म्म कै द र सिरी िजार रुपैर्ााँसम्म\nजररबाना िनु ेछ।\nतर फामलएको, पररत्र्ाग गररएको िा िेिास्ता गरी छाडेको कारणबाट निजात\nत्तशशकु ो मत्ृ र् िएमा दफा १७७ बमोत्तजम सजार् िनु ेछ।\n70\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८५", "title": "आत्मित्र्ा गन य दरुु त्सािन ठदन निनु ेाः (१) कसैले कसैलाई आत्मित्र्ा गन य दरुु त्सािन", "content": "ठदन िा त्र्स्तो काम गने सम्मको पररत्तस्थमत िडा गन य िा गराउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई पााँच िषसय म्म कै द र पचास\nिजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८६", "title": "िमतपूमत य िराई ठदन ु पनेाः र्स पररच्छेद बमोत्तजम िएको कसूरबाट कसैको त्तजउ, ज्र्ान िा", "content": "सम्पत्तिमा िामन, नोक्सानी िा िमत िएमा कसूरदारबाट पीमडत व्र्त्ति र मनज निए\nमनजको िकिालालाई मनामसब िमतपूमत य िराई ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८७", "title": "िदम्र्ादाः (१) दफा १७७, १७८, १७९, १८०, १८१, १८२ र १८४ को उपदफा (३)", "content": "\nमा रिेको प्रमतबन्धात्क िाक्र्ांश अन्तगतय का कसूरदार आफैं सामबत िई पोलेकोमा\nजहिलेसकु ै पमन उजरु लागनेछ। त्र्स्तो कसूरमा कतव्य र्को उजरु ी परेकोमा\nअनसु न्धानबाट कतव्य र्िाला र्िी िो िन् ने पिा नलागेकोमा बीस िषपय मछ र कतव्य र्को\nउजरु नपरेकोमा सो िारदात िएको दईु िषपय मछ उजरु ी लागने छैन।\n(२) उपदफा (१) मा लेत्तिएदेत्ति बािेकका र्स पररच्छेद अन्तगतय का अन्र्\nकसूरमा त्र्स्तो कसूर िएको कुरा थािा पाएको मममतले छ महिना नाघेपमछ उजरु लागने\nछैन।\nपररच्छेद-१३\nगि य संरिण हिरुद्धको कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८८", "title": "गिपय तन गन य निनु ेाः (१) दफा १८९ को अिस्थामा बािेक कसैले गिपय तन गन य िा", "content": "गिपय तन गराउने मनर्तले िा गि य पतन िनु सक्छ िन् ने जानीजानी िा हिश्ि ास गन यु पने\nकुनै काम गरी गिपय तन गराउन ु िाँदु ैन।\n(२) कसैले गििय ती महिलालाई करकाप गरी िा धम्की ठदई िा ललाई फकाई\nिा प्रलोिनमा पारी गिपय तन गराउन िाँदु ैन।\n(३) उपदफा (१) िा (२) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई देिार्\nबमोत्तजमको सजार् िनु ेछाः-\n(क) बाह्र िप्तासम्मको गि य िए एक िषसय म्म कै द र दश िजार\nरुपैर्ााँसम्म जररबाना,\n(ि) बाह्र िप्तािन्दा बढी पच्चीस िप्तासम्मको गि य िए तीन िषसय म्म\nकै द र तीस िजार रुपैर्ासाँ म्म जररबाना,\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n71\nwww.lawcommission.gov.np\n(ग) पच्चीस िप्तािन्दा बढीको गि य िए पााँच िषसय म्म कै द र पचास\nिजार रुपैर्ासाँ म्म जररबाना।\n(४) गिपय तन गने काम गदाय तत्काल गिपय तन निई बच्चा त्तजउाँदो जन्मी त्र्स्तो\nकामको पररणाम स्िरुप जत्तन्मएको बच्चा तत्काल मरेमा र्स दफाको प्रर्ोजनका लामग\nगिपय तन गराएको मामनने छ।\n(५) कसैले कुनै गििय ती महिलाको ज्र्ान मलने उद्योग गदाय त्र्स्ती महिला नमरी\nमनजको गिमय ा रिेको पच्चीस िप्ता िा पच्चीस िप्तािन्दा बढी अिमधको गि य पतन िनु\nगएमा सो काम गने कसूरदारलाई र्स संहिता िा अन्र् कानून बमोत्तजमको सजार्मा थप\nपााँच िषसय म्म कै द िनु ेछ।\n(६) र्स दफामा अन्र्र जनु सकु ै कुरा लेत्तिएको िए तापमन कसैले कुनै गििय ती\nमहिला हिरुद्ध कुनै ररस इिीले कुनै काम गदाय गिपय तन िनु गएमा गिपय तन गने मनर्तले\nत्र्स्तो काम गरेको रिेनछ िने पमन देिार् बमोत्तजमको सजार् िनु ेछाः-\n(क) बाह्र िप्तासम्मको गि य िए एक िषसय म्म कै द,\n(ि) बाह्र िप्तािन्दा बढी पच्चीस िप्तासम्मको गि य िए तीन िषसय म्म\nकै द,\n(ग) पच्चीस िप्तािन्दा बढीको गि य िए पााँच िषसय म्म कै द।\n(७) कसैले गिपय तन गराउने उद्देश्र्ले गिमय ा रिेको भ्रणु को मलङ्ग पहिचान िनु े\nकुनै काम गन य िा गराउन र त्र्सरी मलङ्ग पहिचान िएपमछ गिपय तन गन य िा गराउन ु\nिाँदु ैन।\n(८) उपदफा (७) बमोत्तजमको कसूर गने व्र्त्तिलाई देिार् बमोत्तजमको सजार्\nिनु ेछाः-\n(क) गिपय तन गराउने उद्देश्र्ले गिमय ा रिेको भ्रणु को मलङ्ग पहिचान गने\nिा गराउनेलाई तीन महिनादेत्ति छ महिनासम्म कै द, र\n(ि) मलङ्ग पहिचान गरी गिपय तन गने िा गराउनेलाई उपदफा (३) मा\nलेत्तिएको सजार्मा थप एक िषसय म्म कै द।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८९", "title": "गि य पतन गराउन सक्नेाः दफा १८८ मा जनु सकु ै कुरा लेत्तिएको िए तापमन", "content": "स्िास्थ्र्कमीले देिार्को अिस्थामा गिपय तन गराएकोमा र्स संहिता अन्तगतय को कसूर िए\nगरेको मामनने छैनाः-\n(क) गििय ती महिलाको मञ् जरु ीले बाह्र िप्तासम्मको गिपय तन गराएकोमा,\n72\nwww.lawcommission.gov.np\n(ि) गिपय तन नगराएमा गििय ती महिलाको ज्र्ानमा ितरा पगु न सक्छ िा\nमनजको शारीररक िा मानमसक स्िास्थ्र् िराब िनु सक्छ िा हिकलाङ्ग\nबच्चा जन्मन्छ िनी इजाजत प्राप्त त्तचहकत्सकको रार् िई त्र्स्ती\nमहिलाको मञ्ज रु ीले गिपय तन गराएकोमा,\n(ग) जिजस्य ती करणी िा िाडनाता करणीबाट रिन गएको अठार िप्तासम्मको\nगि य गििय ती महिलाको मञ् जरु ीले गिपय तन गराएकोमा,\n(घ) रोग प्रमतरोधक िमता उन्मत्तुि गने त्तजिाण ु (एच.आई.िी.) िा त्र्स्तै\nप्रकृ मतको अन्र् मनको निनु े रोग शरीरमा िएकी महिलाको मञ् जरु ीले\nगिपय तन गराएकोमा।\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनको लामग “स्िास्थ्र्कमी” िन् नाले\nमनधायररत र्ोगर्ता पगु ी गिपय तन गराउन इजाजत प्राप्त गरेको त्तचहकत्सक\nिा स्िास्थ्र्कमी सम्झन ु पछ।य", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९०", "title": "िदम्र्ादाः र्स पररच्छेद अन्तगतय को कसूरमा त्र्स्तो कसूर िएको कुरा थािा पाएको", "content": "मममतले छ महिना नाघेपमछ उजरु लागने छैन।\nपररच्छेद-१४\nकुटहपट िा अङ्गिङ्ग सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९१", "title": "कुटहपट गन य निनु ेाः (१) कसैले कसैलाई कुटहपट गन य िाँदु ैन।", "content": "(२) कसैले कसैलाई देिार्को कुनै कार् य गरेमा मनजले कुटहपट गरेको मामननेछाः-\n(क) कुनै हकमसमको शारीररक पीडा प¥ुर्ाएमा,\n\n(ि) कुनै काम गरी दफा १०४ र १०५ मा उत्तल्लत्तित रोग\nबािेकको अन्र् कुनै रोग सारेमा,\n(ग) अन्र् कुनै कार् य गरी अशि बनाएमा ।\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनको लामग “अशि” िन् नाले शरीरको कुनै अङ्ग सामान्र्\nरुपमा काम गन य नसक्ने गरी अशि िएको अिस्था सम्झन ु पछ य र सो शब्दले मानमसक\nअशितालाई समेत जनाउाँछ।\n(३) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द िा तीस िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९२", "title": "अङ्गिङ्ग गन य निनु ेाः (१) कसैले कसैको अङ्गिङ्ग गन य िा गराउन िाँदु ैन।", "content": " मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा थप।\n73\nwww.lawcommission.gov.np\n(२) कसैले कसैलाई जानीजानी कुटहपट गदाय देिार् बमोत्तजमको पररणाम िएमा\nअङ्गिङ्गको कसूर गरेको मामननेछाः-\n(क) आिाँ ाको िेने शत्ति िीन गरी िा आिाँ ा फोरी दृहष्टहििीन\nबनाइठदएमा,\n(ि) नाकको साँघ्ु ने शत्ति नाश गररठदएमा,\n(ग) कानको सन्ु ने शत्ति नाश गररठदएमा,\n(घ) त्तजब्रोको बोल्ने शत्ति नाश गररठदएमा,\n(ङ) महिलाको स्तन काहटठदएमा,\n(च) महिलालाई बााँझोपन िा परुु षलाई परुु षत्ििीन बनाएमा,\n(छ) मेरुदण्ड, डडाँ ाल्न,ु िात िुट्टा िा त्र्स्ता अङ्गको जोनी िााँची, फोरी,\nफुकाली बेकम्मा पाररठदएमा,\n(ज) कुटहपटको कारणबाट आफ्नो पेशाको काम गन य नसक्ने गरी\nअसिम बनाइठदएमा।\n(३) कुटहपटबाट तत्काल अङ्गिङ्ग निए तापमन सोिी कामको पररणाम स्िरुप\nपमछ उपदफा (२) बमोत्तजमको पररणाम मनस्के मा पमन अङ्गिङ्ग िएको मामननेछ।\n(४) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई दश िषसय म्म कै द र एक\nलाि रुपैर्ासाँ म्म जररबाना िनु ेछ।\n(५) उपदफा (४) मा जनु सकु ै कुरा लेत्तिएको िए तापमन एउटै हकमसमको काम\nठदने एउटािन्दा बढी अङ्ग िनु ेमा त्र्समध्र्े एउटा अङ्गमार बेकम्मा पारी ठदएको िए सो\nउपदफामा लेत्तिएको सजार्को आधा सजार् िनु ेछ र अङ्गिङ्ग िएको ित मनको िई\nकामलागने िएमा तीनिषसय म्म कै द र तीस िजार रुपैर्ााँसम्म जररबाना िनु ेछ।\n\n१९२क. तेजाब प्रर्ोग गरी अङ्गिङ्ग गन य निनु ेाः (१) कसैले कसैलाई तेजाब फ्र्ााँकी, छहकयई, िन्र्ाई\nिा प्रर्ोग गरी िा सेिन गराई अङ्गिङ्ग गन यु िा गराउन ु िा शारीररक िमत पर्रु र्ाउन ु\nिाँदु ैन।\nस्पष्‍ट टीकरण: र्स संहिताको प्रर्ोजनका लामग \"तेजाब\" िन् नाले मानि अङ्ग,\nजीिजन्त ु िा अन्र् जैहिक िा गैरजैहिक िस्तलु ाई जलाउने (बन)य , घातक िमत पर्रु र्ाउने\n(कोरोमसि) िा अन्र् कुनै हकमसमले गम्िीर असर पर्रु र्ाउने अकारबोमनक (इनअगायमनक)\nएमसडजन्र् रासार्मनक पदाथ य सम्झन ु पछ य र सो शब्दले नाइहरक एमसड, सल्फररक एमसड\n फौजदारी कसूर तथा फौजदारी कार्हयिमध सम्बन्धी के िी ऐन संशोधन गने ऐन, २०७९ द्वारा थप।\n74\nwww.lawcommission.gov.np\nर िाइड्रोक्लोररक एमसड तथा अन्र् घातक तथा ज्िलनशील रासार्मनक पदाथलय ाई समेत\nजनाउाँछ।\n(२) उपदफा (१) बमोत्तजमको कुनै कार् य गदा य िा त्र्स्तो कार्कय ो पररणाम\nस्िरुप कसैको दिु ै आिाँ ा जली िा िमत िई पूणरूय पमा दृहष्ट नष्‍ट ट िएमा, दिु ै कान जली\nिा िमत िई सन्ु ने शत्ति पूणरूय पमा नष्‍ट ट िएमा, नाक जली िा िमत िई काम नलागने\nिएमा, अनिु ार पूणरूय पमा जली िा िमत िई कुरुप िएमा, महिला िए दिु ै स्तन जली िा\nिमत िई काम नलागने िएमा िा कसैको र्ौनाङ्ग जली िा िमत िई नामसएमा त्र्स्तो\nकसूर गने िा गराउने व्र्त्तिलाई बीस िष य कै द र दश लाि रुपैर्ा ाँ जररबाना िनु ेछ।\n(३) उपदफा (२) मा लेत्तिएकोमा बािेक उपदफा (१) बमोत्तजमको कुनै कार् य\nगरी िा त्र्सको पररणाम स्िरूप कसैको एउटा आिाँ ा, एउटा कान जली िा िमत िई\nकाम नलागने िएमा, आंत्तशक रुपमा अनिु ार जली िा िमत िई कुरुप िएमा, महिला िए\nएउटा स्तन जली िा िमत िई काम नलागने िएमा, दिु ै िात जली काम नलागने िएमा\nिा दिु ै गोडा पूणरूय पमा जली काम नलागने िएमा, टाउकोको कुनै िाग जली िमत िएमा\nिा मेरुदण्ड जली िा िमत िई काम नलागने िएमा पन्र िष य देत्ति बीस िषसय म्म कै द र\nसात लाि रुपैर्ााँदेत्ति दश लाि रुपैर्ााँसम्म जररबाना िनु ेछ।\n(४) उपदफा (२) िा (३) मा लेत्तिएकोमा बािेक उपदफा (१) बमोत्तजमको\nकुनै कार् य गदाय िा त्र्सको पररणाम स्िरूप कसैको शरीरको अन्र् कुनै अङ्गिङ्ग िा\nशारीररक िमत िएमा कसूरको प्रकृ मत बमोत्तजम सात िषदय ेत्ति दश िषसय म्म कै द र पााँच\nलाि रुपैर्ााँदेत्ति सात लाि रुपैर्ासाँ म्म जररबाना िनु ेछ।\n(५) उपदफा (१) बमोत्तजम िएको कसूरबाट पीमडत व्र्त्तिको तत्काल मत्ृ र् ु\nनिई सोिी कार्कय ो पररणाम स्िरूप त्र्स्तो कसूर िएको मममतले एक िषमयिर मत्ृ र् ु\nिएमा ज्र्ान मारेको कसूर र उपदफा (२), (३) िा (४) बमोत्तजमको पररणाम मनस्के मा\nसोिी उपदफा बमोत्तजमको कसूर िएको मामननेछ।\n(६) कसैले उपदफा (१) बमोत्तजमको कार् य गन य िोज्दा सम्बत्तन्धत व्र्त्तिलाई\nनलागेमा िा कोिी त्र्सबाट छमलएमा िा उत्तम्कएमा त्र्स्तो कार् य गन य िोज्ने व्र्त्तिले\nर्स दफा बमोत्तजम कसूर गन य उद्योग गरेको मामननेछ र सो िापत पााँच िषदय ेत्ति सात\nिषसय म्म कै द र एक लाि रुपैर्ााँदेत्ति तीन लाि रुपैर्ााँसम्म जररबाना िनु ेछ।\n(७) उपदफा (२), (३) िा (४) बमोत्तजम जररबाना बापत प्राप्त पूरै रकम\nपीमडतलाई िमतपूमत य बापत ठदन ु पनेछ।\n75\nwww.lawcommission.gov.np\n(८) र्स दफा बमोत्तजम िएको कसूरबाट पीमडत व्र्त्तिलाई िएको शारीररक र\nमानमसक पीडा र अङ्गिङ्गको गम्िीरता तथा जररबाना रकम समेत हिचार गरी सजार्\nमनधायरण गदाय मनामसब िमतपूमत य िराउन ु पनेछ।\n ", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९३", "title": "ज्िलनशील जैहिक िा हिषाल ु पदाथ य प्रर्ोग गरी कुरुप पान य निनु ेाः (१) कसैले कसैलाई", "content": "तेजाब िा त्र्स्तै प्रकारका अन्र् रासार्मनक पदाथ य बािेकका अन्र् ज्िलनशील, जैहिक िा\nहिषाल ु पदाथ य प्रर्ोग गरी िा फ्र्ााँकी, छहकयई, िन्र्ाई िा त्र्स्तो पदाथलय े पोली, डामी, दली,\nघसी जीउमा पीडा गराउने िा अनिु ार िा शरीरको कुनै अङ्ग कुरुप पाने काम गन यु िा\nगराउन ु िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई कसूरको प्रकृ मत िेरी\nअनिु ार कुरुप पारेमा पााँच िषदय ेत्ति आठ िषसय म्म कै द र एक लाि रुपैर्ााँदेत्ति पााँच लाि\nरुपैर्ााँसम्म जररबाना र शरीरको अन्र् अङ्ग कुरुप पारेमा िा शरीरमा पीडा प¥ुर्ाएमा तीन\nिषदय ेत्ति पााँच िषसय म्म कै द र पचास िजार रुपैर्ााँदेत्ति तीन लाि रुपैर्ााँसम्म जररबाना\nिनु ेछ।\n(३) उपदफा (२) बमोत्तजम जररबाना बापत प्राप्त पूरै रकम पीमडतलाई िमतपूमत य\nबापत ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९४", "title": "गम्िीर उिेजना िा रीसको आिेशबाट कुटहपट िा अङ्गिङ्ग िएकोमा सजार्ाः (१) दफा", "content": "१९१ िा १९२ मा जनु सकु ै कुरा लेत्तिएको िए तापमन देिार्को अिस्थामा कुटहपट गने\nव्र्त्तिलाई कुटहपट गरी अङ्गिङ्ग गरेको रिेछ िने दईु िषसय म्म कै द िा बीस िजार\nरुपैर्ााँसम्म जररबाना िा दिु ै सजार् र अन्र् कुनै हकमसमले चोट पर्ु ायएको रिेछ िने एक\nिषसय म्म कै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछाः-\n(क) कसैले तत्काल गम्िीर उिेजना ठदलाउने कुनै काम गरेबाट कसूरदारले\nआत्मसंर्म्को शत्ति गमु ाई त्र्स्तो उिेजना ठदलाउने व्र्त्तिलाई िा\nभ्रमिस अरु कसैलाई कुटहपट गरेमा िा संर्ोगिश अरु कसैलाई चोट\nपगु न गएकोमा।\nतर देिार्को अिस्थामा र्ो िण्ड लागू िनु े छैनाः-\n(१) कसैले कानूनको पालन गदाय, मनजी रिाको\nअमधकारको प्रर्ोग गदाय, कुनै राष्‍ट रसेिकले आफ्नो\nपदीर् कतव्य र्को पालन गदाय िा पालन गन य\n फौजदारी कसूर तथा फौजदारी कार्हयिमध सम्बन्धी के िी ऐन संशोधन गने ऐन, २०७९ द्वारा त्तझहकएको।\n फौजदारी कसूर तथा फौजदारी कार्हयिमध सम्बन्धी के िी ऐन संशोधन गने ऐन, २०७९ द्वारा संशोमधत।\n76\nwww.lawcommission.gov.np\nलागेको कुनै कामबाट उिेत्तजत िनु गई कुटहपट\nगरेकोमा,\n(२) कसैलाई कुनै िमत पर्ु ायउने मनर्तले कसूरदार\nस्िर्ंले कसैलाई उिेत्तजत गराएको र त्र्सरी\nउिेत्तजत िई त्र्स्तो व्र्त्तिले गरेको कामबाट\nकसूरदार आफैँ उिेजनामा परी कुटहपट गरी चोट\nपर्ु ायएकोमा ।\n(ि) मनजी रिाको लामग आिश्र्क पने बलिन्दा बढी बल प्रर्ोग गरी\nकसैलाई िमत पर्ु ायएकोमा,\n(ग) एकाएक उठेको झगडाको रीसको आिेशमा तत्काल कसैलाई चोट\nपर्ु ायएकोमा।\nतर र्स िण्ड बमोत्तजमको काम गदाय कसूरदारले अनत्तुचत लाि\nिामसल गरेको िा क्रु र िा अस्ििाहिक तिरबाट काम गरेको िनु ु िाँदु ैन।\n(२) उपदफा (१) को िण्ड (ि) र (ग) मा जनु सकु ै कुरा लेत्तिएको िए तापमन\nइिी मलएर िा सोच हिचार गरेर कुटहपट िा अङ्गिङ्ग गरेकोमा सो िण्डिरुमा लेत्तिएको\nव्र्िस्था लागू िनु े छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९५", "title": "लापरिािीपणू य काम गरी िा िेलचरm्र्ाई गरी कुटहपट गन य िा अङ्गिङ्ग िा अन्र् चोट", "content": "पर्ु ाउय न निनु ेाः (१) कसैले लापरिािीपूण य काम गरी िा िेलचेक्र्र्ाइाँ गरी कसैलाई कुटहपट\nगन,य अङ्गिङ्ग गन य िा अन्र् चोट पर्ु ायउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई देिार् बमोत्तजमको सजार्\nिनु ेछाः-\n(क) लापरिािीपूण य काम गरी अङ्गिङ्ग िएकोमा दईु िषसय म्म कै द िा\nबीस िजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् र अन्र् हकमसमको\nचोट पगु ेको रिेछ िने एक िषसय म्म कै द िा दश िजार\nरुपैर्ााँसम्म जररबाना िा दिु ै सजार्,\n(ि) िेलचेक्र्र्ाइाँ गरी त्र्स्तो कसूर गरेको रिेछ िने छ महिनासम्म\nकै द िा पााँच िजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९६", "title": "आपरामधक बल प्रर्ोग गन य निनु ेाः (१) कसैले कसै उपर आपरामधक बल प्रर्ोग गन य", "content": "िाँदु ैन।\n77\nwww.lawcommission.gov.np\n(२) कसैले कसैलाई देिार् बमोत्तजमको कार् य गरेमा मनजले आपरामधक बल\nप्रर्ोग गरेको मामननेछाः-\n(क) कुनै कसूर गने मनर्तले कुनै व्र्त्ति उपर कुनै हकमसमको बल\nप्रर्ोग गरेमा,\n(ि) कुनै व्र्त्ति िा मनजको पररिार िा सम्पत्तिलाई िमत पर्ु ायउने डर,\nरास उत्पन् न गराउने िा त्तझझ्र्ाउने मनर्तले िा त्र्स्तो िनु सक्छ\nिन् ने जानीजानी मनज उपर बल प्रर्ोग गरेमा,\n(ग) कसैलाई आफू उपर बल प्रर्ोग िनु लागेको िन् ने रमसत पारेमा\nिा धम्की ठदएमा िा जोर जलु मु गरेमा िा अरु कुनै हकमसमले\nत्र्सको उद्योग गरेमा।\n(३) र्स दफामा अन्र्र जनु सकु ै कुरा लेत्तिएको िए तापमन सम्बत्तन्धत हिषर्को\nत्तशिण, प्रत्तशिण िा तामलम ठदाँदा, कुनै हकमसमको अमिनर् गदाय, उपचार गदाय िा िलाई\nिनु े हकमसमले कसैको मञ्ज रु ी मलई कुनै बल प्रर्ोग गरेकोमा िा कुनै हकमसमको िेल\nिाँदु ा स्ििाहिक प्रकृ मतको बल प्रर्ोग गरेकोमा आपरामधक बल प्रर्ोग गरेको मामनने\nछैन। तर कसैलाई िमत पर्ु ायउने बदमनर्तले बल प्रर्ोग गरेकोमा र्स उपदफाको\nव्र्िस्था लागू िनु े छैन।\n(४) आपरामधक बल प्रर्ोग गने िा गराउने व्र्त्तिलाई िमतर्ार मलई गरेको िए\nतीन िषसय म्म कै द िा तीस िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् र िमतर्ार नमलई\nगरेको िए एक िषसय म्म कै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९७", "title": "कसूर गने मनर्तले ििे ोस पान य निनु ेाः (१) कसैले कुनै कसूर गन य सत्तजलो पाने मनर्तले", "content": "अरुलाई िेिोस तल्ु र्ाउने, लठ्याउने िा अस्िस्थ पाने पदाथ य िुिाउन िा अन्र् कुनै\nप्रकारले सेिन गराउन िा कुनै प्रकारले िेिोस गराउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक िषसय म्म\nकै द र दश िजार रुपैर्ााँसम्म जररबाना िनु ेछ।\n(३) उपदफा (१) बमोत्तजमको काम गरी त्र्स्तो कसूर िइसके को रिेछ िने\nत्र्स्तो कसूर बापत िनु े सजार्मा र्स दफा बमोत्तजमको सजार् थप िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९८", "title": "िमतपूमताःय र्स पररच्छेदमा उत्तल्लत्तित कसूरबाट कसैको जीउ िा ज्र्ानमा चोटपटक िा", "content": "िामन, नोक्सानी िएको रिेछ िने कसूरदारबाट पीमडत व्र्त्तिलाई मनामसब िमतपूमत य िराई\nठदन ु पनेछ।\n78\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९९", "title": "िदम्र्ादाः दफा १९६ अन्तगतय को कसूरमा त्र्स्तो कसूर िए गरेको मममतले तीन महिना", "content": "नाघेपमछ, दफा १९७ अन्तगतय को कसूरमा त्र्स्तो व्र्त्तिको िोस आएको मममतले छ\nमहिना नाघेपमछ र र्स पररच्छेद अन्तगतय को अन्र् कसूरमा त्र्स्तो कसूर िएको मममतले\nएक िष य नाघेपमछ उजरु लागने छैन।\nपररच्छेद-१५\nगैरकानूनी थनु ा सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२००", "title": "बदमनर्तपिू कय थनु छेक गन य निनु ेाः (१) कसैले कुनै व्र्त्तिलाई कानून बमोत्तजम बािेक", "content": "बदमनर्तपूिकय अन्र् कुनै हकमसमले थनु ामा राख् न िा राख् न लगाउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई तीन िषसय म्म कै द र तीस\nिजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\n(३) अमधकार प्राप्त व्र्त्तिले बािेक अरु कसैले कसैको आिागमनमा अिरोध गन य\nिा गराउन िाँदु ैन।\n(४) उपदफा (३) बमोत्तजमको कसूर गने व्र्त्तिलाई छ महिनासम्म कै द िा पााँच\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२०१", "title": "मानिोत्तचत न्र्ूनतम सहुिधा नठदई थनु ामा राख्न निनु ेाः (१) कानून बमोत्तजम थनु ामा राख् ने", "content": "अमधकार प्राप्त अमधकारीले कसैलाई पमन कानून बमोत्तजम उपलब्ध गराउन ु पने सहुिधा\nनठदई िा थनु ामा रात्तिएको ठाउाँमा उपलब्ध न्र्ूनतम मानिोत्तचत सहुिधा नठदई थनु ामा\nराख् न िा राख् न लगाउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई डेढ िषसय म्म कै द र पन्र\nिजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२०२", "title": "छाड्ने आदेश िएकोमा थनु ी राख्न निनु ेाः (१) कानून बमोत्तजम थनु ामा रिेको कुनै", "content": "व्र्त्तिलाई थनु ाबाट छाड्न कानून बमोत्तजम अमधकार प्राप्त अमधकारीबाट आदेश प्राप्त\nिएपमछ त्र्स्तो व्र्त्तिलाई थनु ाबाट नछाडी थनु ी राख्न िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक िषसय म्म\nकै द र दश िजार रुपैर्ााँसम्म िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२०३", "title": "गोप्र् तररकाले थनु ामा राख्न निनु ेाः (१) अमधकार प्राप्त अमधकारीले कुनै व्र्त्तिलाई", "content": "थनु ामा राख्दा मनज थमुनएको कुरा िा थमुनएको ठाउाँको जानकारी निनु े िा पिा नलागने\nगरी गोप्र् रुपमा थनु ामा राख् न ु िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई चार िषसय म्म\nकै द र चालीस िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\n79\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२०४", "title": "िमतपूमत य िराई ठदन ु पनेाः र्स पररच्छेद बमोत्तजमको कसूर गने िा गराउने कसूरदारबाट", "content": "पीमडत व्र्त्तिलाई मनामसब िमतपूमत य िराई ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२०५", "title": "िदम्र्ादाः दफा २०० को उपदफा (३) अन्तगतय को कसूरमा त्र्स्तो कसूर िएको मममतले", "content": "र र्स पररच्छेद अन्तगतय का अन्र् कसूरमा थनु ामा परेको व्र्त्ति थनु ाबाट मिु िएको\nमममतले तीन महिना नाघेपमछ उजरु लागने छैन।\nपररच्छेद-१६\nव्र्त्ति बेपिा पाने सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२०६", "title": "व्र्त्ति बेपिा पाने काम गन य गराउन निनु ेाः (१) कसैले कसैलाई बेपिा पाने कार् य गन य िा", "content": "गराउन िाँदु ैन।\n(२) उपदफा (१) को प्रर्ोजनको लामग “व्र्त्ति बेपिा पाने कार्”य िन् नाले\nदेिार्को कार् य सम्झन ु पछयाः-\n(क) कानून बमोत्तजम पक्राउ गन,य अनसु न्धान गन य िा कानून\nकार्ायन्िर्न गन य अत्तख्तर्ारी पाएको व्र्त्ति िा सरु िाकमीले पक्राउ\nगरेको, हिरासतमा रािेको िा अन्र् कुनै हकमसमले मनर्न्रणमा\nमलएको व्र्त्तिलाई मद्दु ा िेने अमधकारी समि त्र्सरी पक्राउ\nगरेको िा मनर्न्रणमा मलएको मममतले बाटोको म्र्ाद बािेक\nचौबीस घण्टामिर उपत्तस्थत नगराई िा सरोकारिालालाई िेटघाट\nगन य नठदई मनजलाई किााँ, कसरी र कुन अिस्थामा रात्तिएको छ\nिन् ने सम्बन्धमा जानकारी नठदने,\n(ि) कुनै व्र्त्ति, सङ्गठन िा सङ्गठठत िा असङ्गठठत समूिको नामबाट\nकुनै व्र्त्तिलाई अपिरण गरी, कब्जा िा मनर्न्रणमा मलई िा\nअन्र् कुनै हकमसमले मनजको िैर्त्तिक स्ितन्रताबाट ित्तित\nगरेकोमा त्र्सरी ित्तित गनकयु ो कारण तथा मनजलाई किााँ, कसरी\nर कुन अिस्थामा रात्तिएको छ िन् ने सम्बन्धमा सरोकारिालालाई\nजानकारी नठदने।\n(३) कुनै व्र्त्तिलाई जनु व्र्त्तिको आदेशले पक्राउ गरी, थनु ामा रािी िा\nमनर्न्रणमा मलई िेपिा पारेको िो त्र्स्तो आदेश ठदने र त्र्स्तो आदेशको कार्ायन्िर्न\nगने व्र्त्ति बेपिा पाने मख्ु र् कसूरदार मामननेछ।\n(४) व्र्त्ति बेपिा पाने कार् य कुनै सािजय मनक पद धारण गरेको व्र्त्ति िा\nसङ्गठन िा सङ्गठठत िा असङ्गठठत समूिको त्तजम्मेबार व्र्त्तिको आदेश िा मनदेशन\n80\nwww.lawcommission.gov.np\nबमोत्तजम िए गरेको रिेछ िने त्र्स्तो आदेश िा मनदेशन ठदने व्र्त्ति बेपिा पाने मख्ु र्\nकसूरदार मामननेछ।\n(५) कसैले आफू मातितको पदामधकारी, मनकार् िा समूिद्वारा व्र्त्ति बेपिा पाने\nकार् य गन य िा गराउन लागेको कुरा थािा पाएर पमन त्र्सको उपेिा गरेमा िा त्र्स्तो\nकार् य रोक्ने सम्बन्धमा आिश्र्क उपार् नअपनाएमा मनजले समेत र्स दफा बमोत्तजम\nकसूर गरेको मामननेछ।\n(६) कुनै व्र्त्तिलाई एकिन्दा बढी व्र्त्तिले सामूहिक रुपमा बेपिा पारेमा\nत्र्स्तो कार्मय ा संलगन प्रत्र्ेक व्र्त्ति समान रुपमा कसूरदार मामननेछ।\n(७) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई देिार् बमोत्तजमको सजार्\nिनु ेछाः-\n(क) व्र्त्ति बेपिा पानेलाई बेपिा पारेको अिमध र अिस्थालाई समेत\nहिचार गरी त्र्स्तो काम गने मख्ु र् कसूरदारलाई पन्र िषसय म्म\nकै द र पााँच लाि रुपैर्ााँसम्म जररबाना,\n(ि) व्र्त्ति बेपिा पान य ममतर्ार बन्न े िा षड् र्न्र गनेलाई व्र्त्ति बेपिा\nपाने मख्ु र् कसूरदार सरि र सोको उद्योग गने िा पररपि\nममलाउने व्र्त्तिलाई मख्ु र् कसूरदारलाई िनु े सजार्को आधा\nसजार्।\n(८) महिला िा बालबामलका हिरुद्ध उपदफा (१) बमोत्तजमको कसूर मामनने कार् य\nगनेलाई उपदफा (७) बमोत्तजम िनु े सजार्मा थप दईु िष य कै द सजार् िनु ेछ।\n(९) कसैले कुनै व्र्त्तिलाई बेपिा पाररएको अिस्थामा िेपिा पाररएको व्र्त्तिको\nहिरुद्ध कानून बमोत्तजम सजार् िनु े अन्र् कुनै कसूर गरेको रिेछ िने मनजलाई त्र्स्तो\nकसूर बापत कानून बमोत्तजम िनु े सजार्मा र्स दफा बमोत्तजम थप सजार् िनु ेछ।\n(१०) सरकारी साधन, ििन, िातिमतर्ार िा मालसामान प्रर्ोग गरी व्र्त्ति बेपिा\nपाने व्र्त्तिलाई र्स दफामा िनु े सजार्मा थप एक िष य कै द िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२०७", "title": "कसूरसाँग सम्बत्तन्धत मालसामान जफत िनु ेाः र्स पररच्छेद अन्तगतय सजार् िनु े कसूर गदाय", "content": "सम्बत्तन्धत धनीले जानीजानी प्रर्ोग गन य ठदएको िा धनीको सिममतले प्रर्ोग गररएका घर\nजगगा, सिारी साधन, िातिमतर्ार तथा अन्र् सबै मालसामान जफत िनु ेछन।्\nतर सरकारी ििन, साधन, िातिमतर्ार तथा मालसामान जफत िनु े छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२०८", "title": "िमतपूमत य िराई मलन पाउनेाः (१) बेपिा पाररएको व्र्त्ति पमछ सािजय मनक िएमा िा", "content": "गररएमा मनजले बेपिा पाने व्र्त्तिबाट मनामसब िमतपूमत य िराई मलन पाउनेछ।\n81\nwww.lawcommission.gov.np\n(२) बेपिा पाररएको व्र्त्तिको मत्ृ र् ु िइसके को िए उपदफा (१) बमोत्तजमको\nिमतपूमत य मनजको नत्तजकको िकिालाले िराई मलन पाउनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२०९", "title": "धनमाल हफता य गन यु पनेाः र्स पररच्छेद बमोत्तजम कसैले कुनै व्र्त्तिलाई बेपिा पादा य", "content": "त्र्स्तो व्र्त्तिको धनमाल समेत मलएको रिेछ िने त्र्सरी बेपिा पाने व्र्त्तिबाट बेपिा\nपाररएको िा मनजको नत्तजकको िकिालालाई त्र्स्तो धनमाल िए हफताय गन यु पनेछ र\nनिएमा त्र्स्तो धनमाल बापतको मनामसब िमतपूमत य मतन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२१०", "title": "िदम्र्ादाः र्स पररच्छेद अन्तगतय को कसूर िएको थािा िएको िा बेपिा पाररएको व्र्त्ति", "content": "सािजय मनक िएको िा गररएको मममतले छ महिना नाघेपमछ उजरु लागने छैन।\nतर उजरु गन य सहकने पररत्तस्थमत निएको कारण िुलाई अदालतको अनमु मत मलई\nप्रमाण सहित उजरु गरेमा जहिलेसकु ै उजरु लागनेछ।\nपररच्छेद-१७\nअपिरण िा शरीर बन्धक सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२११", "title": "अपिरण गन य निनु ेाः (१) कसैले कुनै व्र्त्तिलाई अपिरण गन य िा गराउन िाँदु ैन।", "content": "(२) उपदफा (१) को प्रर्ोजनको लामग कसैले देिार्को कुनै काम गरेमा मनजले\nअपिरण गरेको मामननेछाः-\n(क) कुनै व्र्त्तिलाई बल प्रर्ोग गरी िा सो प्रर्ोग गने धम्की ठदई,\nछलकपट गरी िा डररासमा पारी, जोर जलु मु गरी, िातिमतर्ार\nदेिाई िा नदेिाई िा झक्ु र्ानमा पारी िा नशाल ु पदाथ य िा मादक\nपदाथ य सेिन गराई िा कुनै व्र्त्ति र्ारा गरी रिेको सिारी साधन\nकुनै हकमसमले कब्जा िा मनर्न्रणमा मलई िा त्र्स उपर कुनै\nहकमसमले मनर्न्रण गरी मनजलाई कुनै ठाउाँमा लगेमा िा जान\nबाध्र् गराएमा िा,\n(ि) कुनै व्र्त्तिलाई मनजको मञ् जरु ी हिना िा बालबामलका िा\nशारीररक अशिताको कारणले अरुको आश्रर्मा बसेको िा\nमानमसक अस्िस्थताको कारणले िोस ठेगानमा नरिेको व्र्त्तिलाई\nमनजको बाब ु आमा िा संरिकको मञ् जरु ी हिना िा झक्ु र्ानमा\nपारी जिजस्य ती कुनै ठाउाँमा लगेमा।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२१२", "title": "शरीर बन्धक मलन निनु ेाः (१) कसैले कसैको शरीर बन्धक मलन िाँदु ैन।", "content": "(२) उपदफा (१) को प्रर्ोजनको लामग कसैले कुनै व्र्त्तिलाई मनजको मञ् जरु ी\nहिना िा बालबामलका र िोस ठेगान निएको व्र्त्ति िए मनजको आमा बाब ु िा\n82\nwww.lawcommission.gov.np\nसंरिकको मञ् जरु ी हिना बल प्रर्ोग गरी िा सोको धम्की ठदई, डर रास देिाई, जोर\nजलु मु गरी, िातिमतर्ार देिाई िा नदेिाई छलकपट गरी, झक्ु र्ानमा पारी, नशाल ु िा\nमादक पदाथ य सेिन गराई, र्ातार्ातको साधन िा रिे बसेको ठाउाँ कब्जा गरी िा\nमनर्न्रणमा मलई थनु ामा िा मनर्न्रणमा रािेमा शरीर बन्धक मलएको मामननेछ।\n(३) उपदफा (२) मा जनु सकु ै कुरा लेत्तिएको िए तापमन मानमसक रुपमा\nअस्िस्थ व्र्त्तिलाई मनजको बाब,ु आमा िा संरिकको मञ् जरु ी मलई असल मनर्तबाट\nसम्बत्तन्धत व्र्त्तिको हितको लामग उपचार गने क्रममा िा अन्र् कुनै प्रर्ोजनका लामग\nकसैको मनगरानी िा मनर्न्रणमा रात्तिएकोमा शरीर बन्धक मलएको मामनने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२१३", "title": "अपिरण िा शरीर बन्धक मलएमा िनु े सजार्ाः कसैले ज्र्ान मलने, कुटहपट गरी चोट", "content": "पर्ु ायउने, जिजस्य ती करणी िा अप्राकृ मतक मैथनु गने, मामनस मबक्री गने िा दास बनाउने\nिा इच्छा हिरुद्ध जिजस्य ती काममा लगाउने, िेश्र्ाित्तृिमा लगाउने, र्ातना ठदने, कुनै काम\nगन य िा गराउन बाध्र् गराउने, मत्तुि रकम मलने िा प्रचमलत कानून बमोत्तजम कसूर िनु े\nअन्र् कुनै काम गन य लगाउन े उद्देश्र्ले दफा २११ िा २१२ बमोत्तजमको काम गरे िा\nगराएको िए सात िषदय ेत्ति दश िषसय म्म कै द र सिरी िजारदेत्ति एक लाि रुपैर्ासाँ म्म\nजररबाना र त्र्स बािेक अन्र् उद्देश्र्ले गरे िा गराएको िए तीन िषदय ेत्ति पााँच िषसय म्म\nकै द र तीस िजारदेत्ति पचास िजार रुपैर्ा ाँ सम्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२१४", "title": "थप सजार् िनु ेाः (१) दफा २११ बमोत्तजम अपिरण गरी दफा २१२ बमोत्तजम शरीर", "content": "बन्धक मलने व्र्त्तिलाई दश िषदय ेत्ति पन्र िषसय म्म कै द र एक लािदेत्ति एक लाि\nपचास िजार रुपैर्ााँसम्म जररबाना िनु ेछ।\n(२) कसैले अपिरण गरी िा शरीर बन्धक मलई र्स संहिता िा कानून बमोत्तजम\nकसूर मामनने अन्र् कुनै काम गरेको रिेछ िने मनजलाई त्र्स्तो कसूर बापतको सजार्मा\nउपदफा (१) बमोत्तजमको सजार् थप िनु ेछ।\n(३) दफा २११ र २१२ को कसूर सङ्गठठत रुपमा गरे गराएको रिेछ िने\nत्र्स्तो गराउने व्र्त्तिलाई थप दईु िष य कै द सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२१५", "title": "दरुु त्सािन ठदने िा आदेश ठदने िा उद्योग गने िा षडर्न्र गने व्र्त्ति िा ममतर्ारलाई", "content": "सजार् िनु ेाः (१) र्स पररच्छेदमा लेत्तिएको कसूर गन य दरुु त्सािन ठदने िा आदेश ठदने\nव्र्त्तिलाई मख्ु र् कसूरदारलाई िए सरि सजार् िनु ेछ।\n(२) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापमन सो कुराको उद्योग िा\nषड् र्न्र गने िा ममतर्ार िनु े व्र्त्तिलाई सो कसूरमा िनु े सजार्को आधा सजार्\nिनु ेछ।\n83\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२१६", "title": "आत्मसमपणय गरेमा सजार् कम िनु ेाः र्स पररच्छेद अन्तगतय को कसूर गने व्र्त्तिले कसूर", "content": "गदाय गदैको बित सरु िाकमी समि आत्मसमपणय गरेमा िा अन्र् कसूरदार िा सो कसूर\nगने मगरोिका सदस्र्लाई पक्राउ गन य सिर्ोग प¥ुर्ाएमा अिस्था िेरी अदालतले मनजलाई\nसजार् कम गन य सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२१७", "title": "िमतपूमत य िराई ठदन ु पनेाः (१) र्स पररच्छेद अन्तगतय को कसूर गरे िा गराएको ठिरेमा", "content": "कसूर गने िा गराउने व्र्त्तिबाट पीमडत व्र्त्तिलाई मनामसब िमतपूमत य िराई ठदन ु\nपनेछ।\n(२) उपदफा (१) बमोत्तजमको िमतपूमत य पीमडत व्र्त्ति मरी सके को िए मनजको\nनत्तजकको िकदारलाई िराई ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२१८", "title": "िदम्र्ादाः (१) र्स पररच्छेद अन्तगतय का कुनै कसूर गरी कसैको ज्र्ान मलएकोमा जहिले", "content": "सकु ै पमन उजरु गन य सहकने छ।\n(२) उपदफा (१) मा लेत्तिए बािेक र्स पररच्छेद अन्तगतय को कुनै कसूर िए\nगरेको मममतले दईु िष य र दफा २११ र २१२ अन्तगतय को कसूर िएकोमा सम्बत्तन्धत\nव्र्त्ति त्र्स्तो कसूरबाट मिु िएको मममतले छ महिना नाघेपमछ उजरु लागने छैन।\nपररच्छेद-१८\nकरणी सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२१९", "title": "जिजस्य ती करणी गन य निनु ेाः (१) कसैले जिजस्य ती करणी गन य िाँदु ैन।", "content": "(२) कसैले कुनै महिलालाई मनजको मञ् जरु ी नमलई करणी गरेमा िा मञ् जरु ी\nमलएर िए पमन अठार िषिय न्दा कम उमेरको कुनै बामलकालाई करणी गरेमा मनजले\nत्र्स्तो महिला िा बामलकालाई जिजस्य ती करणी गरेको मामननेछ।\nस्पष्‍ट टीकरणाः र्स पररच्छेदको प्रर्ोजनको लामगाः\n(क) करकाप, अनत्तुचत प्रिाि, डर, रास, झक्ु र्ानमा पारी िा अपिरण\nगरी िा शरीर बन्धक मलई मलएको मञ् जरु ीलाई मञ् जरु ी मामनने\nछैन,\n(ि) िोस ठेगानमा नरिेको अिस्थामा मलएको मञ् जरु ीलाई मञ् जरु ी\nमामनने छैन,\n(ग) गदु द्वार िा मिु मा मलङ्ग पसाएमा, गदु द्वार, मिु िा र्ोनीमा मलङ्ग\nके िी मार पसेको िएमा, मलङ्ग बािेक अन्र् कुनै िस्त ु र्ोनीमा\nप्रिेश गराएमा पमन जिजस्य ती करणी गरेको मामननेछ।\n84\nwww.lawcommission.gov.np\n(३) जिजस्य ती करणी गने व्र्त्तिलाई त्र्सरी करणी गदायको पररत्तस्थमत र\nमहिलाको उमेर िेरी देिार् बमोत्तजम कै द िनु ेछाः-\n\n(क) दश िषिय न्दा कम उमेरकी बामलका, पूण य अशि, अपाङ्गता िएका\nिा सिरी िषिय न्दा बढी उमेरका महिला िए जन्म कै द\n(ि) दश िष य िा दश िषिय न्दा बढी चौध िषिय न्दा कम उमेरकी\nबामलका िए अठार िषदय ेत्ति बीस िषसय म्म,\n(ग) चौध िष य िा चौध िषिय न्दा बढी सोह्र िषिय न्दा कम उमेरकी\nबामलका िए बाह्र िषदय ेत्ति चौध िषसय म्म,\n(घ) सोह्र िष य िा सोह्र िषिय न्दा बढी अठार िषिय न्दा कम उमेरकी\nमहिला िए दश िषदय ेत्ति बाह्र िषसय म्म,\n(ङ) अठार िष य िा अठार िषिय न्दा बढी उमेरकी महिला िए सात\nिषदय ेत्ति दश िषसय म्म।\n\n(३क) जिजस्य ती करणी गने व्र्त्तिलाई उपदफा (३) बमोत्तजमको कै द सजार्को\nअमतररि देिार् बमोत्तजमको जररबाना समेत िनु ेछ र त्र्स्तो जररबाना बापत प्राप्त सब ै\nरकम प्रचमलत कानून बमोत्तजम स्थापना िएको पीमडत राित कोषमा जम्मा गररनेछ:-\n(क) उपदफा (३) को िण्ड (क) िा (ि) बमोत्तजम कै द सजार् िनु े\nकसूरदारलाई सात लाि रुपैर्ााँ जररबाना,\n(ि) उपदफा (३) को िण्ड (ग) िा (घ) बमोत्तजम कै द सजार् िनु े\nकसूरदारलाई पााँच लाि रुपैर्ााँ जररबाना,\n(ग) उपदफा (३) को िण्ड (ङ) बमोत्तजम कै द सजार् िनु े\nकसूरदारलाई तीन लाि रुपैर्ााँ जररबाना।\n(४) उपदफा (३) मा जनु सकु ै कुरा लेत्तिएको िए तापमन बैबाहिक सम्बन्ध\nकार्म रिेको अिस्थामा पमतले पत्नीलाई जिरजस्ती करणी गरेमा पााँच िष य सम्म कै द\nिनु ेछ।\nतर देिार्को अिस्थालाई िैिाहिक सम्बन्ध कार्म रिेको मामनने छैनाः-\n(क) पमतसाँग मानो छुहट्टई अंश मद्दु ा चलेको,\n(ि) पमतसाँग अङ्क्श मलई छुट्टै बसेको,\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n र्ौन हिंसा हिरुद्धका के िी ऐनलाई संशोधन गन य बनेको ऐन, २०७९ द्वारा थप।\n85\nwww.lawcommission.gov.np\n(ग) पमतसाँग सम्बन्ध हिच्छेद मद्दु ा चलेको।\n(५) उपदफा (४) बमोत्तजमको अिस्थामा पीमडतको मनिेदन माग बमोत्तजम\nआिश्र्क िएमा अदालतले पमतको नाममा देिार् बमोत्तजमको आदेश जारी गन य सक्नेछाः-\n(क) पत्नीलाई मनज बसी आएको घरमा नै बसोबास गन य ठदन, पत्नीलाई\nिान लाउन ठदन, कुटहपट नगन य तथा त्तशष्ट र सभ्र् व्र्ििार गन य\nलगाउन,\n(ि) पत्नीलाई आिश्र्क उपचार गराउन िा उपचारका लामग उपर्िु\nरकम ठदन लगाउन,\n(ग) दिु ैलाई एकै ठाउाँमा बसोबास गन य उपर्िु िनु े नदेत्तिएमा\nपमतलाई अलग बस्ने व्र्िस्था गन य तथा त्र्सरी अलग बस्दा\nपत्नीको िरणपोषणको लामग आिश्र्क व्र्िस्था गन य लगाउन,\n(घ) पत्नीलाई कुनै प्रकारले दाःु ि ठदने िा सताउने कार् य नगन य र\nपत्नीको हित र सरु िाको मनममि आिश्र्क र उपर्िु कुरा गन य\nगराउन।\n(६) उपदफा (३) मा जनु सकु ै कुरा लेत्तिएको िए तापमन आफू लाई मानिरोग\n\nप्रमतरोधक िमता ह्रास गने त्तजिाण ु (एच.आई.िी.पोत्तजहटि) िा सरुिा र्ौनरोग\n(सेक्सअु ली रान्सममटेड मडत्तजज) िएको थािा पाउाँदा पाउाँदै कसैले जिजस्य ती करणी\nगरेको रिेछ िने त्र्स्तो कसूरदारलाई उपदफा (३) मा लेत्तिएको सजार्मा देिार्\nबमोत्तजमको थप सजार् समेत िनु ेछाः-\n\n(क) मानिरोग प्रमतरोधक िमता ह्रास गने त्तजिाण ु (एच.आई.िी.\nपोत्तजहटि) िएको थािा पाउाँदा पाउाँदै जिजस्य ती करणी िएको िए\nदफा १०५ बमोत्तजमको सजार्,\n(ि) अन्र् सरुिा र्ौनरोग (सेक्सअु ली रान्सममटेड मडत्तजज) िएको थािा\nपाउाँदा पाउाँदै जिजस्य ती करणी िएको िए तीन िषसय म्म कै द र\nतीस िजार रुपैर्ााँसम्म जररबाना।\n(७) सामूहिक रुपमा जिजस्य ती करणी गरेमा िा छ महिनािन्दा बढीको गििय ती,\nअशि िा अपाङ्ग िा शारीररक िा मानमसक रुपमा अस्िस्थ महिलालाई िा िातिमतर्ार\n र्ौन हिंसा हिरुद्धका के िी ऐनलाई संशोधन गन य बनेको ऐन, २०७९ द्वारा संशोमधत।\n86\nwww.lawcommission.gov.np\nदेिाई जिजस्य ती करणी गरेमा उपदफा (३) मा लेत्तिएको सजार्मा थप पााँच िषसय म्म\nकै द सजार् िनु ेछ।\n\nतर पूण य अशि अपाङ्गता िएकी महिला िएमा उपदफा (३) को िण्ड (क)\nबमोत्तजमको सजार् िनु ेछ।\n(८) कसैले िाडनाताकी महिलालाई जिजस्य ती करणी गरेकोमा मनजलाई िाडनाता\nकरणीमा सजार् िनु े रिेछ िने र्स पररच्छेद बमोत्तजमको सजार्मा िाडनाताको करणीमा\nिनु े सजार् समेत थप िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२२०", "title": "िाडनातामा करणी गन य निनु ेाः (१) कसैले आफ्नो जात िा कुलमा चली आएको चलन,", "content": "परम्परा िा मान्र्ता अनसु ार हििाि गन य निनु े नाताको व्र्त्ति िो िन् ने जानीजानी त्र्स्तो\nव्र्त्तिसाँग करणी मलन ु ठदन ु िाँदु ैन।\n(२) देिार्का नातामा उपदफा (१) बमोत्तजमको कसूर गनेलाई देिार् बमोत्तजम\nसजार् िनु ेछाः-\n(क) जन्माउने आमा छोराको िा बाब ु छोरीको करणी िएमा जन्मकै द,\n(ि) सौतेनी आमा छोरा िा बाब ु छोरी, सिोदर ठददी िाइ िा दाज ु\nबहिनी, एकै िााँगाको ससरु ा बिु ारी, एकै िााँगाको बाजे नामतनी िा\nपनामतनी, एकै िााँगाका जेठाज ु र िाइ बिु ारी िा देिर िाउजूको\nकरणी िएमा चार िषदय ेत्ति दश िषसय म्म कै द र चालीस िजार\nरुपैर्ााँदेत्ति एक लाि रुपैर्ााँसम्म जररबाना,\n(ग) एकै िााँगाको तीन पस्ु तासम्मको बज्र्ै, नामत िा पनामत, एकै\nिााँगाको ठूलो बाब ु िा काका िमतजी, एकै िााँगाको िमतजो ठूली\nआमा िा काकी, एकै िााँगाको ससरु ो िमतजी बिु ारी, साख्र्ै मामा\nिाञ्जी िा िामनज माइज,ु आमा तफय का ठूली आमा िा सानी आमा\nर छोरा र आफ्नी श्रीमती तफय की सासू र ज्िााँइको करणी िएमा\nतीन िषदय ेत्ति छ िषसय म्म कै द र तीस िजार रुपैर्ााँदेत्ति साठी\nिजार रुपैर्ासाँ म्म जररबाना,\n(घ) िण्ड (क), (ि) िा (ग) मा लेत्तिएदेत्ति बािेक आफ्नो िंशका\nसात पस्ु तासम्मका अन्र् नातामा करणी िएमा िााँगो, नाता र पस्ु ता\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा थप।\n87\nwww.lawcommission.gov.np\nसमेत हिचार गरी एक िषदय ेत्ति तीन िषसय म्म कै द र दश िजार\nरुपैर्ााँदेत्ति तीस िजार रुपैर्ासाँ म्म जररबाना।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२२१", "title": "थनु ामा रिेको व्र्त्तिसगाँ करणी गन य निनु ेाः (१) कै द िा थनु ामा रिेको कुनै व्र्त्तिसाँग", "content": "सरकारी कमचय ारीले करणी गन य िा करणी गन य अरु कसैलाई संर्ोग पारी ममलाई ठदई\nकरणी गराउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजम करणी गने िा गराउने व्र्त्तिलाई तीन िषसय म्म कै द\nसजार् िनु ेछ र त्र्स्तो करणी र्स संहिता िा अन्र् कानून अनसु ार पमन कसूर िनु े रिेछ\nिने सो बमोत्तजमको सजार्मा र्स दफा बमोत्तजमको सजार् थप िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२२२", "title": "आफ्नो संरिण िा सरु िामा रिेको व्र्त्तिसाँग करणी गन य निनु ेाः (१) कसैले आफू ले", "content": "संरिण िा सरु िा ठदएको िा आफ्नो िेरहिचारमा रिेको कुनै व्र्त्तिसाँग करणी गन य िा\nकरणी गन य अरुलाई सिर्ोग गन य िा िोस ठेगानमा नरिेको िा शारीररक िा मानमसक\nरोग लागी उपचार िा पनु स्र्थापना गने कुनै संस्थामा रात्तिएको कुनै व्र्त्तिसाँग त्र्स्तो\nसंस्थाका पदामधकारी िा कमचय ारीले करणी गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई तीन िषसय म्म कै द िनु ेछ र\nत्र्स्तो करणी र्स संहिता िा अन्र् कानून अनसु ार पमन कसूर िनु े रिेछ िने सो बमोत्तजम\nिनु े सजार्मा र्स दफाको सजार् थप िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२२३", "title": "कार्ालय र् िा पेशागत सेिा प्राप्त गने व्र्त्तिसगाँ करणी गन य निनु ेाः (१) सरकारी िा मनजी", "content": "कार्ायलर्मा कार्रय त िा कुनै पेशागत सेिा िा व्र्ािसाहर्क कामको लामग सम्पकयमा\nआएको िा रिेको कुनै व्र्त्तिसाँग त्र्स्तो कार्ायलर्मा काम गने कमचय ारी िा त्र्स्तो सेिा\nउपलब्ध गराउने व्र्त्तिले कार्ायलर्को काम गदा य िा त्र्स्तो सेिा उपलब्ध गराउाँदा िा\nगराउने स्थानमा करणी गन य िा करणी गन य अरुलाई सिर्ोग गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई चार िषसय म्म कै द र\nचालीस िजार रुपैर्ााँसम्म जररबाना िनु ेछ र त्र्स्तो करणी र्स संहिता िा अन्र् कानून\nअनसु ार पमन कसूर िनु े रिेछ िने सो बमोत्तजम िनु े सजार्मा र्स दफाको सजार् थप\nिनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२२४", "title": "र्ौन दव्र्ु र्ििार गन य निनु ेाः (१) कसैले कसैलाई र्ौन दव्र्ु र्ििार गन य िा गराउन ु िाँदु ैन।", "content": "(२) कसैले आफ्नो पमत िा पत्नी बािेक अन्र् व्र्त्तिलाई मनजको मञ् जरु ी हिना\nकरणीका आशर्ले समातेमा िा मनजको संिेदनशील अङ्ग छोएमा िा छुन प्रर्ास गरेमा,\nमनजको मिरी पोशाक िोलेमा िा िोल्ने प्रर्ास गरेमा, मनजले लगाउने मिरी पोशाक\nलगाउन िा फुकाल्न कुनै हकमसमले बाधा अिरोध गरेमा िा मनजलाई अस्िािाहिक रुपमा\n88\nwww.lawcommission.gov.np\nकुनै एकान्त ठाउाँमा लगेमा, र्ौन सम्बन्धी आफ्नो अङ्ग मनजलाई छुन, समाउन लगाएमा,\nमनजसाँग अत्तश् लल िा अन्र् त्र्स्तै प्रकारको शब्द मौत्तिक, मलत्तित िा साङ्केमतक रुपमा िा\nहिद्यतु ीर् माध्र्मबाट प्रर्ोग गरेमा, अत्तश्ल ल त्तचर िा तस्िीर देिाएमा, र्ौनका आशर्ले\nत्तजस्क्र्ाएमा िा िैरानी ठदएमा िा मनजसाँग अस्िािाहिक, अिात्तञ्छत िा अमर्ायठदत व्र्ििार\nगरेमा मनजले र्ौन दव्र्ु र्ििार गरेको मामननेछ।\n(३) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई तीन िषसय म्म कै द र तीस\nिजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२२५", "title": "बालर्ौन दरुु पर्ोग गन य निनु ेाः (१) कसैले बालर्ौन दरुु पर्ोग गन य िा गराउन िाँदु ैन।", "content": "(२) कसैले करणीका आशर्ले बालबामलकालाई अस्िािाहिक रुपमा एकान्तमा\nलगेमा, र्ौन सम्बन्धी मनजको अङ्ग छोएमा िा समातेमा, र्ौन सम्बन्धी आफ्नो अङ्ग\nमनजलाई छुन िा समाउन लगाएमा िा मनजसगाँ अन्र् कुनै हकमसमको र्ौनजन्र्\nअस्िािाहिक व्र्ििार गरेमा बालर्ौन दरुु पर्ोग गरेको मामननेछ।\n(३) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई तीन िषसय म्म कै द र तीस\nिजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२२६", "title": "अप्राकृ मतक मैथनु गन य निनु ेाः (१) कसैले कसैको मञ् जरु ी हिना अप्राकृ मतक मैथनु गन यु िा", "content": "गराउन ु िाँदु ैन।\nस्पष्‍ट टीकरणाः र्स उपदफाको प्रर्ोजनको लामग बालबामलकाले ठदएको मञ् जरु ीलाई मञ् जरु ी\nमामनने छैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई तीन िषसय म्म कै द र तीस\nिजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\n(३) बालबामलका हिरुद्ध उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई दफा\n२१९ बमोत्तजम सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२२७", "title": "पश ु करणी गन य निनु ेाः (१) कसैले पमन पश ु करणी गन यु िा गराउन ु िाँदु ैन।", "content": "(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई गाईको करणी गरे िा\nगराएको िए दईु िषसय म्म कै द र बीस िजार रुपैर्ासाँ म्म जररबाना र अन्र् पश ु करणी\nगरे िा गराएको िए एक िषसय म्म कै द र दश िजार रुपैंर्ााँसम्म जररबाना िनु ेछ।\n\n२२७क. ममलापर गन य िा गराउन निनु े: (१) र्स पररच्छेद बमोत्तजम करणी सम्बन्धी कसूर\nिएपमछ पीमडत िा पीमडतको पररिारलाई कुनै प्रकारको डर, धाक, धम्की ठदई िा\n र्ौन हिंसा हिरुद्धका केिी ऐनलाई संशोधन गन य बनके ो ऐन, २०७९ द्वारा थप।\n89\nwww.lawcommission.gov.np\nकरकापमा पारी कुनै हकमसमको लेनदेन गरी िा नगरी त्र्स्तो कसूरमा उजरु ी नगन,य\nजािेरी नठदन िा अदालतमा उपत्तस्थत निनु मञ्जुर गराउन िा कसूर गने व्र्त्ति र पीमडत\nिा पीमडतको पररिारको सदस्र्बीच मेलममलाप िा ममलापर गराउन िा त्र्सको लामग\nदबाब ठदन िा प्रिािमा पान य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने गराउने व्र्त्तिलाई तीन िषसय म्म कै द\nर तीस िजार रुपैर्ााँसम्म जररबाना िनु ेछ।\n(३) उपदफा (१) बमोत्तजमको कसूर सािजय मनक पद धारण गरेको व्र्त्तिले गरे\nिा गराएमा मनजलाई उपदफा (२) बमोत्तजम िनु े सजार्मा थप छ महिना कै द सजार्\nिनु ेछ।\n(४) र्स दफामा अन्र्र जनु सकु ै कुरा लेत्तिएको िए तापमन कानून बमोत्तजम\nममतर्ार िा दरुु त्सािन मामनने कसूरमा सोिी बमोत्तजम मद्दु ा चलाई सजार् िनु ेछ।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२२८", "title": "िमतपूमत य िराई ठदन ु पनेाः दफा २२० र २२७ अन्तगतय को कसूर बािेक र्स पररच्छेद", "content": "\nबमोत्तजमको अन्र् कसूरबाट पीमडत व्र्त्तिलाई जररबानाबाट प्राप्त िनु े रकम समेत\nहिचार गरी कसूरदारलाई सजार् मनधायरण गदाय मनजबाट मनामसब िमतपूमत य िराई ठदन ु\nपनेछ र कसूरदारले जररबाना बापत पीमडत राित कोषमा बझु ाएको रकम समेत\nपीमडतलाई ठदन ु पनेछ।\n\nतर कसूरदारको कुनै सम्पत्ति निई जबरजस्ती करणीको कसूरबाट पीमडतले\nिमतपूमत य नपाउने देत्तिएमा र प्रचमलत कानून बमोत्तजमको पीमडत राित कोष स्थापना\nिइनसके को अिस्थामा अदालतले नेपाल सरकारको महिला तथा बालबामलका हिषर् िेने\nमनकार्को नाममा िमतपूमत य स्िरुप उत्तचत रकम पीमडतलाई िराइठदने गरी आदेश गन य\nसक्नेछ र त्र्सरी आदेश िएमा सो कार्ायलर्बाट िमतपूमत य बापतको रकम तत्काल\nपीमडतलाई उपलब्ध गराउन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२२९", "title": "िदम्र्ादाः (१) दफा २२० अन्तगतय को कसूरमा जहिले सकु ै पमन उजरु गन य सहकनेछ।", "content": "(२) दफा २१९, २२१, २२२, २२३, २२४, २२५ र  २२६ को उपदफा (३)\nर दफा २२७क. को उपदफा (१) अन्तगतय को कसूर बालबामलकाको हिरुद्ध िएकोमा\nत्र्स्तो बालबामलका अठार िष य पूरा िएको मममतले तीन िषमयिर, त्र्स्तो कसूर पूण य\nअशि अपाङ्गता िएका, सस्ु त मनत्तस्थमत िएका िा सिरी िषिय न्दा बढी उमेर िएका\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n र्ौन हिंसा हिरुद्धका के िी ऐनलाई संशोधन गन य बनेको ऐन, २०७९ द्वारा संशोमधत।\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा थप।\n90\nwww.lawcommission.gov.np\nव्र्त्तिका हिरुद्ध िएमा कसूर िएको मममतले तीन िषमयिर र अन्र्को िकमा त्र्स्तो\nकसूर िएको मममतले दईु िषमयिर र र्स पररच्छेद अन्तगतय को अन्र् कसूरमा त्र्स्तो\nकसूर िएको कुरा थािा पाएको मममतले तीन महिना नाघेपमछ उजरु लागने छैन।\nतर थनु ामा रिेको िा मनर्न्रणमा मलएको िा अपिरण गरेको िा शरीर बन्धक\nमलएको व्र्त्ति हिरुद्ध कसूर िएकोमा थनु ा, मनर्न्रण अपिरण िा शरीर बन्धकबाट मत्तुि\nपाएको मममतले तीन महिना नाघेपमछ उजरु लागने छैन।\nपररच्छेद-१९\nइलाज सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२३०", "title": "इजाजत प्राप्त नगरेको व्र्त्तिले इलाज गन य निनु ेाः (१) त्तचहकत्सा सम्बन्धी हिषर्मा", "content": "मनधायररत शैत्तिक र्ोगर्ता प्राप्त गरेपमछ कानून बमोत्तजम अमधकार प्राप्त अमधकारीबाट\nइलाज गनकय ो लामग इजाजत प्राप्त गरेको व्र्त्तिले बािेक कसैले कसैलाई त्तचहकत्सा सेिा\nठदन, कसैको मानि शरीरको कुनै अङ्गको त्तचरफार गन,य कुनै प्रकारको औषमध िुिाउन िा\nिान मसफाररस गन य िा अन्र् कुनै प्रकारले इलाज गन य िाँदु ैन।\n(२) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापमन लामो अनिु िबाट\nइलाज सम्बन्धमा जानकारी राख् ने व्र्त्तिले उत्तचत िोमसर्ारी अपनाई सानो मतनो रोग\nलागेको हिरामीको मानि अङ्गलाई कुनै िास प्रमतकू ल असर नपने मामलु ी प्रकृ मतको\nऔषमध िुिाउन िा सानोमतनो घाउ, िहटरा त्तचरफार गरी उपचार गनमय ा बाधा पगु ने\nछैन।\n(३) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द र तीस िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\n(४) उपदफा (१) हिपरीत िनु े गरी त्तचहकत्सा सेिा ठदाँदा, त्तचरफार गदाय िा औषमध\nिुिाउाँदा कसैको ज्र्ान मन य गएमा कसूरदारलाई जन्म कै द िनु ेछ र अङ्गिङ्ग िएमा पन्र\nिषसय म्म कै द िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२३१", "title": "बठिर्त त्तचताई इलाज गन य निनु ेाः (१) कसैले कसैको ज्र्ान माने िा अङ्गिङ्ग गने मनर्तले", "content": "उपचार गन,य एक हकमसमको इलाज गन यु पनेमा अको हकमसमको इलाज गन य िा कुनै\nऔषमध िुिाउाँदा िा िान मसफाररस गदाय कसैको ज्र्ान मन य िा अङ्गिङ्ग िनु सक्छ िन् ने\nजानीजानी िा सो थािा पाउन ु पने मनामसब कारण िई त्र्स्तो औषमध िुिाउन िा िान\nमसफाररस गन य िा त्तचरफार गन य िा मानि शरीरको कुनै एक अङ्गको त्तचरफार गन यु पनेमा\nअको अङ्ग त्तचरफार गन य िा त्र्स्तो अङ्ग बेकम्मा बनाउन िा शरीरबाट त्र्सलाई अलग\nगने काम गन य िा गराउन िाँदु ैन।\n91\nwww.lawcommission.gov.np\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई देिार्\nबमोत्तजमको सजार् िनु ेछाः–\n\n(क) कसैको ज्र्ान गएकोमा जन्मकै द,\n\n(ि) कसैको अङ्गिङ्ग िएकोमा दफा १९२ बमोत्तजमको सजार्।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२३२", "title": "लापरबािी िा िेलचेक्र्र्ाइाँ गरी इलाज गन य निनु ेाः (१) कानून बमोत्तजम इलाज गन य पाउने", "content": "व्र्त्तिले कसैको इलाज गदाय  गम्िीर लापरबािी िा िेलचेक्र्र्ाइाँ गरी इलाज गन,य औषमध\nिान ठदन िा िान मसफाररस गन य िा त्तचरफार गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कामबाट कसैको ज्र्ान मन य गएमा िा अङ्गिङ्ग\nिएमा लापरिािीपूण य काम गरेको कारणबाट ज्र्ान मरेमा िा अङ्गिङ्ग िएमा पााँच िषसय म्म\nकै द र पचास िजार रुपैर्ााँसम्म जररबाना र िेलचरm्र्ाई गरेको कारणबाट मरेकोमा िा\nअङ्गिङ्ग िएकोमा तीन िषसय म्म कै द र तीस िजार रुपैर्ााँसम्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२३३", "title": "मञ्ज रु ी हिना मानि शरीरमा परीिण गन य निनु ेाः (१) कानून बमोत्तजम इलाज गन य पाउने", "content": "व्र्त्तिले मानि शरीरमा कुनै इलाज सम्बन्धी हिमध, त्तचरफार िा औषमध परीिण गन यु पदाय\nसम्बत्तन्धत व्र्त्ति र बालबामलका िा िोस ठेगानमा निएको व्र्त्ति िए मनजको बाब ु\nआमा िा संरिकको मञ् जरु ी नमलई र त्र्स्तो व्र्त्ति िा बाब ु आमा िा संरिकलाई त्र्स\nकुराको जानकारी नठदई त्र्स्तो काम गन यु िा गराउन ु िाँदु ैन।\n\nतर हिपद् िा सडक दघु टय ना िएको िा सम्बत्तन्धत व्र्त्तिको बाब,ु आमा िा\nसंरिकको तत्काल मञ् जरु ी मलन नसहकने िा सो कुराको जानकारी ठदन नसहकने\nअिस्थामा त्र्स्तो व्र्त्तिको ज्र्ान जोगाउनको लामग तत्काल उपचार िा अङ्ग त्तचरफार\nगन य कुनै बाधा पने छैन।\n(२) उपदफा (१) बमोत्तजम परीिण गदा य त्र्स्तो हिमध, त्तचरफार िा औषमधको\nमानि शरीरमा िनु सक्ने असर समेतलाई हिचार गरी िोमसर्ारी पूिकय गन यु पनेछ।\n(३) कसैले अनत्तुचत आमथकय लाि मलने िा महिलाको गोपमनर्ता िङ्ग गने िा\nअन्र् कुनै मनर्तले कसैको शारीररक परीिण गन यु िा अङ्ग पररितनय गन यु िा गराउन ु\nिाँदु ैन।\n(४) उपदफा (१), (२) िा (३) हिपरीत परीिण गने, गराउने व्र्त्तिलाई तीन\nिषसय म्म कै द र तीस िजार रुपैर्ााँसम्म जररबाना िनु ेछ।\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा थप।\n92\nwww.lawcommission.gov.np\n(५) उपदफा (१), (२) िा (३) बमोत्तजमको कसूर गरेको कारणबाट कसैको\nज्र्ान मरेकोमा ज्र्ान मारे सरि र अङ्गिङ्ग िएकोमा अङ्गिङ्ग गरे सरि सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२३४", "title": "जोत्तिमपणू य औषमध मबक्री हितरण गन य निनु ेाः (१) कानून बमोत्तजम औषमध मबक्री हितरण", "content": "गन य पाउने व्र्त्तिले इलाज गन य पाउने इजाजत प्राप्त व्र्त्तिको मसफाररस हिना कसैलाई\nमानि शरीरमा गम्िीर असर िनु े कुनै लागू औषध, हिषादी िा जोत्तिमपूण य औषमध मबक्री\nहितरण गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई दईु िषसय म्म\nकै द िा बीस िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२३५", "title": "औषमधमा ममसािट गन य िा ममसािट गरेको औषमध मबक्री गन य निनु ेाः (१) कसैले जानीजानी", "content": "औषमधको असर शन्ु र् िा घटी िा बदमलने िा िामनकारक िनु े गरी कुनै औषमधमा\nममसािट गन य िा त्र्सरी ममसािट िएको औषमध िा अन्र् कुनै बस्तलु ाई औषमध िनी\nमबक्री गन य िा उपचारको मनममि कसैलाई ठदन िा कुनै व्र्त्तिलाई त्र्स्तो औषमध सेिन\nगन य िा गराउन लगाउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई देिार् बमोत्तजम सजार्\nिनु ेछाः-\n(क) त्र्स्तो औषमध सेिन गरेको कारणले ज्र्ान मररसके कोमा ज्र्ान\nमारेको सरि,\n(ि) त्र्स्तो औषमध सेिन गरेको कारणले ज्र्ान मन य सक्ने गरी ितरा\nपगु ेको िा पगु ने सम्िािना िएकोमा ज्र्ान माने उद्योग गरे सरि,\n(ग) त्र्स्तो औषमध सेिन गरेको कारणले शरीरको कुनै अङ्गिङ्ग िनु े िा\nसोको शत्ति िीण िा िरण िनु सक्ने िएमा दश िषसय म्म कै द र\nएक लाि रुपैर्ासाँ म्म जररबाना,\n(घ) िण्ड (क), (ि) िा (ग) को अिस्थामा बािेक अन्र् अिस्थामा\nपााँच िषसय म्म कै द र पचास िजार रुपैर्ााँसम्म जररबाना।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२३६", "title": "म्र्ाद नाघेको िा पूि य सािधानी नमलई औषमध मबक्री, हितरण गन य निनु ेाः (१) कसैले कुनै", "content": "मनत्तित समर्ािमधमिर प्रर्ोग गररसक्न ु पने औषमध सो म्र्ाद नाघेपमछ मबक्री गन य िा कुनै\nऔषमध मबक्री हितरण गदाय कुनै िास पूि य सािधानी मलन ु पनेमा त्र्स्तो नमलई मबक्री\nहितरण गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक िषसय म्म\nकै द र दश िजार रुपैर्ााँसम्म जररबाना िनु ेछ।\n93\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२३७", "title": "एक औषमधलाई अको औषमध िनी मबक्री हितरण गन य निनु ेाः (१) कानून बमोत्तजम औषमध", "content": "मबक्री गन य पाउने व्र्त्तिले औषमध मबक्री हितरण गदाय एक हकमसमको औषमधलाई\nतात्तत्िक रुपमा मिन् न अको हकमसमको औषमध िो िन् ने जानीजानी िा थािा पाउाँन ु पने\nमनामसब कारण िई मबक्री हितरण गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई दईु िषसय म्म\nकै द िा बीस िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२३८", "title": "झठ्ठु ा प्रमतिदे न ठदन निनु ेाः (१) कानून बमोत्तजम मानि रगत, मूर िा िकार आठद", "content": "प्रर्ोगशाला परीिण (प्र्ाथोलोत्तजकल टेष्‍ट ट) गन य इजाजतपर प्राप्त व्र्त्तिले त्र्सरी परीिण\nगदाय झठ्ठु ा िा गलत प्रमतिेदन ठदन िा परीिणबाट प्राप्त तथ्र्िन्दा फरक तथ्र् उल्लेि\nगरी प्रमतिेदन ठदन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द र तीस िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\n(३) उपदफा (१) बमोत्तजमको प्रमतिेदनको आधारमा कसैलाई औषमध मसफाररस\nगरी सेिन गदाय, त्तचरफार गदा य िा उपचार गदा य कसैको ज्र्ान मरेमा िा अङ्गिङ्ग िएमा\nत्र्स्तो प्रमतिेदन ठदने व्र्त्ति कसूरदार मामननेछ।\n(४) उपदफा (३) बमोत्तजम कसूर गने िा गराउने व्र्त्तिलाई ज्र्ान मररसके को\nिए ज्र्ान मारे सरि र अङ्गिङ्ग िएको िए अङ्गिङ्ग गरे सरि सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२३९", "title": "िमतपूमत य िराई ठदन ु पनेाः र्स पररच्छेद बमोत्तजमको कसूर गरेको कारणबाट कसैको ज्र्ान", "content": "मरेमा िा अङ्गिङ्ग िएमा िा अन्र् िामन, नोक्सानी िा िमत पगु ेकोमा कसूरदारबाट\nसम्बत्तन्धत पीमडतलाई र पीमडतको मत्ृ र् ु िएकोमा मनजको िकिालालाई मनामसब िमतपूमत य\nिराई ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२४०", "title": "िदम्र्ादाः (१) दफा २३० को उपदफा (४), २३१, २३२, २३३ को उपदफा (४),", "content": "\n२३५ र २३८ को उपदफा (४) बमोत्तजमको कामबाट ज्र्ान मरेकोमा दफा १८७\nको उपदफा (१) मा उत्तल्लत्तित िदम्र्ाद लागनेछ।\n(२) दफा २३० को उपदफा (१) अन्तगतय को कसूरमा त्र्स्तो कसूर िएको\nकुरा थािा पाएको मममतले एक िष य र र्स पररच्छेद अन्तगतय को अन्र् कसूरको िकमा\nत्र्स्तो कसूर िए गरेको मममतले छ महिना नाघेपमछ उजरु लागने छैन।\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n94\nwww.lawcommission.gov.np\nपररच्छेद-२०\nचोरी तथा डाकाँ ा सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२४१", "title": "चोरी गन य निनु ेाः (१) कसैले चोरी गन य िा गराउन िाँदु ैन।", "content": "(२) उपदफा (१) को प्रर्ोजनको लामग कसैले अन्र् व्र्त्तिको स्िाममत्ि, कब्जा,\nमनर्न्रण िा त्तजम्मामा रिेको चल सम्पत्ति आफ्नो बनाउने, उपिोग गने िा मलन िानका\nलामग त्र्स्तो व्र्त्तिको मञ् जरु ी हिना बेइमानीका मनर्तले मलएमा िा स्थान पररितनय\nगरेमा मनजले चोरी गरेको मामननेछ।\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनका लामग-\n(क) “मञ्ज रु ी” िन् नाले मलत्तित िा मौत्तिक रुपमा ठदइएको िा\nआचरणद्वारा व्र्ि िएको मञ् जरु ी सम्झन ु पछ।य\n(ि) अठार िष य नपगु ेका बालबामलकाको िा िोस ठेगानमा निएको\nव्र्त्तिको मञ् जरु ीलाई मञ् जरु ी मामनने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२४२", "title": "चोरी गरेमा िनु े सजार्ाः (१) देिार् बमोत्तजमको अिस्थामा चोरी गने िा गराउने", "content": "व्र्त्तिलाई दईु िषदय ेत्ति सात िषसय म्म कै द र बीस िजार रुपैर्ााँदेत्ति सिरी िजार\nरुपैर्ााँसम्म जररबाना िनु ेछाः-\n(क) कुनै सरकारी िा सािजय मनक सम्पत्ति िा कुनै धाममकय स्थान िा\nदेिालर्को सम्पत्ति चोरी गरेमा,\n(ि) कुनै व्र्त्तिलाई मादक पदाथ य िुिाई िा लागू पदाथ य सेिन गराई\nिा अरु हकमसमले िेिोस गराई कुनै सम्पत्ति चोरी गरेमा,\n(ग) िकू म्प, आगलागी, बाढी, िूलदङ्गा िा र्स्तै प्रकृ मतको अरु कुनै\nसङ्कटापन् न त्तस्थमत िा कुनै दघु टय नाको मौका छोपी कुनै सम्पत्ति\nचोरी गरेमा,\n(घ) आफू जनु कार्ायलर् िा व्र्त्तिको सेिामा रिेको छ त्र्स्तो\nकार्ायलर् िा व्र्त्तिको सम्पत्ति चोरी गरेमा,\n(ङ) मामनस िा िस्त ु पररििनको लामग उपर्ोग िएको कुनै सिारीमा\nचोरी गरेमा।\n(२) उपदफा (१) मा लेत्तिएदेत्ति बािेक अन्र् अिस्थामा चोरी गने िा गराउने\nव्र्त्तिलाई तीन िषसय म्म कै द र तीस िजार रुपैर्ाााँसम्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२४३", "title": "नकिजनी चोरी गन य निनु ेाः (१) कसैले नकिजनी चोरी गन य िा गराउन िाँदु ैन।", "content": "95\nwww.lawcommission.gov.np\n(२) उपदफा (१) को प्रर्ोजनको लामग कुनै घरमा सो घरको मूल ढोका फोरी\nिा मूल ढोका बािेक अन्र् कुनै बाटो, स्थान िा तररका िा साधनबाट प्रिेश गरी चोरी\nगरेमा िा चोरी गररसके पमछ मूल ढोका फोरी िा मूल ढोका बािेक अन्र् कुनै बाटो,\nस्थान िा तररका िा साधनबाट बाहिर मनस्के मा िा मनस्कने उद्योग गरेमा मनजले\nनकिजनी चोरी गरेको मामननेछ।\n(३) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई तीन िषदय ेत्ति पााँच िषसय म्म\nकै द र तीस िजार रुपैर्ााँदेत्ति पचास िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२४४", "title": "डाकाँ ा गन य निनु ेाः (१) कसैले डााँका गन य िा गराउन िाँदु ैन।", "content": "(२) कसैले देिार् बमोत्तजमको चोरी गरेमा मनजले डााँका गरेको मामननेछाः-\n(क) चोरी गनायका लामग िा चोरी गदाय िा चोरी गरेको सम्पत्ति लैजान\nिा चोरी गरेपमछ पक्राउबाट बच्नका लामग कुनै व्र्त्तिको ज्र्ान\n\nमलएमा िा मनजलाई गम्िीर चोट पर्ु ायएमा िा बााँधछााँद िा\nथनु छेक गरेमा िा सो कुराको उद्योग गरेमा िा तत्कालै कुनै\n\nव्र्त्तिको ज्र्ान मलने िा मनजलाई गम्िीर चोट पर्ु ायउने डररास\nदेिाएमा िा जोत्तिमी िातिमतर्ार साथमा मलई चोरी गरेमा,\n(ि) तत्कालै कसैको ज्र्ान मलने िा कसैलाई चोट पर्ु ायउने िा\nमनर्न्रणमा मलने डररास देिाई िा आपरामधक लाि मलई कुनै\nरकम िा आमथकय लाि प्राप्त गरेमा,\n(ग) बाटो घाटो, एकान्त स्थल िा जङ्गलमा ढुकी डर, रास देिाई\nजोत्तिमी िातिमतर्ार प्रर्ोग गरी िा सो प्रर्ोग गने धम्की ठदई िा\nचोरी गरेमा।\n(घ) तीन जना िा तीन जनािन्दा बढीको जमात िई चोरी गरेमा।\n(३) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई देिार् बमोत्तजम सजार्\nिनु ेछाः-\n(क) उपदफा (२) को िण्ड (क) िा (ि) बमोत्तजमको कसूर िए\nसात िषदय ेत्ति चौध िषसय म्म कै द र सिरी िजार रुपैर्ादाँ ेत्ति एक\nलाि चालीस िजार रुपैर्ासाँ म्म जररबाना,\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n96\nwww.lawcommission.gov.np\n(ि) उपदफा (२) को िण्ड (ग) िा (घ) बमोत्तजमको कसूर िए पााँच\nिषदय ेत्ति दश िषसय म्म कै द र पचास िजारदेत्ति एक लाि\nरुपैर्ााँसम्म जररबाना।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२४५", "title": "चोरीमा प्रर्ोग िनु े औजार मलई हिड्न निनु ेाः (१) कसैले चोरी गने िा डााँका गने", "content": "मनर्तले चोरी िा डााँकामा प्रर्ोग िनु सक्ने औजार, मालसामान, िातिमतर्ार, नक् कली\nसााँचो, पञ्जा, िर्र र्ाङ्ग आठद साधन मलई कसैको घर पररसरमा हिड्न िा प्रिेश गन य िा प्रिेश\nगने उद्योग गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजम हिाँडने, प्रिेश गने िा प्रिेश गने उद्योग गने व्र्त्तिले\nअन्र्था प्रमात्तणत िएकोमा बािेक चोरी गने मनर्तले हिडेको, प्रिेश गरेको िा प्रिेश गन य\nउद्योग गरेको मामननेछ।\n(३) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक िषसय म्म\nकै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२४६", "title": "बगली मान य निनु ेाः (१) कसैले बगली मान य िा मान य लगाउन िाँदु ैन।", "content": "(२) उपदफा (१) को प्रर्ोजनको लामग कसैले पैदल हिाँमडरिेको, सिारी साधनमा\nर्ारा गरररिेको िा कुनै सािजय मनक स्थानमा रिेको व्र्त्तिले थािा पाउने िा नपाउने गरी\nमनजको बगली िा मनजको साथमा रिेको थैली, झोला िा अन्र् कुनै हकमसमको साधनमा\nरिेको नगद िा धनमाल मलएमा मनजले बगली मारेको मामननेछ।\nतर दश िजार रुपैर्ााँ नगद िा दश िजार रुपैर्ािाँ न्दा बढी मूल्र् िएको धनमाल\nबगली मारेको िए दफा २४१ बमोत्तजमको कसूर गरेको मामननेछ।\n(३) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई देिार् बमोत्तजमको सजार्\nिनु ेछाः\n(क) पहिलो पटक बगली मारेको िए एक महिनासम्म कै द िा हिगो\nबमोत्तजम जररबाना िा दिु ै सजार्,\n(ि) दोस्रो पटकदेत्ति पटक्कै हपच्छे दईु महिनासम्म कै द िा मबगो\nबमोत्तजम जररबाना कै द िा दिु ै सजार्।\n\n२४६क. थप सजार् गरी िमतपूमत य िराईनेाः (१) कानून बमोत्तजम आिश्र्क िस्त ु मामनने कुनै\nसरकारी, सािजय मनक िा मनजी िस्त ु िा सम्पत्ति चोरी गने िा चोरी गरी प्राप्त गरेको िस्त ु\nिा सम्पत्ति जानीजानी हकन्न े िा बेच्ने कार् य गने व्र्त्तिलाई र्स पररच्छेद बमोत्तजमको\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा थप।\n97\nwww.lawcommission.gov.np\nकसूरमा िनु े सजार्मा थप एक िष य कै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै\nसजार् िनु ेछ।\n(२) उपदफा (१) बमोत्तजमको िस्त ु िा सम्पत्तिको िामन, नोक्सानी िइसके को\nरिेछ िने त्र्सको मबगो बमोत्तजमको िमतपूमत य समेत कसूरदारबाट िराउन ु पनेछ।\n(३) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्ति र्हकन िएकोमा सोिी व्र्त्ति र\nत्र्स्तो व्र्त्ति र्हकन निएकोमा त्र्स्तो काम गन य उक्साउने िा आदेश ठदने व्र्त्तिले\nकसूर गरेको मामननेछ।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२४७", "title": "मबगो िराउन ु पनेाः (१) र्स पररच्छेद बमोत्तजमको कसूर गने कसूरदारबाट त्र्स्तो", "content": "कसूरको मबगो िएमा मबगो जफत गरी सम्पत्ति धनीलाई िराई ठदन ु पनेछ। कसूरदारले\nमबगोको सम्पत्ति मामससके को िए त्र्स्तो मबगोको मूल्र् बराबरको सम्पत्ति धनीलाई िराई\nठदन ु पनेछ।\n\n(२) उपदफा (१) बमोत्तजम मबगो िराउाँदा बरामद िई आएको मालमध्र्े\nत्तचन्िले िा प्रमाणबाट र्सको िन् ने ठिरेको जमत जसको िो उसैलाई िराई ठदई अरु धनी\nपिा नलागेको माल धरौट रािी तीन महिनाको अिमध ठदई सूचना जारी गन यु पनेछ र सो\nअिमधमा कसैले मलन आर्ो र चोरीको दरिास्तमा लेत्तिएको मालसाँग ममल्न आर्ो िने\nसम्बत्तन्धत मालधनीलाई हफताय ठदन ु पनेछ। त्र्सरी मालिस्त ु मलन आएन िा दरिास्तको\nमालमा ममलेन िने पहिले पक्री ल्र्ाउने धनीलाई साबूत िराई बढ्ता िए अरु कार्म\nगराइसके को धनीलाई दामासािीको हिसाबले िराई ठदई बढी िए मललाम गरी सरकारी\nकोषमा दात्तिला गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२४८", "title": "िदम्र्ादाः दफा २४५ र २४६ अन्तगतय को कसूरमा त्र्स्तो कसूर िए गरेको मममतले तीन", "content": "महिनामिर र र्स पररच्छेद अन्तगतय को अन्र् कसूरमा त्र्स्तो कसूर िएको कुरा थािा\nपाएको मममतले छ महिना नाघेपमछ उजरु लागने छैन।\nपररच्छेद-२१\nठगी, आपरामधक हिश्ि ासघात तथा आपरामधक लाि (एक्सटसनय ) सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२४९", "title": "ठगी गन य निनु ेाः (१) कसैले ठगी गन य िा गराउन िाँदु ैन।", "content": "(२) उपदफा (१) को प्रर्ोजनको लामग कसैले कसैलाई कुनै कुराको हिश्ि ास\nठदलाएकोमा सो बमोत्तजम नगरी िा फकाई, झक्ु र्ाई िा अन्र् कुनै हकमसमले धोका ठदई\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा थप।\n98\nwww.lawcommission.gov.np\nकुनै काम गरी िा गनबय ाट रोकी त्र्स्तो व्र्त्ति िा अन्र् कसैलाई बेइमानीपूिकय कुनै\nहकमसमको िामन, नोक्सानी िा िमत प¥ुर्ाएमा िा आफ्नो िा अरु कसैको लामग कुनै लाि\nप्राप्त गरेमा मनजले ठगी गरेको मामननेछ।\nस्पष्‍ट टीकरणाः ठगीबाट पीमडत व्र्त्तिले ठगी गने व्र्त्तिबाट कुनै मलित गराएको रिेछ\nिने त्र्स हिषर्मा मलित बमोत्तजम िनु ेछ।\n(३) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई देिार् बमोत्तजमको सजार्\nिनु ेछाः-\n(क) भ्रष्टाचार िनु ेमा बािेक नेपाल सरकार िा नेपाल सरकारको पूण य\nिा अमधकांश स्िाममत्ि िा मनर्न्रणमा िएको कुनै संस्थालाई ठगी\nगरेमा दश िषसय म्म कै द र एक लाि रुपैर्ासाँ म्म जररबाना,\n(ि) आफनो नाम, दजा,य पदिी, र्ोगर्ता ढााँटी ठगी गरेमा पााँच िषसय म्म\nकै द र पचास िजार रुपैर्ासाँ म्म जररबाना,\n(ग) िण्ड (क) िा (ि) मा लेत्तिएदेत्ति बािेक अन्र् कुनै हकमसमले\nठगी गरेमा सात िषसय म्म कै द र सिरी िजार रुपैर्ााँसम्म\nजररबाना।\n(४) बालबामलका, िोस ठेगानमा नरिेको व्र्त्ति, असिार्, मनरिर िा पचििर िष य\nमामथको व्र्त्तिलाई ठगी गरेकोमा उपदफा (३) मा लेत्तिएको सजार्मा थप एक िषसय म्म\nकै द सजार् िनु ेछ।\n\n२४९क. अनत्तुचत लेनदेन गन य निनु े: (१) कसैले अनत्तुचत लेनदेन गन य िा गराउन िाँदु ैन।\n(२) उपदफा (१) को प्रर्ोजनको लामग घरसारमा कसैले देिार्का काम गरेमा\nअनत्तुचत लेनदेन गरेको िा गराएको मामननेछाः-\n(क) लेनदेन निएको िा नगरेको रकम ठदएको िनी मलित तर्ार गने,\n(ि) लेनदेन गरेको िास्तहिक रकमिन्दा बढी रकमको मलित तर्ार\nगने,\n(ग) लेनदेन गदायकै बित ब्र्ाज रकम समेत सािााँमा जोडी मलित तर्ार\nगने,\n(घ) ब्र्ाजलाई सािााँमा जोडी नर्ााँ मलित तर्ार गने,\n(ङ) ऋणीले मतरे बझु ाएको रकमको िरपाई नठदने िा मलित नबनाउने,\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०८० द्वारा थप।\n99\nwww.lawcommission.gov.np\n(च) ऋणको सािााँिन्दा बढी ब्र्ाज मलने,\n(छ) ऋण असलु ीको लामग कुनै प्रकारको शारीररक िा मानमसक िामन िनु े\nगरी धम्की ठदने िा हिंसा िा शोषण गने, िा\n(ज) अनत्तुचत लेनदेनको आधारमा ऋणीको अचल सम्पत्तिको िक\nिस्तान्तरण गरी मलने।\n(३) र्ो दफा प्रारम्ि िनु अु त्तघ िएको लेनदेनको कारोबारको आधारमा कसैले\nउपदफा (२) बमोत्तजमको काम गन,य गराउन िा अनत्तुचत लेनदेनको रकम असलु उपर\nगन य ऋणीलाई िैरानी पर्रु र्ाउन ु िाँदु ैन।\n(४) उपदफा (१) िा (३) बमोत्तजमको कसरु गने िा गराउने व्र्त्तिलाई\nकसरु को गम्िीरता िेरी सात िषसय म्म कै द र सिरी िजार रूपैर्ााँसम्म जररबाना िनु ेछ।\n(५) अनत्तुचत लेनदेनको कसरु गने कसरु दारले त्र्स्तो लेनदेनको आधारमा\nऋणीबाट रकम िा अन्र् कुनै चल सम्पत्ति मलएको रिेछ िने कारोबार िएको िास्तहिक\nरकम र कानून बमोत्तजमको ब्र्ाज मनजलाई ठदलाई बााँकी रकम िा अन्र् चल सम्पत्ति\nसम्बत्तन्धत ऋणीलाई कसरु दारबाट िराइठदन ु पनेछ।\n(६) अनत्तुचत लेनदेनको आधारमा ऋणीको अचल सम्पत्तिको िक िस्तान्तरण\nिएको ठिर िएमा त्र्स्तो िक िस्तान्तरण बदर िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२५०", "title": "ठेक्क ा िा करारको काममा फरक पान य निनु ेाः (१) मनमायण सम्बन्धी काम िा अन्र् कुनै", "content": "काम गने त्तजम्मेिारी मलएको व्र्त्तिले िा मनजको तफय बाट काम गने कुनै व्र्त्तिले\nबेइमानीका मनर्तले मनधायररत मापदण्ड िा गणु स्तरको माल प्रर्ोग नगरी िा प्रर्ोग िनु े\nमालको पररमाण घटीबढी पारी िा अन्र् कुनै हकमसमबाट मनधायररत गणु स्तरिन्दा फरक\nपारी मनमायण कार् य िा अन्र् काम गन य िा गराउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई दश िषसय म्म कै द र एक\nलाि रुपैर्ासाँ म्म जररबाना िनु ेछ।\n(३) कुनै माल, िस्त ु िा सेिा आपूमत य गने त्तजम्मेिारी िएको व्र्त्ति िा मनजको\nतफय बाट काम गने कुनै व्र्त्तिले बेइमानीका मनर्तले कमसल िा घटी पररमाणका माल,\nिस्त ु िा सेिा आपूमत य गन य िा अन्र् कुनै हकमसमबाट तोहकएको िन्दा फरक गणु को माल,\nिस्त ु िा सेिा उपलब्ध गराउन ु िाँदु ैन।\n(४) उपदफा (३) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाईय पााँच िषसय म्म\nकै द र पचास िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\n100\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२५१", "title": "सम्पत्तिको आपरामधक उपर्ोग गन य निनु ेाः (१) कसैले सम्पत्तिको आपरामधक उपर्ोग गन य", "content": "िा गराउन िाँदु ैन।\n(२) उपदफा (१) को प्रर्ोजनका लामग कसैले देिार्को काम गरेमा मनजले\nसम्पत्तिको आपरामधक उपर्ोग गरेको मामननेछाः-\n(क) अकायको सम्पत्ति बेइमानीको मनर्तले कब्जा गरी उपर्ोग गरेमा,\nिामन, नोक्सानी िा हिनाममना गरेमा िा सम्बत्तन्धत व्र्त्तिको\nमञ् जरु ी हिना िाडामा लगाएमा िा बेचमबिन गरेमा,\nतर कुनै जगगाको िास्तहिक साँमधर्ारले िलु िस सामान्र्\nरुपमा सााँध सीमाना ममच्ने गरी कसैको सम्पत्ति उपर्ोग गरेकोमा\nर्स िण्ड बमोत्तजमको कसूर मामनने छैन।\n(ि) िेिाररसी सम्पत्ति पाउने व्र्त्तिले त्र्स्तो सम्पत्तिको धनी थािा िएर\nिा त्र्स्तो सम्पत्तिको धनी थािा िाँदु ा िाँदु ै िा थािा पाएपमछ पमन\nमनामसब समर्मिर त्र्स्तो धनीलाई त्र्स्तो सम्पत्ति हफताय नगरी\nिा सम्पत्ति हफताय मलन सूचना नठदई िा त्र्स्तो सम्पत्तिको\nधनीलाई उत्तचत म्र्ादसम्म नपिी बेइमानीपूिकय त्र्स्तो सम्पत्ति\nआफ्नो मनममि उपर्ोग गरेमा िा कुनै प्रकारले रुपान्तरण\nगरेमा।\nतर उत्तचत प्रर्ास गदाय पमन सम्पत्तिको धनी पिा नलागेमा\nिा सूचना ठदएको उत्तचत म्र्ादमिर सम्पत्ति धनी सम्पत्ति हफताय\nमलन नआएमा सम्पत्ति पाउने व्र्त्तिले सो सम्पत्ति आफ्नो मनममि\nअसल मनर्तले उपर्ोग गरेमा र्स दफा बमोत्तजमको कसूर गरेको\nमामनने छैन।\n(३) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाईय देिार् बमोत्तजम\nसजार् िनु ेछाः-\n(क) कुनै व्र्त्तिको मत्ृ र् ु िाँदु ाको बित मनजको कव्जामा रिेको\nसम्पत्ति मनजको कानून बमोत्तजमको िकिालाको कव्जामा नपदै\nत्र्स्तो सम्पत्तिको आपरामधक उपर्ोग गरेमा िा बालबामलका,\nमानमसक िा शारीररक अस्िस्थताले िोस ठेगानमा नरिेको व्र्त्ति\nिा पचििर िष य मामथका व्र्त्तिको सम्पत्तिको आपरामधक उपर्ोग\n101\nwww.lawcommission.gov.np\nगरेमा तीन िषसय म्म कै द िा तीस िजार रुपैर्ााँसम्म जररबाना िा\nदिु ै सजार्,\n(ि) िण्ड (क) मा लेत्तिएदेत्ति बािेक अन्र् अिस्थामा सम्पत्तिको\nआपरामधक उपर्ोग गरेको िए एक िषसय म्म कै द िा दश िजार\nरुपैर्ााँसम्म जररबाना िा दिु ै सजार्।\n(४) र्स दफा बमोत्तजम आपरामधक उपर्ोग गरेको सम्पत्ति हफताय गन य सहकने\nअिस्थामा रिेछ िने त्र्सरी उपर्ोग गने व्र्त्तिले त्र्स्तो सम्पत्तिको धनी िा मनजको\nमत्ृ र् ु िइसके को िए मनजको नत्तजकको िकिालालाई हफताय गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२५२", "title": "आपरामधक हिश्ि ासघात गन य निनु ेाः (१) कसैले आपरामधक हिश्ि ासघात गन य िा गराउन", "content": "िाँदु ैन।\n(२) उपदफा (१) को प्रर्ोजनको लामग कसैले देिार्को कुनै काम गरेमा मनजले\nआपरामधक हिश्ि ासघात गरे िा गराएको मामननेछाः-\n(क) आफ्नो त्तजम्मा िा संरिणमा रिेको अकायको सम्पत्ति बेइमानीपूिकय\nआफ्नो मनममि प्रर्ोग गरेमा िा कुनै प्रकारले रुपान्तरण गरेमा िा\nत्र्स्तो सम्पत्तिको उपर्ोग तत्सम्बन्धी करार िा शतनय ामा िा\nकानून हिपरीत बेइमानीपूिकय आफ्नो मनममि उपर्ोग गरेमा िा\nअरु कसैलाई उपर्ोग गन य ठदएमा िा िक टुटाई अरुलाई ठदएमा\nिा ठदलाएमा,\n(ि) अकायको कुनै काम कारोिार गने त्तजम्मा मलएको िा कानूनी\nकतव्य र् पालन गन यु पने त्तजम्मेिारी िएको व्र्त्तिले िा कुनै काम\nकारोिारका सम्बन्धमा अकायको प्रमतमनमधको रुपमा काम गने\nव्र्त्तिले आफू िा अरु कसैलाई फाइदा पर्ु ाउय नको लामग आफ्नो\nकतव्य र्को हिपरीत कुनै काम गरी त्र्स्तो व्र्त्तिलाई कुनै िामन,\nनोक्सानी िा िमत प¥ुर्ाएमा।\n(३) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई देिार्\nबमोत्तजमको सजार् िनु ेछाः-\n(क) कुनै संस्थाको व्र्िस्थापक, प्रबन्धक, कमचय ारी िा प्रमतमनमधको\nिैमसर्तले कुनै व्र्त्तिले िा कुनै सम्पत्ति एक ठाउाँबाट अको\nठाउाँमा प¥ुर्ाइठदने िा गोदाम िा अन्र् कुनै ठाउाँमा सरु त्तित साथ\nराख् ने त्तजम्मा मलएको िा त्र्स्तो गने कानूनी कतव्य र् िएको\n102\nwww.lawcommission.gov.np\nव्र्त्तिले आपरामधक हिश्ि ासघात गरेमा पााँच िषसय म्म कै द र\nपचास िजार रुपैर्ााँसम्म जररबाना,\n(ि) िण्ड (क) मा लेत्तिएदेत्ति बािेक अरु कसैले आपरामधक\nहिश्ि ासघात गरेमा तीन िषसय म्म कै द िा तीस िजार रुपैर्ााँसम्म\nजररबाना िा दिु ै सजार्।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२५३", "title": "आपरामधक लाि (एक्सटसनय ) मलन निनु ेाः (१) कसैले आपरामधक लाि (एक्सटसनय ) मलन", "content": "िा मलन लगाउन िाँदु ैन।\n(२) उपदफा (१) को प्रर्ोजनको लामग कसैले कुनै व्र्त्तिलाई मनजको िा अरु\nकसैको कुनै िमत पर्ु ायउने डर रासमा पारी मनजबाट बेइमानीपूिकय आफ्नो िा अरु\nकसैको लामग कुनै लाि उठाएमा िा त्र्स्तो लाि उठाउने मनर्तले कुनै काम गराएमा िा\nमनजलाई कुनै काम गनबय ाट रोके मा आपरामधक लाि मलएको मामननेछ।\n(३) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई देिार् बमोत्तजम सजार्\nिनु ेछाः-\n(क) आपरामधक लाि मलने मनर्तले कसैको ज्र्ान मलने, अङ्गिङ्ग गने िा\nगम्िीर चोट पर्ु ायउने डर िा रास देिाएमा सात िषसय म्म कै द र\nसिरी िजार रुपैर्ासाँ म्म जररबाना,\n(ि) कसैको व्र्िसार्मा गैर कानूनी तररकाले कुनै िमत पर्ु ायउने िा\nचरररमा झठु ो दोष लगाउने मनर्तले डर, रास देिाई आपरामधक\nलाि मलएमा तीन िषसय म्म कै द र तीस िजार रुपैर्ााँसम्म\nजररबाना,\n(ग) िण्ड (क) िा (ि) मा लेत्तिएदेत्ति बािेक अन्र् अिस्थामा\nआपरामधक लाि मलएमा एक िषसय म्म कै द र दश िजार\nरुपैर्ााँसम्म जररबाना।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२५४", "title": "िमतपूमताःय र्स पररच्छेद बमोत्तजमको कसूरबाट कसैलाई िामन, नोक्सानी पगु ेको रिेछ िने", "content": "त्र्स्तो कसूरदारबाट हिगो िुलेकोमा मबगो असूल गरी पीमडतलाई िराई ठदन ु पनेछ र\nहिगो निुलेकोमा पीमडतलाई मनामसब िमतपूमत य िराई ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२५५", "title": "िदम्र्ादाः र्स पररच्छेद अन्तगतय का कसूरमा त्र्स्तो कसूर िएको कुरा थािा पाएको", "content": "मममतले एक िष य नाघे पमछ उजरु लागने छैन।\n103\nwww.lawcommission.gov.np\nपररच्छेद-२२\nमद्रु ा सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२५६", "title": "िोटा मद्रु ा बनाउन निनु ेाः (१) कसैले िोटा मद्रु ा बनाउन िा बनाउने उद्योग गन य", "content": "िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई मद्रु ाको पररमाण\nर मूल्र् हिचार गरी पााँच िषदय ेत्ति दश िषसय म्म कै द र पचास िजार रुपैर्ााँदेत्ति एक लाि\nरुपैर्ााँसम्म जररबाना िनु ेछ।\nस्पष्‍ट टीकरणाः र्स पररच्छेदको प्रर्ोजनका लामग,–\n(क) “मद्रु ा” िन् नाले सबै हकमसमको करेन्सी नोट, पोस्टल अडरय , पोस्टल\nनोट, मनी अडरय , चेक, ड्राफ्ट, रािलस य चेक, प्रमततपर, हिमनमर्पर,\nप्रमतज्ञापर, क्रे मडट काड य सम्झन ु पछ य र सो शब्दले बैङ्कले\nआिश्र्कता अनसु ार सािजय मनक सूचना प्रकाशन र प्रसारण गरी\nतोहकठदएको अन्र् र्स्तै प्रकारका मौठद्रक उपकरण समेतलाई\nजनाउाँछ।\n(ि) “िोटा मद्रु ा” िन् नाले नेपाल सरकार िा नेपाल राष्‍ट र बैङ्क िा\nहिदेशी सरकार िा अमधकार प्राप्त हिदेशी संस्थाले मनकालेको िो\nिन् ने िान पाने िा हिश्ि ास िनु े गरी अनमधकृ त रुपमा बनाएको िा\nनक् कली मद्रु ा सम्झन ु पछ।य", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२५७", "title": "िोटा मद्रु ा चलन गन य निनु ेाः (१) कसैले िोटो मद्रु ा िो िन् ने जानीजानी सद्द े सरि चलन", "content": "गने मनर्तले त्र्स्तो मद्रु ा िररद िा मबक्री गन,य मनकासी िा पैठारी गन,य लेनदेन गन,य सद्द े\nसरि चलनमा ल्र्ाउन िा त्र्सको उद्योग गन य िा आफू साँग राख् न िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई सात िषसय म्म\nकै द र सिरी िजार रुपैर्ााँसम्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२५८", "title": "िोटा मद्रु ा बनाउने सामान बनाउन, राख्न िा ममतय गन य निनु ेाः (१) िोटा मद्रु ा बनाउन िा", "content": "बनाउने काममा प्रर्ोग िन्ु छ िन् ने जानीजानी िा हिश्ि ास गने मनामसब कारण िई कसैले\nकुनै औजार िा अन्र् कुनै सामान बनाउन, ममतय गन,य िररद मबक्री गन,य ठदन मलन िा\nमनकासी िा पैठारी गन य िा आफू साँग राख् न िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई सात िषसय म्म\nकै द र सिरी िजार रुपैर्ााँसम्म जररबाना िनु ेछ।\n104\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२५९", "title": "मापदण्ड हिपरीत मद्रु ा बनाउन निनु ेाः (१) प्रचमलत कानून बमोत्तजम मद्रु ा बनाउने", "content": "अमधकार पाएको कुनै अमधकारी िा व्र्त्तिले जानीजानी कानूनद्वारा मनधायररत मापदण्ड\nहिपरीत िनु े गरी मद्रु ा बनाउन, मद्रु ा बनाउने शत य बन्देज हिपरीत मद्रु ा बनाउन, बनाउन ु\nपनेिन्दा बढी पररमाणमा मद्रु ा बनाउन िा त्र्सरी फरक पारी बनाउने मनर्तले कुनै काम\nगन य िा त्र्सबाट आफू लाई िा अरु कसैलाई लाि पर्ु ायउन िा त्र्स्तो काममा सिर्ोग\nपर्ु ायउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई सात िषसय म्म\nकै द र सिरी िजार रुपैर्ााँसम्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२६०", "title": "मद्रु ा बनाउने औजार बाहिर लैजान निनु ेाः (१) कानून बमोत्तजम अमधकार प्राप्त", "content": "अमधकारीको आदेशले बािेक कसैले मद्रु ा बनाउने र्न्र िा उपकरण िा अन्र् सामिी\nमद्रु ा बनाउने ठाउाँबाट बाहिर लैजान िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई पााँच िषसय म्म\nकै द र पचास िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२६१", "title": "मद्रु ाको तौल घटाउन िा रुप िदल्न निनु ेाः (१) सद्दे सरि व्र्ििारमा चलाउने मनर्तले", "content": "िा सो िनु सक्छ िन् ने जानीजानी कसैले धातबु ाट बनेको मद्रु ाको तौल घटाउन िा\nधातकु ो अंश फरक पान य िा एक हकमसमको मद्रु ालाई अको हकमसमको मद्रु ा िो िन् ने िान\nपाने गरी मनकासी िा पैठारी गन य िा आफू साँग राख् न िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई पााँच िषसय म्म\nकै द र पचास िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२६२", "title": "रोक लगाइएको मद्रु ा चलन चल्तीमा ल्र्ाउन निनु ेाः (१) चलन चल्तीमा रिेको मद्रु ालाई", "content": "चलन चल्तीमा ल्र्ाउन रोक लगाउने गरी कानून बमोत्तजम अमधकार प्राप्त अमधकारीको\nआदेश िएकोमा त्र्स्तो आदेश प्रमतकू ल िनु े गरी त्र्सरी रोक लगाइएको मद्रु ा चलन\nचल्तीमा ल्र्ाउन, लेनदेन गन य िा राख् न िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक िषसय म्म\nकै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ र त्र्सरी चलन चलाएको,\nलेनदेन गरेको िा रािेको मद्रु ा समेत जफत िनु ेछ।\n\n२६२क. िौमतक मद्रु ाको प्रर्ोग गन य निनु े: (१) नेपाल राष्‍ट र बैङ्कले जारी गने मद्रु ा बािेक कसैले\nपमन नेपालमा प्रर्ोग गने, गराउने िा नेपालमिर िा बाहिरको व्र्ािसाहर्क कारोबारको\n सम्पत्ति शद्धु ीकरण (मनी लाउण्डररङ्ग) मनिारण तथा व्र्ािसाहर्क िातािरण प्रिद्धयन सम्बन्धी के िी ऐनलाई\nसंशोधन गने ऐन, २०८० द्वारा थप।\n105\nwww.lawcommission.gov.np\nििु ानी मलने, ठदने िा हिसाब ममलान गने िा अन्र् कुनै प्रर्ोजनको लामग मद्रु ाको नाम\nमलई िा नमलई अिौमतक (िचअयु ल) मद्रु ाको उत्पादन, मबक्री, कारोबार, सटिी िा\nस्थानान्तरण गन,य राख् न (िोल्ड गन)य िा त्र्स्तो मद्रु ा जारी िा िस्तान्तरण गन य िा गराउन\nिाँदु ैन।\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनको लामग \"अिौमतक (िचअयु ल) मद्रु ा\" िन् नाले\nहक्रप्टोिाफी िा अन्र् कुनै तररकाले मसजनय ा िा उत्पादन गररएको हिद्यतु ीर् माध्र्मबाट\nमूल्र् दशायउने िा मूल्र्को प्रमतमनमधत्ि गने व्र्ापाररक हक्रर्ाकलापमा मित्ि िा उपादेर्ता\nरिेको िा मूल्र् िा िाताको एकाइमा सत्तित िा िण्डारण गन य सहकने सूचना, कोड िा\nसङ्केत नम्बर, टोकन, हक्रप्टो करेन्सी िा र्स्तै हकमसमको िचअयु ल सम्पत्ति सम्झन ु पछय।\n(२) उपदफा (१) हिपरीत कसैले कुनै व्र्ािसाहर्क कारोबारको िास्तहिक\nहिसाब हकताब नदेत्तिने गरी सो सम्बन्धी रकम कुनै पमन माध्र्मबाट ििु ानी मलने ठदने\nगन यु िाँदु ैन।\n(३) कसैले उपदफा (१) िा (२) बमोत्तजमको कसूर गरेमा मबगो र सोबाट बढे\nिा बढाएको सम्पत्ति समेत जफत गरी पााँच िषसय म्म कै द र मबगो बमोत्तजम जररबाना\nिनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२६३", "title": "बैङ्क नोट िा मसक्क ा जलाउन, गाल्न, च्र्ात्न िा बैङ्क नोटमा लेख्न निनु ेाः (१) अमधकार प्राप्त", "content": "अमधकारीको आदेश हिना कसैले मद्रु ाको रुपमा िाह्य िएको बैङ्क नोट िा मसक् कालाई\nजलाउन िा त्र्सलाई काम नलागने गरी गाल्न िा च्र्ात्न िाँदु ैन।\n(२) कसैले बैङ्क नोटमा लेख् न िा कोन य िाँदु ैन।\n(३) उपदफा (१) िा (२) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन\nमहिनासम्म कै द र पााँच िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२६४", "title": "झरु ो बैङ्क नोट दरुु पर्ोग गन य निनु ेाः (१) मद्रु ाको रुपमा िाह्य िएको बैङ्क नोट झरु ो िई", "content": "िा अिर, त्तचह्न िा आकार नत्तचमनने िई िा अन्र् कुनै कारणले चलन चल्तीमा ल्र्ाउन\nनिनु े िई सडाउने िा जलाउने ठिर िएका झरु ा नोटिरु कानून बमोत्तजम अमधकार प्राप्त\nअमधकारीको आदेशले जलाउने िा सडाउने कतव्य र् िएको व्र्त्तिले त्र्स्तो बैङ्क नोट\nचलन चल्तीमा ल्र्ाउन िा त्र्सबाट कुनै हकमसमको लाि पाउने िदमनर्तले नजलाई िा\nनसडाई राख् न िा कसैलाई ठदन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द र तीस िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\n106\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२६५", "title": "जफत िनु ेाः र्स पररच्छेद बमोत्तजमको कसूर गन य प्रर्ोग िएको मद्रु ा, औजार, उपकरण िा", "content": "र्न्र र त्र्ससाँग सम्बत्तन्धत सामिी जफत िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२६६", "title": "िदम्र्ादाः र्स पररच्छेद अन्तगतय को कसूरमा त्र्स्तो कसूर िएको कुरा थािा पाएको", "content": "मममतले एक िष य नाघेपमछ उजरु लागने छैन।\nपररच्छेद-२३\nहटकट सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२६७", "title": "िोटा हटकट बनाउन िा चलन गन य निनु ेाः (१) कसैले सद्दे सरि चलन गने मनर्तले", "content": "िोटा हटकट बनाउन िा बनाउने उद्योग गन,य िररद मबक्री गन,य लेनदेन गन य िा मनकासी\nिा पैठारी गन य िा सद्दे सरि चलन गन य िा त्र्स्तो गन य उद्योग गन य िा आफू साँग राख् न\nिाँदु ैन।\nस्पष्‍ट टीकरणाः र्स पररच्छेदको प्रर्ोजनका लामगाः\n(क) “हटकट” िन् नाले िलु ाक हटकट िा मलितमा टााँमसने राजस्ि\nसम्बन्धी अन्र् हटकट सम्झन ु पछ य र सो शब्दले िाम, िलु ाक पर\nिा अरु कुनै िस्तमु ा लगाइएको िा छाहपएको हटकटको मनस्सा िा\nहटकटको प्रर्ोजनका लामग प्रर्ोग िनु े त्तस्टकर समेतलाई\nजनाउाँछ।\n(ि) “िोटा हटकट” िन् नाले िण्ड (क) मा उल्लेि गररए बमोत्तजमको\nहटकट िो िन् ने िान पाने गरी अनमधकृ त रुपमा बनाएको नक् कली\nहटकट सम्झन ु पछय र सो शब्दले एकपटक प्रर्ोग िइसके को\nहटकट समेतलाई जनाउाँछ।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई पााँच िषसय म्म\nकै द र पचास िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२६८", "title": "िोटा हटकट बनाउने औजार िररद, मबक्री, ममतय इत्र्ादी गन य निनु ेाः (१) िोटा हटकट", "content": "बनाउने काममा प्रर्ोग िन्ु छ िन् ने जानीजानी िा हिश्ि ास गन यु पने मनामसब कारण िई\nकसैले कुनै औजार िा अन्र् कुनै सामान बनाउन, ममतय गन,य िररद मबक्री गन,य लेनदेन\nगन य िा आफू साँग राख् न िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई पााँच िषसय म्म\nकै द र पचास िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२६९", "title": "प्रर्ोग िएको हटकट पनु ाः प्रर्ोगमा ल्र्ाउन निनु ेाः (१) एक पटक प्रर्ोग िइसके को", "content": "हटकट िो िन् ने जानीजानी त्र्स्तो हटकट कसैले पनु ाः सद्दे सरि प्रर्ोग गन,य सद्दे सरि\n107\nwww.lawcommission.gov.np\nप्रर्ोग गने मनर्तले हटकटमा लागेको छाप िा त्तचह्न मेट्न, िुकयन िा उडाउन िा त्र्सको\nउद्योग गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक िषसय म्म\nकै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२७०", "title": "सािजय मनक मलितमा प्रर्ोग िएको हटकट उप्काउन निनु ेाः (१) कसैले कुनै सािजय मनक", "content": "मलितमा प्रर्ोग िएको कुनै हटकट उप्काउन िा उप्काउने उद्योग गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई छ महिनासम्म\nकै द िा पााँच िजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२७१", "title": "जफत िनु ेाः र्स पररच्छेद बमोत्तजमको कसूर गन य प्रर्ोग िएको हटकट, औजार, उपकरण", "content": "िा त्र्ससाँग सम्बत्तन्धत सामिी जफत िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२७२", "title": "िदम्र्ादाः र्स पररच्छेद अन्तगतय को कसूरमा त्र्स्तो कसूर िएको कुरा थािा पाएको", "content": "मममतले एक िष य नाघेपमछ उजरु लागने छैन।\nपररच्छेद-२४\nनापतौल सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२७३", "title": "नाप्ने िा तौलने साधन नक्क ली बनाउन िा चलन गन य निनु ेाः (१) कसैले नाप्ने, तौलने िा", "content": "गणु स्तर मनधायरण गने कुनै साधन मनधायररत स्तरिन्दा घटी बढी िनु े गरी बनाउन िा\nबनाउन लगाउन िा त्र्सरी बनाएको नाप्ने, तौलने, गणु स्तर मनधायरण गने साधन जानीजानी\nसक् कली सरि चलन गन य िा चलन गने मनर्तले राख् न िा मबक्री गन य िा त्र्स्तो साधनमा\nलगाउने छाप िा टााँचा नक् कली बनाउन िा नाप्ने, तौलने िा गणु स्तर मनधायरण गने\nसाधनको छाप िा टााँचा हिगान य िा अको कुनै साधनको मद्दतले त्र्स्तो साधनको नाप्ने,\nतौलने िा गणु स्तर मनधायरण िमतामा प्रिाि पान य िा त्र्स्तो साधनमा नक् कली छाप िा\nटााँचा लगाउन िा अन्र् कुनै उपार्द्वारा चलन चल्तीको नाप िा तौललाई घटी बढी िनु\nसक्ने बनाउन िाँदु ैन।\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनको लामग “नाप्ने, तौलने िा गणु स्तर मनधायरण गने\nसाधन” िन् नाले कुनै िस्त ु िा सेिाको इकाई, गणु िा पररमाण िा त्र्स्तो बस्त ु िा सेिाको\nशद्धु ता िा स्तर िा कुनै िस्तकु ो इकाई मनधायरण गन य कानून बमोत्तजम चलन चल्तीमा\nरिेको साधन सम्झन ु पछ।य\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द र तीस िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\n108\nwww.lawcommission.gov.np\n(३) उपदफा (१) बमोत्तजम बनाएको, चलन चल्तीमा ल्र्ाएको साधन, त्र्सलाई\nबनाउने िा ममतय गने औजार समेत जफत िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२७४", "title": "नाप्ने, तौलने िा गणु स्तर मनधारय ण गने साधन कपटपणू य प्रर्ोग गन य निनु ेाः (१) कसैले कुनै", "content": "व्र्िसार्, कारोबार िा व्र्ापारको मसलमसलामा नाप्ने, तौलने िा गणु स्तर मनधायरण गने\nसाधन प्रर्ोग गन यु पदाय कानून बमोत्तजम त्र्स्तो साधनको चलन चल्तीमा मनधायरण गररएको\nनाप, तौल िा स्तरिन्दा घटी बढी िनु े गरी कपटपणू य रुपमा प्रर्ोग गन,य अको कुनै साधन\nिा उपार्को मद्दतले त्र्स्तो साधनको चलन चल्तीको नाप्ने, तौलने िा गणु स्तर मनधायरण\nगने कुरामा प्रमतकू ल प्रिाि पान य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द र तीस िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२७५", "title": "िदम्र्ादाः र्स पररच्छेद अन्तगतय को कसूरमा त्र्स्तो कसूर िएको कुरा थािा पाएको", "content": "मममतले तीन महिना नाघेपमछ उजरु लागने छैन।\nपररच्छेद-२५\nमलित सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२७६", "title": "कीते गन य निनु ेाः (१) कसैले कीते गन य िा गराउन िाँदु ैन।", "content": "(२) उपदफा (१) को प्रर्ोजनको लामग कसैले सिसय ाधारण िा कसैलाई कुनै\nिामन, नोक्सानी िा िमत पर्ु ाउय ने िा आफू िा कसैलाई कुनै लाि पर्ु ायउने मनर्तले कुनै\nझठ्ठु ा मलित िा झठ्ठु ा हिद्यतु ीर् अमिलेि िा मलित िा हिद्यतु ीर् अमिलेिको झठ्ठु ा अंश िा\nिाग बनाउने काम गरेमा मनजले कीते गरेको मामननेछ।\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनका लामग,–\n(क) “मलित” िन् नाले मलितमा लागेको सिी, औठँ ा छाप, छाप र मलितमा\nजमनएको अङ्क, अिर, मममत िा अन्र् कुनै व्र्िोरा सम्झन ु पछ।य\n(ि) “झठ्ठु ा मलित बनाउने काम” िन् नाले देिार्को कुनै काम सम्झन ु पछयाः-\n(१) जनु अमधकारी िा व्र्त्तिले मलित बनाएको, लेिेको िा सिीछाप\nगरेको िोइन त्र्स्तो अमधकारी िा व्र्त्तिले मलित बनाएको,\nलेिेको िा सहिछाप गरेको िो िन् ने हिश्ि ास पाने हकमसमबाट\nबेइमानीपूिकय मलित िा त्र्सको अंश तर्ार गने, हिद्यतु ीर्\nअमिलेि तर्ार गने िा पठाउने, हिद्यतु ीर् अमिलेिमा मडत्तजटलिरु\nसंरिण गने,\n109\nwww.lawcommission.gov.np\n(२) हिना अमधकार िा िेइमानीपूिकय कुनै मलित िा हिद्यतु ीर्\nअमिलेिमा कुनै कुरा थपी, मेटी, के री, पररितनय गरी िा अन्र् कुनै\nहकमसमबाट व्र्िोरा फरक िा नबत्तुझने पाने,\n(३) मानमसक अस्िस्थताको कारणबाट िोस ठेगानमा निएको, मादक\nपदाथ य िा लागू पदाथ य सेिन गरेको िा छलकपटमा पाररएको\nकारणले कसैले मलितमा लेत्तिएको कुराको मतलि बिु m्न सक्दैन\nिन् ने जानीजानी त्र्स्तो व्र्त्तिलाई मलित बनाउन, सहिछाप गन य\nिा मलितमा लेत्तिएको कुनै कुरा बदल्न लगाउने,\n(४) एक कामको लामग सिीछाप गरी मलफा, कागज िा छाप मलए\nठदएकोमा त्र्स्तो काममा नलगाई अकै प्रर्ोजनको मलित िडा\nगने िा सोमा लगाउने।\n(३) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई देिार् बमोत्तजमको सजार्\nिनु ेछाः-\n(क) राष्‍ट रपमतबाट प्रमाणीकरण िएको मलित कीते गनेलाई दश\nिषसय म्म कै द र एक लाि रुपैर्ासाँ म्म जररबाना,\n\n(क१) प्रदेश प्रमिु बाट प्रमाणीकरण िएको मलित कीते गनेलाई िण्ड\n(क) बमोत्तजमको कै द र जररबाना,\n(ि) अदालतको फै सला िा आदेश कीते गनेलाई आठ िषसय म्म कै द र\nअसी िजार रुपैर्ााँसम्म जररबाना,\n(ग) िण्ड (क) र (ि) मा लेत्तिएदेत्ति बािेक अन्र् सरकारी िा\nसािजय मनक मलित कीते गनेलाई सात िषसय म्म कै द र सिरी\nिजार रुपैर्ासाँ म्म जररबाना,\n(घ) िण्ड (क), (ि) र (ग) मा लेत्तिएदेत्ति बािेक अन्र् कुरा कीते\nगनेलाई पााँच िषसय म्म कै द र पचास िजार रुपैर्ााँसम्म\nजररबाना।\n(४) कसैले कीते गरी प्राप्त गरेको सम्पत्ति मलई मामससके को रिेछ िने मनजलाई\nउपदफा (३) बमोत्तजमको सजार्को अमतररि हिगो बमोत्तजमको थप जररबाना समेत\nिनु ेछ।\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा थप।\n110\nwww.lawcommission.gov.np\n(५) कसैले कीते गरी कुनै सम्पत्ति प्राप्त गरेको रिेछ िने मनजले त्र्स्तो सम्पत्ति\nसम्बत्तन्धत धनीलाई हफताय गन यु पनेछ र त्र्स्तो सम्पत्ति मामससके को रिेछ िने\nकसूरदारको अन्र् जार्जातबाट त्र्सको मबगो धनीलाई िराई ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२७७", "title": "कीते मलित सद्द े सरि राख्न िा व्र्ििारमा ल्र्ाउन निनु ेाः (१) कीते मलित िो िन् ने", "content": "जानीजानी िा हिश्ि ास गन यु पने मनामसब कारण िई कसैले बेइमानीपूिकय त्र्स्तो मलित\nसद्दे सरि व्र्ििार गने मनर्तले साथमा राख् न ु िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द र तीस िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\n(३) कीते मलित िो िन् ने जानीजानी िा हिश्ि ास गन यु पने मनामसब कारण िई\nकसैले त्र्स्तो मलित सद्दे सरि व्र्ििारमा ल्र्ाएमा मनजलाई त्र्स्तो मलित कीते गरे\nसरिको सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२७८", "title": "कीते मलित बनाउने औजार बनाउन निनु ेाः (१) कसैले कीते मलित िडा गने िा", "content": "बनाउने काममा प्रर्ोग गने मनर्तले िा त्र्स्तो काममा प्रर्ोग िनु सक्छ िन् ने जानीजानी\nिा हिश्ि ास गन यु पने मनामसब कारण िई कीते मलित बनाउने छाप िा अन्र् कुनै\nऔजार बनाउन, ममतय गन,य िरीद गन,य ठदन मलन िा आफू साँग राख् न ु िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई चार िषसय म्म\nकै द र चालीस िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२७९", "title": "जालसाजी गन य निनु ेाः (१) कसैले जालसाजी गन य िा गराउन िाँदु ैन।", "content": "(२) उपदफा (१) को प्रर्ोजनको लामग कीते मामनने कसूर बािेक कसैको िक\nमेट्ने, िदम्र्ाद, तारेि जान,े कुनै हकमसमले िामन, नोक्सानी गने िा कसैलाई िमत िा\nलाि पर्ु ायउने मनर्तले जानीजानी निए िा नगरेको कुरा िए गरेको िो िनी िा झठ्ठु ा\nमममत, अङ्क िा व्र्िोरा उल्लेि गरी मलित बनाएमा िा त्र्स्तो मलितमा सिीछाप गरे िा\nगराएमा िा आफ्नो िक निएको कुरामा िक िएको देिाई कुनै काम गरेमा\nजालसाजीको कसूर गरेको मामननेछ।\n(३) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द िा तीस िजार रुपैर्ााँेाँसम्म जररबाना िा दिु ै सजार् िनु ेछ।\n(४) कसैले जालसाजी गरी प्राप्त गरेको सम्पत्ति मलई मामससके को रिेछ िने\nमनजलाई उपदफा (३) बमोत्तजमको सजार्को अमतररि हिगो बमोत्तजमको थप जररबाना\nसमेत िनु ेछ।\n111\nwww.lawcommission.gov.np\n(५) कसैले जालसाजी गरी कुनै सम्पत्ति प्राप्त गरेको रिेछ िने मनजले त्र्स्तो\nसम्पत्ति सम्बत्तन्धत धनीलाई हफताय गन यु पनेछ र त्र्स्तो सम्पत्ति मामससके को रिेछ िने\nकसूरदारको अन्र् जार्जातबाट त्र्सको मबगो धनीलाई िराई ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२८०", "title": "जालसाजी मलित सद्द े सरि व्र्ििारमा ल्र्ाउन निनु ेाः (१) कसैले जालसाजी मलित िो", "content": "िन् ने थािा पाई िा थािा पाउन ु पने मनामसब कारण िई त्र्स्तो मलित सद्दे सरि\nव्र्ििारमा ल्र्ाउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई जालसाजी गरे\nसरिको सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२८१", "title": "ममतर्ार मानी सजार् िनु ेाः (१) कीते कागज िो िनी जानीजानी सािी बस्ने िा मलित", "content": "लेख् ने व्र्त्तिलाई कीते कसूरको ममतर्ार मामननेछ।\n\n(२) उपदफा (१) बमोत्तजमको ममतर्ारलाई दफा २७६ को उपदफा (३) मा\nउत्तल्लत्तित सजार्को आधा सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२८२", "title": "िमतपूमत य िराई ठदन ु पनेाः र्स पररच्छेद बमोत्तजमको कसूरबाट कसैलाई िामन, नोक्सानी,", "content": "िएकोमा कसूरदारबाट त्र्स्तो िामन, नोक्सानी िएको व्र्त्तिलाई मनामसब िमतपूमत य िराई\nठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२८३", "title": "िदम्र्ादाः सािजय मनक मलित कीते गरेकोमा थािा पाएको मममतले दईु िष य र र्स पररच्छेद", "content": "अन्तगतय को अन्र् कसूरमा त्र्स्तो कसूर िएको कुरा थािा पाएको मममतले छ महिना\nनाघेपमछ उजरु लागने छैन।\nपररच्छेद-२६\nआपरामधक प्रिेश तथा आपरामधक उपद्रि सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२८४", "title": "आपरामधक प्रिेश गन य निनु ेाः (१) कसैले कसैको सम्पत्तिमा आपरामधक प्रिेश गन य िा", "content": "गराउन िाँदु ैन।\n(२) उपदफा (१) को प्रर्ोजनको लामग कसैले देिार्को कुनै काम गने मनर्तले\nिूल िज्ु जत गरी िा नगरी अनमधकृ त रुपमा अकाकय ो स्िाममत्ि िा कब्जामा रिेको कुनै\nसम्पत्तिमा त्र्स्तो व्र्त्तिको अनमु मत नमलई प्रिेश गरेमा िा अनमु मत मलई प्रिेश गरेकोमा\nत्र्स्तो कुनै काम गने मनर्तले सो सम्पत्तिमा बमसरिेमा, ओगटेमा िा सम्पत्ति उपिोग गरी\nरिेमा मनजले आपरामधक प्रिेश गरेको मामननेछाः-\n(क) कुनै कसूर गने, िा\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा संशोमधत।\n112\nwww.lawcommission.gov.np\n(ि) जनु व्र्त्तिको स्िाममत्ि िा कव्जामा सम्पत्ति रिेको छ त्र्स्तो\nव्र्त्तिलाई डररास देिाउने, अपमान गने िा त्तझझ्र्ाउने।\n(३) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई देिार् बमोत्तजमको सजार्\nिनु ेछाः-\n(क) उपदफा (२) को िण्ड (क) को प्रर्ोजनका लामग आपरामधक\nप्रिेश गनेलाईय त्र्स्तो कसूरको उद्योग गरे सरिको सजार्,\n(ि) उपदफा (२) को िण्ड (ि) को उद्देश्र्ले कुनै सरकारी\nकार्ायलर् िा मामनस बसोबास गरेको घरमा प्रिेश गरेको िए छ\nमहिनासम्म कै द िा पााँच िजार रुपैर्ासाँ म्म जररबाना िा दिु ै\nसजार्।\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनको लामगाः\n(१) अस्थार्ी बसोबास गरेको ठाउाँलाई पमन घर मामननेछ।\n(२) सनातनदेत्ति प्रर्ोग गदै आएको बाटो, मनकास, पानीघाट, मसाँचाईको\nकुलो, मसानघाट, देिालर्मा प्रिेश गरेको िा प्रर्ोग गरेकोमा\nआपरामधक प्रिेश गरेको मामनने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२८५", "title": "आपरामधक उपद्रि गन य निनु ेाः (१) कसैले आपरामधक उपद्रि गन य िा गराउन िाँदु ैन।", "content": "(२) उपदफा (१) को प्रर्ोजनको लामग कसैले देिार्को कुनै काम गरेमा मनजले\nआपरामधक उपद्रि गरेको मामननेछाः-\n(क) नेपाल सरकार, प्रदेश सरकार िा स्थानीर् ति, नेपाल सरकार,\nप्रदेश सरकार िा स्थानीर् तिको पूण य िा अमधकांश स्िाममत्ि िा\nमनर्न्रण रिेको सङ्गठठत संस्था, सिसय ाधारण िा कुनै व्र्त्तिलाई\nकुनै िामन, नोक्सानी िा िमत पर्ु ायउने मनर्तले िा त्र्स्तो िमत\nपगु न सक्छ िन् ने जानीजानी िा हिश्ि ास गन यु पने मनामसब कारण\nिई िा लापरबािी िा िेलचेक्र्र्ाइाँ गरी कुनै सरकारी, सािजय मनक\nिा मनजी सम्पत्ति नाश गरेमा िा त्र्सको मूल्र्, मित्ि िा\nउपर्ोमगता घट्ने कुनै काम गरेमा,\n(ि) सािजय मनक िा मनजी ढल, मनकास, कुलो, पधाँ ेरो, सडक, पलु िा कुनै\nसिार िा र्ातार्ातको साधन इत्र्ाठदको िामन, नोक्सानी िा\nअनत्तुचत िमत प¥ुर्ाएमा िा िमत पगु ने कुनै काम गरेमा िा सोको\n113\nwww.lawcommission.gov.np\nउपर्ोगमा जानीजानी कुनै हकमसमले बाधा अिरोध िामन, नोक्सानी\nिा अनत्तुचत िमत प¥ुर्ाएमा िा िमत पगु ने कुनै काम गरेमा,\n(ग) अमधकार प्राप्त अमधकारीको आदेशले बािेक सािजय मनक सहुिधाको\nलामग रात्तिएको कुनै सङ्केत िा त्तचह्न नासेमा, िटाएमा, मेटेमा िा\nमबगारेमा,\n(घ) झटु ो अफिाि फै लाएर िा अरुलाई धोका िनु े कुनै साधनको\nप्रर्ोग गरेर अकायको काम कारोबार िा व्र्िसार्मा बाधा प¥ुर्ाएमा\nिा अकायको व्र्ापारको ख्र्ामतलाई िमत प¥ुर्ाएमा,\n(ङ) अकायको त्तचठ्ठी, सूचना, पमुलन्दा िा अन्र् कुनै माल लकु ाएमा िा\nबदमनर्तसाथ हढलो पगु ने गराएमा।\n(३) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई देिार् बमोत्तजमको सजार्\nिनु ेछाः-\n(क) नेपाल सरकारले संरिण गरेको िा कानून बमोत्तजम संरत्तित कुनै\nिन्र्जन्त ु िा िनस्पमतको प्रजामतको अत्तस्तत्ि नै हिनाश गने\nउद्देश्र्ले रात्तष्‍ट रर् मनकुञ्ज िा आरि िा संरत्तित िेर, हिश्व सम्पदा\nसूचीमा समािेश िएका ऐमतिामसक िा परु ातात्तत्िक स्मारक िा\nस्तम्ि, ऐमतिामसक िा परु ातात्तत्िक मित्िका िस्त ु सङ्कलन गरी\nरात्तिएको स्थान िा सङ्क्ििालर्, ऐमतिामसक मलितिरु रात्तिएको\nअमिलेिालर्, जङ्गी िा प्रिरीको िातिमतर्ार तथा िरिजाना\nरात्तिएको सैमनक िा अधसय ैमनक घर िा ठाउाँ, सरु िण छापािाना,\nमसक् का टकमारी गने टक्सार, कारिाना, बैङ्क नोट छाप्ने िा थपु ाने\nनेपाल राष्‍ट र बैङ्कको गोदाममा आगो लगाएमा िा हिष्‍टफोटक पदाथ य\nप्रर्ोग गरेमा जन्मकै दको सजार् र हिगो बमोत्तजम जररबाना,\n(ि) िण्ड (क) मा लेत्तिए बािेकका ऐमतिामसक, परु ातात्तत्िक िा\nधाममकय स्मारक िा स्तम्ि, सािजय मनक िा सरकारी मित्िका\nकागजात रिेको ििन िा तिहिल रिेको अदालत, संिैधामनक\nमनकार्, नेपाल सरकार, प्रदेश सरकार िा स्थानीर् तिको कार्ायलर्\nिा नेपाल सरकार, प्रदेश सरकार िा स्थानीर् तिको पूण य िा\nअमधकांश स्िाममत्ि िा मनर्न्रण रिेको संस्था, हिदेशी कू टनीमतक\nमनर्ोग िा अन्तररात्तष्‍ट रर् िा अन्तरसरकारी संस्थाको कार्ायलर्मा\n114\nwww.lawcommission.gov.np\nआगो लगाई िा हिष्‍टफोटक पदाथ य प्रर्ोग गरी आपरामधक उपद्रि\nगरेको िए पााँच िषदय ेत्ति बाह्र िषसय म्म कै द र हिगो बमोत्तजम\nजररबाना,\n(ग) िण्ड (क) िा (ि) मा लेत्तिएदेत्ति बािेक अन्र् कुनै काम गरी\nकुनै सािजय मनक सम्पत्तिमा िमत पर्ु ायई आपरामधक उपद्रि गरेको\nिए चार िषसय म्म कै द र चालीस िजार रुपैर्ासाँ म्म जररबाना,\n(घ) कसैको घर, कार्ायलर् िा कुनै सम्पमतमा आगो लगाई िा\nहिष्‍टफोटक पदाथ य प्रर्ोग गरी आपरामधक उपद्रि गरेकोमा दईु\nिषदय ेत्ति पााँच िषसय म्म कै द र बीस िजारदेत्ति पचास िजार\nरुपैर्ााँसम्म जररबाना,\n(ङ) िण्ड (क), (ि), (ग) िा (घ) मा लेत्तिएदेत्ति बािेक अरु कुनै\nकाम गरी आपरामधक उपद्रि गरेको कारणले कसैलाई कुनै िामन,\nनोक्सानी िएकोमा तीन िषसय म्म कै द र तीस िजार रुपैर्ासाँ म्म\nजररबाना।\n(४) र्स दफा बमोत्तजमको कसूरबाट कसैलाई िामन, नोक्सानी िएमा िामन,\nनोक्सानी िएको हिगो बराबरको िमतपूमत य कसूरदारबाट पीमडतलाई िराई ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२८६", "title": "लटु हपट गन य निनु ेाः (१) कसैले लटु हपट गन यु िा गराउन ु िाँदु ैन।", "content": "(२) उपदफा (१) को प्रर्ोजनका लामग कसैले आफ्नो िक नपगु ने िा अन्र्\nकसैको स्िाममत्ि, त्तजम्मा िा मनर्न्रणमा रिेको सम्पत्ति चोरी िा ठगी गरेको अिस्थामा\nबािेक अरु कुनै हकमसमले जबजस्य ती गरी िा नगरी िोसी, धरपकड िा लछार पछार गरी\nिा त्र्स्तो गने धम्की ठदई लैजाने िा िामन, नोक्सानी गने मनर्तले कुनै काम गरेमा\nलटु हपट गरेको मामनने छ।\n(३) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई तीन महिनासम्म कै द िा\nलटु हपट गरेको हिगोको पच्चीस प्रमतशतसम्म जररबाना िा दिु ै सजार् िनु ेछ र लटु हपट\nिएको सम्पमतको हिगो कसूरदारबाट पीमडतलाई िराई ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२८७", "title": "कसूर गरी प्राप्त गरेको सम्पत्ति मलन निनु ेाः (१) कुनै कसूर गरी प्राप्त गरेको सम्पत्ति िो", "content": "िन् ने जानीजानी िा हिश्ि ास िनु े कुनै मनामसब कारण िई कसैले कुनै सम्पत्ति मलन, राख् न\nिा िरीद–मबक्री गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई पााँच िष य कै द\nिा पचास िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ ।\n115\nwww.lawcommission.gov.np\n(३) उपदफा (१) बमोत्तजम मलए रािेको िा िररद मबक्री गरेको सम्पत्ति सो\nसम्पत्तिको धनीलाई हफताय गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२८८", "title": "िदम्र्ादाः दफा २८४ र २८५ अन्तगतय को कसूर त्र्स्तो कसूर िएको मममतले छ", "content": "महिनामिर र दफा २८६ को अन्तगतय को कसूरमा सो िए गरेको मममतले तीन महिनामिर\nर र्स पररच्छेद अन्तगतय को अन्र् कसूर त्र्स्तो कसूर िएको कुरा थािा पाएको मममतले\nतीन महिना नाघेपमछ उजरु लागने छैन।\nपररच्छेद-२७\nपशपु िी सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२८९", "title": "गाई, गोरु मान य िा कुट्न निनु ेाः (१) कसैले गाई िा गोरु माने िा कुनै चोट पर्ु ायउने", "content": "मनर्तले कुनै काम गन यु िा गराउन ु िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कामबाट कुनै गाई िा गोरु मन य गएमा त्र्स्तो\nकसूर गने व्र्त्तिलाई तीन िष य सम्म कै द िनु ेछ।\n(३) कसैले गाई िा गोरुलाई कुटी अङ्गिङ्ग पारेमा मनजलाई छ महिनासम्म कै द\nर अन्र् चोट पर्ु ायएमा पचास िजार रुपैर्ासाँ म्म जररबाना िनु ेछ।\n(४) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापमन कसैले कुनै गाई िा\nगोरुले आफ्नो िा अरुको त्तजउ िा ज्र्ानमा पर्ु ायउन लागेको िमत बचाउन आिश्र्क\nपरेको कुनै काम गदा य त्र्स्तो गाई िा गोरु मन य गएमा िा त्र्स्तो गाई िा गोरुलाई कुनै\nचोट पगु न गएको रिेछ िने र्स दफा बमोत्तजम कसूर गरेको मामनने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२९०", "title": "पशपु िी प्रमत मनदयर्ी व्र्ििार गन य निनु ेाः (१) कसैले कुनै पशपु िीलाई कुटी, हिकायई िा", "content": "बोक्न सक्ने िमतािन्दा बढी िारी बोकाई िा सामथ्र्र्िन्दा बढी दौडाई िा रोग, घाउ,\nिहटरा िा अन्र् कुनै कारणबाट काम गन य असमथ य िएकोलाई काममा लगाई िा\nिामनकारक बस्त ु सेिन गराई िा अन्र् कुनै प्रकारले र्ातना ठदन िा आफू ले पालेको\nपशपु ंिी रोगी िा िद्धृ िएको कारणले सािजय मनक रुपमा छाड्न िा अन्र् कुनै हकमसमबाट\nमनदयर्ी िा क्रु र व्र्ििार गन य िाँदु ैन।\nतर पशपु िीलाई कुनै काम गन य मसकाउने, तामलम ठदने, त्र्सलाई आफ्नो कामप्रमत\nमनपणु बनाउने उद्देश्र्ले न्र्ूनतम बल प्रर्ोग गरी कुनै काम गन य िा पशपु िीलाई त्र्सको\nशारीररक िमता अनसु ार कुनै िारी बोकाउन िा दौडाउन बाधा पने छैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई तीन महिनासम्म\nकै द िा पााँच िजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।\n116\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२९१", "title": "सािजय ामनक स्थलमा पश ु िा पिी मान य निनु ेाः (१) र्स संहितामा अन्र्था व्र्िस्था", "content": "िएकोमा बािेक कसैले पमन कुनै पश ु िा पिीलाई परम्परादेत्ति बली ठदाँदै आएको\nधाममकय स्थल बािेक अन्र् कुनै पमन सािजय मनक स्थलमा मान यु िाँदु ैन।\nतर परम्परादेत्ति नै पश ु िा पिीको बध गन य चली आएको मेला, जारा, िाट िा\nमिोत्सि िा स्थानमा पश ु िा पिी मान य िाधा पने छैन।\nस्पष्‍ट टीकरणाः र्स दफाको प्रर्ोजनको लामग “सािजय मनक स्थल” िन् नाले बाटो, सडक, पलु ,\nचौर िा मामनस आित जाित गने ठाउाँ सम्झन ु पछ।य\n(२) उपदफा (१) बमोत्तजम बली ठदनपु दाय परम्परादेत्ति बली ठददै आएको\nधाममकय स्थल बािेक अन्र् सािजय मनक िा धाममकय स्थलमा पश ु िा पिीको बली ठदन सहकने\nछैन।\n(३) उपदफा (१) बमोत्तजम पश ु िा पछीको बली ठदनपु दाय पश ु िा पिीको\nबलीको हिकल्पमा िनु सक्ने अन्र् उपार् िएमा त्र्स्तो उपार् अिलम्बन गन यु पनेछ।\n(४) उपदफा (३) बमोत्तजमको उपार् अपनाउन सम्िि निई पश ु िा पिीको\nबली ठदन ु परेमा त्र्स प्रर्ोजनका लामग सम्बत्तन्धत धाममकय स्थलका व्र्िस्थापकले\nमनधायरण गरेको ठााँउमा र मनधायरण गरेको हिमध बमोत्तजम बली ठदने काम गन यु पनेछ।\n(५) र्स दफा बमोत्तजम कसूर गने िा गराउने व्र्त्तिलाई एक महिनासम्म कै द\nिा पााँच िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२९२", "title": "िदम्र्ादाः दफा २९० अन्तगतय को कसूरमा त्र्स्तो कसूर िएको मममतले र र्स पररच्छेद", "content": "अन्तगतय को अन्र् कसूरमा त्र्स्तो कसूर िएको कुरा थािा पाएको मममतले तीन महिना\nनाघेपमछ उजरु लागने छैन।\nिाग-३\nिैर्त्तिक गोपनीर्ता तथा प्रमतष्ठा हिरुद्वको कसूर\nपररच्छेद-१\nगोपनीर्ता हिरुद्धका कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२९३", "title": "अकाकय ो कुरा सन्ु न िा ध्िनी अङ्कन गन य निनु ेाः (१) कसैले दईु िा दईु िन्दा बढी", "content": "व्र्त्तििरुका मबचमा िएका कुनै कुरा अमधकार प्राप्त अमधकारीको अनमु मतले िा त्र्सरी\nकुरा गने व्र्त्तििरुको मञ्ज रु ी हिना कुनै र्ात्तन्रक उपकरणको प्रर्ोग गरेर सन्ु न िा\nत्र्स्तो कुराको ध्िनी अङ्कन गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई दईु िषसय म्म\nकै द िा बीस िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।\n117\nwww.lawcommission.gov.np\nतर सािजय मनक रुपमा गररएको िाषण िा ििव्र्को िकमा र्ो दफा लागू िनु े\nछैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२९४", "title": "गोप्र् कुरा प्रकट गन य निनु ेाः (१) कसैले आफ्नो व्र्ािसाहर्क कामको मसलमसलामा कुनै", "content": "व्र्त्तिबाट थािा पाएको मनजको कुनै गोप्र् कुरा कानूनले िाध्र् गराएको िा त्र्स्तो\nव्र्त्तिले अनमु मत ठदएको अिस्थामा बािेक कसैलाई पमन प्रकट गन य िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई एक िषसय म्म कै द िा दश\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२९५", "title": "अनमु मत हिना कुनै व्र्त्तिको तस्िीर त्तिच्न िा तस्िीरको स्िरुप मबगान य निनु ेाः (१) कसैले", "content": "कुनै व्र्त्तिको अनमु मत हिना मनजको तस्िीर त्तिच्न िा मनजको तस्िीरसाँग अरु कसैको\nतस्िीर रािी अको तस्िीर बनाउन िाँदु ैन।\nतर कसैले कुनै सािजय मनक स्थानको तस्िीर त्तिच्दा त्र्स्तो स्थानमा रिेको कुनै\nव्र्त्ति समेतको तस्िीर त्तित्तचन गएको रिेछ िने र्स दफा बमोत्तजम कसूर गरेको मामनने\nछैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक िषसय म्म\nकै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।\n(३) कसैले एकको तस्िीरको के िी िाग अको व्र्त्तिको अको िागसाँग रािी िा\nअन्र् कुनै हकमसमले हिकृ त रुपको तस्िीर बनाउन िा प्रकाशन गन य िाँदु ैन।\n(४) उपदफा (३) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई दईु िषसय म्म\nकै द िा बीस िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२९६", "title": "अनमु मत हिना एकको तस्िीर अरुलाई ठदन िा मबक्री गन य निनु ेाः (१) कसैले कुनै", "content": "व्र्त्तिको तस्िीर मनजको अनमु मत हिना अरुलाई ठदन िा मबक्री गन य िा मनजलाई\nत्तझझ्र्ाउन िा सताउने, िैरान पाने िा मनजबाट कुनै अनत्तुचत फाइदा मलने िा तस्िीरको\nव्र्ापाररक प्रर्ोग गरी फाइदा मलने मनर्तले प्रकाशन गन,य प्रचार िा िररद मबक्री गन य\nिाँदु ैन।\n(२) उपदफा (१) बमोत्तजको कसूर गने िा गराउने व्र्त्तिलाई तीन िषसय म्म\nकै द िा तीस िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२९७", "title": "त्तचठ्ठी िोल्न िा टेमलफोनमा गरेको कुरा सन्ु न निनु ेाः (१) अमधकार प्राप्त अमधकारी िा", "content": "सम्बत्तन्धत व्र्त्तिको अनमु मत हिना कसैको त्तचठ्ठी िोल्न िा अरुले टेमलफोनमा गरेको\nकुरा कुनै र्ात्तन्रक उपकरणको प्रर्ोग गरेर मबचमा सन्ु न िा ध्िनी अङ्कन गन य िाँदु ैन।\n118\nwww.lawcommission.gov.np\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई दईु िषसय म्म\nकै द िा बीस िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२९८", "title": "हिद्यतु ीर् माध्र्मद्वारा गोपनीर्ता िङ्ग गन य निनु ेाः (१) कसैले हिद्यतु ीर् माध्र्ममा रिेको िा", "content": "प्रिाि िनु े सूचना, जानकारी, पराचार अनमधकृ त रुपमा प्राप्त गन य त्र्सको गोपनीर्ता िङ्ग\nगन य िा अनमधकृ त रुपमा कसैलाई िस्तान्तरण गन य िा गराउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई दईु िषसय म्म\nकै द िा बीस िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२९९", "title": "छलकपटपणू य टेमलफोन िा सन्देश प्रिाि गन य निनु ेाः (१) कसैले आफ्नो पररचर् ठदई िा", "content": "नठदई कसैलाई छल्ने, धोका ठदने, िैरानी पाने िा सताउने उद्देश्र्ले छलकपटपूण य टेमलफोन\nिा सन्देश प्रिाि गन य गराउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई दईु िषसय म्म कै द िा बीस\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३००", "title": "िैरान पाने बठिर्तले त्तचठ्ठी पर लेख्न निनु ेाः (१) कसैलाई डर, रास िा दाःुि िा िैरानी", "content": "ठदने, अपमान िा बेइज्जत गने बदमनर्तले कुनै त्तचठ्ठी पर, पचाय िा अन्र् कुनै हकमसमको\nमलित लेिी, लेिाई िा हिद्यतु ीर् माध्र्मद्वारा धम्की ठदने, सताउने, त्तजस्क्र्ाउने िा अन्र्\nकुनै हकमसमले अनत्तुचत व्र्ििार गन य िा गराउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक िषसय म्म\nकै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३०१", "title": "अरुको शरीर िानतलासी गन य निनु ेाः (१) कानून बमोत्तजम अमधकार प्राप्त अमधकारी िा", "content": "मनजको आदेश िा सरु िाको प्रर्ोजनका लामग िहटएको व्र्त्तिले अमधकार प्राप्त\nअमधकारीको अनमु मतले बािेक कसैले सम्बत्तन्धत व्र्त्तिको स्िीकृ मत हिना अरुको शरीर,\nसिारी साधन िा मनजी प्रर्ोगका िस्तिु रुको िानतलासी गन य िा गराउन िाँदु ैन।\n(२) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक िषसय म्म\nकै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३०२", "title": "अरुको आिासमा अनामधकृत प्रिेश गन य निनु ेाः (१) कानून बमोत्तजम अमधकार प्राप्त", "content": "अमधकारी िा मनजको आदेशले बािेक कसैले अरुको घरमा सम्बत्तन्धत घर धनीको\nस्िीकृ मत हिना अनमधकृ त रुपमा प्रिेश गन,य घर धनी िा मनजको पररिारको गोप्र्ता िङ्ग\nगन य िा त्र्स्तो घरको िानतलासी गन य िा गराउन िाँदु ैन।\n119\nwww.lawcommission.gov.np\nस्पष्‍टट ीकरणाः र्स दफाको प्रर्ोजनका लामग “घर” िन् नाले कुनै व्र्त्तिले बसोबास गरेको\nघर, मनिास, आिास, कोठा सम्झन ु पछ य र सो शब्दले त्र्स्तो व्र्त्तिले रात हिताउने गरी\nबसेको िोटेल कोठा, त्तशहिर र पाल समेतलाई जनाउाँछ।\n(२) उपदफा (१) बमोत्तजमको कसूर गने व्र्त्तिलाई तीन िषसय म्म कै द िा तीस\nिजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३०३", "title": "िमतपूमत य िराई ठदन ु पनेाः र्स पररच्छेद बमोत्तजमको कसूर गरी कसैले कुनै लाि प्राप्त", "content": "गरेको िा कसैलाई कुनै हकमसमको िामन, नोक्सानी, िैरानी िा िमत पर्ु ायएको रिेछ िने\nकसूरबाट त्र्स्तो लाि, िामन, नोक्सानी, िैरानी िा िमतको िमतपूमत य समेत िराई ठदन ु\nपनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३०४", "title": "िदम्र्ादाः र्स पररच्छेद अन्तगतय को कसूरमा कसूर िए गरेको मममतले तीन महिना", "content": "नाघेपमछ उजरु लागने छैन।\nपररच्छेद-२\nगाली बेइज्जती सम्बन्धी कसूर", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३०५", "title": "गाली गन य निनु ेाः (१) कसैले कसैलाई गाली गन य िाँदु ैन।", "content": "(२) उपदफा (१) को प्रर्ोजनको लामग कसैले कसैलाई िोच्र्ाउने मनर्तले बोली\nिा िचनले अपमानजनक शब्द प्रर्ोग गरेमा मनजले गाली गरेको मामननेछ।\n(३) उपदफा (१) बमोत्तजमको कसूर गने िा गराउने व्र्त्तिलाई एक िषसय म्म\nकै द िा दश िजार रुपैर्ााँसम्म जररबाना िा दिु ै सजार् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३०६", "title": "बेइज्जती गन य निनु ेाः (१) कसैले कसैको बेइज्जती गन य िाँदु ैन।", "content": "(२) उपदफा (१) को प्रर्ोजनको लामग कसैले देिार् बमोत्तजमको काम गरेमा\nमनजले बेइज्जती गरेको मामननेछाः-\n(क) अरुको इज्जतमा धक्का पर्ु ायउने मनर्तले िा धक्का पगु न सक्छ िन् ने\nजानीजानी िा हिश्ि ास गने मनामसब कारण िई लेिेर, आचरण िा\nआकार िा त्तचह्न िा प्रचार प्रसारद्वारा िा अरु कुनै हकमसमबाट\nप्रत्र्ि िा अप्रत्र्ि रुपले त्र्स्तो व्र्त्तिलाई अरुको दृहष्टमा\nमनजको व्र्त्तिगत चररर, आचरण, नैमतकता िा ख्र्ामतलाई\nिोच्र्ाउने गरी चररर ित्र्ा गरेमा िा मनजको शरीर सामान्र्ताः\nघृत्तणत अिस्थामा छ िन् ने अरुलाई हिश्ि ास पने गरी दोष\nलगाएमा िा त्र्स्तो दोष लगाएको कुरा प्रचार, प्रसार िा प्रकाशन\n120\nwww.lawcommission.gov.np\nगरेमा िा कसैको बेइज्जती िनु े साधनको रुपमा प्रर्ोग गररएको\nकुनै त्तचज जानीजानी मबक्री िा मबतरण गरेमा,\n(ि) मतृ कलाई कुनै आिेप लगाइएकोमा त्र्स्तो आिपे लगाउाँदाका\nबित मनज जीहित रिेको िए मनजको इज्जतमा धक्का पगु ने रिेछ\nिन् ने जानीजानी मनजको पररिार िा नत्तजकको अन्र् नातेदारिरुको\nिािनामा चोट पर्ु ाउय ने मनर्तले कुनै आिेप लगाएकोमा,\n\n(ग) ...............\n(३) उपदफा (२) मा जनु सकु ै कुरा लेत्तिएको िए तापमन देिार्को कामलाई\nबेइज्जती मामनने छैनाः-\n(क) सिसय ाधारणको हितको लामग प्रमाण र आधार सहित कुनै\nव्र्त्तिसाँग सम्बत्तन्धत सााँचोेे कुरा प्रकाशन िा प्रशारण गन,यु\n(ि) कुनै राष्‍ट रसेिकले आफ्नो ओिदाको कतव्य र् पालना गदाय मनजको\nआचरणलाई मलएर िा त्र्स्तो आचरणबाट बत्तुझनेसम्मको मार\nमनजको चरररलाई मलएर असल मनर्तले मर्ायठदत ढङ्गबाट कुनै\nकुरा प्रकाशन गन,यु\n(ग) कुनै व्र्त्तिको सािजय मनक पद िा ओिोदाको मित्िसाँग सम्बन्ध\nराख् ने आचरण र त्र्स्तोेे आचरणबाट बत्तुझनेसम्मको मनजको\nचरररलाई मलएर असल मनर्तले कुनै हिचार प्रकट गन,यु\n(घ) कुनै कुरा गने व्र्त्तिले सिसय ाधारणको रार्को लामग कुनै कुरा\nपेश गरेकोमा त्र्स्तो कुराको गणु िा दोषलाई मलएर िा सो\nिदसम्म मार त्र्स्तो कुरा गने व्र्त्तिको चरररलाई मलएर असल\nमनर्तले मर्ायठदत ढङ्गबाट कुनै हिचार प्रकट गन,यु\n(ङ) कुनै व्र्त्तिको अको कुनै व्र्त्ति उपर कानूनद्वारा िा मनजसाँग\nिएको करारद्वारा कुनै अमधकार िएकोमा मनजले सो अमधकार\nसम्बन्धी काम कुरामा त्र्स्तो व्र्त्तिको आचरणमा असल मनर्तले\nकुनै िोट लगाउन,ु\n(च) कानून बमोत्तजम कुनै कसूरको अनसु न्धान गन यु िा त्र्स्तो\nआधारमा मनजलाई कानून बमोत्तजम अमिर्ोग लगाउन,ु\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा त्तझहकएको।\n121\nwww.lawcommission.gov.np\n(छ) कसैलाई मनजको हितको लामग, मनजको स्िाथ य िएको व्र्त्तिको\nहितको लामग िा सिसय ाधारणको हितको लामग अरु कुनै व्र्त्तिको\nहिरुद्ध सतकय पान,यु\n\n(ज) सािजय मनक हित, सदाचार िा नैमतकताको लामग असल मनर्तले\nकसैको कुनै कार्,य चररर िा आचरणको सम्बन्धमा व्र्ङ्क्गर् गन य\nिा आधार र कारण सहित कुनै हटप्पणी गन य िा कुनै कुरा\nप्रकाशन िा प्रसारण गन।य", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३०७", "title": "बेइज्जती गरेमा िनु े सजार्ाः (१) कसैले कसैको बेइज्जती गरे िा गराएमा मनजलाई दईु", "content": "िषसय म्म कै द िा बीस िजार रुपैर्ासाँ म्म जररबाना िा दिु ै सजार् िनु ेछ।\nतर हिद्यतु ीर् िा अन्र् आम सिारका माध्र्मबाट बेइज्जती गरे िा गराएमा\nत्र्स्तो सजार्मा थप एक िषसय म्म कै द र दश िजार रुपैर्ााँसम्म जररबाना िनु ेछ।\n(२) कसैले कसैलाई बेइज्जती गरे िा गराएको ठिररएमा बेइज्जती गररएको\nव्र्त्तिलाई कसूरको गम्िीरता, त्र्स्तो व्र्त्तिको प्रमतष्ठामा पन य गएको असर तथा हिद्यतु ीर्\nिा अन्र् आमसिारका माध्र्मबाट बेइज्जती गरेको िएमा त्र्स्तो कुरा समेतलाई हिचार\nगरी कसूरदारबाट मनामसब िमतपूमत य र त्र्स्तो व्र्त्तिलाई कसूरदारबाट मद्दु ामा लागेको\nिच य समेत िराउन ु पनेछ।\n(३) मररसके को कुनै व्र्त्तिलाई र्स पररच्छेद बमोत्तजम बेइज्जती गरेको\nठिररएमा कसूरदारबाट त्र्स्तो बेइज्जतीबाट िािनामा चोट लागेको मनजको नत्तजकको\nिकिालालाई त्र्स्तो िमतपूमत य र मद्दु ामा लागेको िचकय ो रकम िराई ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३०८", "title": "िदम्र्ादाः र्स पररच्छेद अन्तगतय को कसूर िएको कुरा थािा पाएको मममतले तीन महिना", "content": "नाघेपमछ उजरु लागने छैन।\n मलु कु ी संहिता सम्बन्धी के िी नेपाल ऐनलाई संशोधन गने ऐन, २०७५ द्वारा थप।\n122", "children": []}]}]$CODExd7ea9e8908$::jsonb,$CODEx17fe55698e$मुलुकी अपराध संहिता, २०७४_it7vg66.pdf$CODEx17fe55698e$) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, original_title=EXCLUDED.original_title, document_type=EXCLUDED.document_type, year_bs=EXCLUDED.year_bs, year_ad=EXCLUDED.year_ad, total_pages=EXCLUDED.total_pages, nodes=EXCLUDED.nodes, source_filename=EXCLUDED.source_filename;
